var e={tone:3,_encoded:`core,little_vespers,great_vespers,nocturns,matins,liturgy,vespers_weekday.sun,vespers_weekday.mon,vespers_weekday.tue,vespers_weekday.wed,vespers_weekday.thu,vespers_weekday.fri,compline.sun,compline.mon,compline.tue,compline.wed,compline.thu,compline.fri,compline.sat,matins_weekday.mon,matins_weekday.tue,matins_weekday.wed,matins_weekday.thu,matins_weekday.fri,matins_weekday.sat,liturgy_weekday.mon,liturgy_weekday.tue,liturgy_weekday.wed,liturgy_weekday.thu,liturgy_weekday.fri,liturgy_weekday.sat`.split(`,`),troparion:{text:`Let the heavens be glad; let earthly things rejoice; * for the Lord hath wrought might with His arm, * trampling down death by death; * becoming the first-born of the dead, * delivering us from the belly of Hades, ** and granting the world great mercy.`,tier:2,src:{file:`3-1.pdf`,locus:`Great Vespers, if-no-Vigil (CANONICAL print, §9.5 convention)`},provenance_note:`Verified word- and pointing-identical at all four print sites (LV dismissal, GV no-vigil, Matins God-is-the-Lord, Liturgy); quotation-mark variance at: none. Canonical field stores the GV print per the §9.5 ruling.`},dismissal_theotokion:{text:`We hymn thee who hast mediated the salvation of our race, * O Virgin Theotokos; * for thy Son and our God, * accepting suffering on the Cross in the flesh * He had received of thee, * hath delivered us from corruption, ** in that He is the Lover of mankind.`,tier:2,src:{file:`3-1.pdf`,locus:`Great Vespers, if-no-Vigil (verified identical at the Matins God-is-the-Lord site)`}},kontakion:{text:`Thou didst arise today, O merciful One, * and hast led us out from the gates of death. * Adam danceth today, and Eve rejoiceth. * The prophets also, along with patriarchs, ** ceaselessly praise the divine might of Thine authority.`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins after Ode VI (verified identical at the Liturgy site)`},spec_mel:`Today the Virgin`},ikos:{text:`Let heaven and earth dance today, and with one accord sing the praises of Christ our God, for He hath raised the prisoners from the tombs. All creation rejoiceth together as it offers fitting songs to the Creator of all things and our Redeemer. For today, as Giver of life, He draweth mortals out of Hades raising them to heaven. He layeth low the uprisings of the enemy and hath destroyed the gates of Hades by the divine might of His authority.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins, after Ode VI`},sourceLabel:`Ikos`},little_vespers:{rubric:`On “Lord, I have cried ...,” 4 Stichera:`,lic:[{text:`By Thy Cross, O Christ our Savior, * the dominion of death hath been abolished, * the devil’s deception hath been dispelled, * while mankind, saved by faith, ** each evening offers hymns unto Thee.`,tier:2,src:{file:`3-1.pdf`,locus:`Little Vespers, LIC sticheron position 1`}},{text:`By Thy Cross, O Christ our Savior, * the dominion of death hath been abolished, * the devil’s deception hath been dispelled, * while mankind, saved by faith, ** each evening offers hymns unto Thee.`,tier:2,src:{file:`3-1.pdf`,locus:`Little Vespers, LIC sticheron position 2`}},{text:`By Thy Resurrection, O Lord, * the universe hath been filled with light * and paradise hath been opened again, * while all creation, singing Thy praise, ** each evening offers hymns unto Thee.`,tier:2,src:{file:`3-1.pdf`,locus:`Little Vespers, LIC sticheron position 3`}},{text:`I glorify the power of the Father and the Son, * and I praise the authority of the Holy Spirit, * undivided, uncreated Godhead, * consubstantial Trinity, ** that reigneth from ages to ages.`,tier:2,src:{file:`3-1.pdf`,locus:`Little Vespers, LIC sticheron position 4`}}],lic_verses:[{text:`From the morning watch until night, from the morning watch * let Israel hope in the Lord.`,tier:2,src:{file:`3-1.pdf`,locus:`Little Vespers, LIC verse 1`}},{text:`For with the Lord there is mercy, and with Him is plenteous redemption; * and He shall redeem Israel out of all his iniquities.`,tier:2,src:{file:`3-1.pdf`,locus:`Little Vespers, LIC verse 2`}},{text:`O praise the Lord, all ye nations; * praise Him, all ye peoples.`,tier:2,src:{file:`3-1.pdf`,locus:`Little Vespers, LIC verse 3`}},{text:`For He hath made His mercy to prevail over us, * and the truth of the Lord abideth forever.`,tier:2,src:{file:`3-1.pdf`,locus:`Little Vespers, LIC verse 4`}}],lic_theotokion:{text:`O Greatest wonder: * a Virgin today giveth birth, * and that which is born is God before the ages. * Having revealed Thine ineffable birthgiving, * clearly that which was accomplished was beyond nature. * O fearsome mystery! * What was apprehended remaineth ineffable, * and that which was contemplated remaineth incomprehensible. * Blessed art thou, O most pure maiden, * daughter of Adam the earthborn, * and revealed as the Mother of the Most High. ** beseech Him that our souls be saved.`,tier:2,src:{file:`3-1.pdf`,locus:`Little Vespers, LIC Glory/Both-now Theotokion`}},prokeimenon:{ref:`shared.saturday_vespers_prokeimenon`,rubric:`The Prokeimenon: “The Lord is King ...,” with its verses.`},aposticha:{resurrection:[{text:`By Thy Passion, O Christ, * Thou didst darken the sun, * and by the light of Thy Resurrection * Thou hast made the whole universe radiant. * We beseech Thee to accept our evening hymn, ** O Lover of mankind.`,tier:2,src:{file:`3-1.pdf`,locus:`Little Vespers, aposticha Resurrection sticheron (as printed here — differs from the GV print, §2.2)`}}],theotokos:[{text:`O pure Virgin, * we know thee to be the spiritual ark * who for us bore the Tablets written by God, * the Lawgiver and Creator. ** Intercede with Him that our souls may be saved.`,tier:2,src:{file:`3-1.pdf`,locus:`Little Vespers, aposticha Theotokos sticheron 1`}},{text:`God the Word, who is by nature beyond understanding, * and who dwelt in thy womb taking flesh from thee, * hath revealed thee to be heaven upon earth, O pure Virgin, * wherefore thou, who knewest not wedlock, ** doth bedew all with immortal dew.`,tier:2,src:{file:`3-1.pdf`,locus:`Little Vespers, aposticha Theotokos sticheron 2`}},{text:`By thine intercessions we have gained salvation, * because through them, O Virgin, we ever escape from dangers * and the tempests of temptations, * wherefore we entreat thee, ** cease not to intercede on our behalf, that our souls may be saved.`,tier:2,src:{file:`3-1.pdf`,locus:`Little Vespers, aposticha Theotokos sticheron 3`}}],theotokos_verses:{ref:`shared.lv_theotokos_aposticha_verses`}},aposticha_theotokion:{text:`Through thee, O Mary most pure, * we have come to know regeneration * and a second life for our human nature: * for the Maker of creation who hath been kneaded within thy womb * and who hath raised us up from death and Hades, * hath granted us eternal life, * wherefore we cry out to thee, O Ever-virgin; * “Rejoice!, thou who hast joined together things below with those of heaven. * Rejoice!, the hope of all the ends of the earth, * our protection and intercession. * Rejoice!, thou who by the Resurrection of thy Son * maketh all things radiant ** granting unto the world His great mercy.”`,tier:2,src:{file:`3-1.pdf`,locus:`Little Vespers, aposticha Theotokion`}},closing_rubric:`“Now lettest Thou Thy servant depart ...,” Trisagion. Then:`,dismissal_rubric:`Glory ..., Both now ..., Theotokion: [marked WITHOUT a printed text — §9.6: resolution is an assembly question (Fekula/Theotokia tables), not a data gap]`},great_vespers:{rubric:`On “Lord I have cried ...,” 10 Stichera: 7 Resurrection Stichera and 3 of the saint of the day, or 4 and 6 if the Menaion service is of Polyeleos rank.`,lic:[{text:`By Thy Cross, O Christ our Savior, * the dominion of death hath been abolished, * the devil’s deception hath been dispelled, * while mankind, saved by faith, ** each evening offers hymns unto Thee.`,tier:2,src:{file:`3-1.pdf`,locus:`Great Vespers, LIC sticheron 1`}},{text:`By Thy Resurrection, O Lord, * the universe hath been filled with light * and paradise hath been opened again, * while all creation, singing Thy praise, ** each evening offers hymns unto Thee.`,tier:2,src:{file:`3-1.pdf`,locus:`Great Vespers, LIC sticheron 2`}},{text:`I glorify the power of the Father and the Son, * and I praise the authority of the Holy Spirit, * undivided, uncreated Godhead, * consubstantial Trinity, ** that reigneth from ages to ages.`,tier:2,src:{file:`3-1.pdf`,locus:`Great Vespers, LIC sticheron 3`}},{text:`We worship Thy precious Cross, O Christ, * and we praise and glorify Thy Resurrection, ** for by Thy wounds we have all been healed.`,tier:2,src:{file:`3-1.pdf`,locus:`Great Vespers, LIC sticheron 4`},provenance_note:`sub-group "Other Stichera, by Anatolius" (§4.3)`},{text:`We praise the Savior who took flesh from the Virgin; * for he was crucified for us and arose on the third day, ** granting unto us His great mercy.`,tier:2,src:{file:`3-1.pdf`,locus:`Great Vespers, LIC sticheron 5`},provenance_note:`sub-group "Other Stichera, by Anatolius" (§4.3)`},{text:`Descending down unto those in Hades, * Christ proclaimed the good tidings, exclaiming, * “Be of good cheer; for now I have conquered! * I am the Resurrection; * I shall raise you up, ** abolishing the gates of death.”`,tier:2,src:{file:`3-1.pdf`,locus:`Great Vespers, LIC sticheron 6`},provenance_note:`sub-group "Other Stichera, by Anatolius" (§4.3)`},{text:`We who stand unworthily in Thy most pure house * chant an evening hymn, * crying from the depths, * “O Christ God, who hath enlightened the world by Thy Resurrection on the third day, ** deliver Thy people from the hand of Thine enemies, O Lover of mankind.”`,tier:2,src:{file:`3-1.pdf`,locus:`Great Vespers, LIC sticheron 7`},provenance_note:`sub-group "Other Stichera, by Anatolius" (§4.3)`}],lic_verses:[{text:`Bring my soul out of prison * that I may confess Thy name.`,tier:2,src:{file:`3-1.pdf`,locus:`Great Vespers, LIC ladder verse 1`}},{text:`The righteous shall wait patiently for me * until Thou shalt reward me.`,tier:2,src:{file:`3-1.pdf`,locus:`Great Vespers, LIC ladder verse 2`}},{text:`Out of the depths have I cried unto Thee, O Lord; * O Lord, hear my voice.`,tier:2,src:{file:`3-1.pdf`,locus:`Great Vespers, LIC ladder verse 3`}},{text:`Let Thine ears be attentive * to the voice of my supplication.`,tier:2,src:{file:`3-1.pdf`,locus:`Great Vespers, LIC ladder verse 4`}},{text:`If Thou shouldest mark iniquities, O Lord, O Lord, who shall stand? * For with Thee there is forgiveness.`,tier:2,src:{file:`3-1.pdf`,locus:`Great Vespers, LIC ladder verse 5`}},{text:`For Thy name’s sake have I patiently waited for Thee, O Lord; my soul hath patiently waited for Thy word, * my soul hath hoped in the Lord.`,tier:2,src:{file:`3-1.pdf`,locus:`Great Vespers, LIC ladder verse 6`}},{text:`From the morning watch until night, from the morning watch * let Israel hope in the Lord.`,tier:2,src:{file:`3-1.pdf`,locus:`Great Vespers, LIC ladder verse 7`}}],lic_menaion_rubric:`Then the Stichera from the Menaion, with the following Verses:`,lic_menaion_verses:[{text:`For with the Lord there is mercy, and with Him is plenteous redemption; * and He shall redeem Israel out of all his iniquities.`,tier:2,src:{file:`3-1.pdf`,locus:`Great Vespers, Menaion-stichera verse 1`}},{text:`O praise the Lord, all ye nations; * praise Him, all ye peoples.`,tier:2,src:{file:`3-1.pdf`,locus:`Great Vespers, Menaion-stichera verse 2`}},{text:`For He hath made His mercy to prevail over us, * and the truth of the Lord abideth forever.`,tier:2,src:{file:`3-1.pdf`,locus:`Great Vespers, Menaion-stichera verse 3`}}],dogmatikon_rubric:`Glory from the Menaion, if appointed otherwise: Glory ..., Both now ..., Theotokion Dogmatic:`,dogmatikon:{text:`How can we, O all-honored one, * not marvel at thine Offspring? * Who is both God and man. * For without knowing a man, O all-immaculate one, * without a father thou hast given birth to a Son in the flesh, * who without a mother was begotten from the Father before all ages, * yet in no way undergoing change, fusion or separation, * but preserving fully the characteristics of both natures. * Wherefore, O Sovereign Lady, and Virgin Mother, * beseech Him to save the souls of those ** who with Orthodox faith confess thee to be the true Theotokos.`,tier:2,src:{file:`3-1.pdf`,locus:`Great Vespers, Glory/Both-now — Theotokion Dogmatic`},sourceLabel:`Glory ..., Both now ..., Theotokion Dogmatic`},prokeimenon:{ref:`shared.saturday_vespers_prokeimenon`},aposticha:[{text:`By Thy Passion, O Christ, * Thou didst darken the sun, * and by the light of Thy Resurrection * Thou hast made the whole universe radiant. * We beseech Thee to accept our evening hymn, ** O Lover of mankind.`,tier:2,src:{file:`3-1.pdf`,locus:`Great Vespers, aposticha sticheron 1 (unversed)`}},{text:`O Gracious Lord, Thy life-bearing rising hath enlightened the world, * and reclaimed Thine own fashioned after Thine image, * which had become corrupt. * And so, delivered from the curse of Adam, we cry aloud, ** “O all-powerful Lord, glory be to Thee!”`,tier:2,src:{file:`3-1.pdf`,locus:`Great Vespers, aposticha sticheron 2`}},{text:`Howbeit, as God Thou art unchangeable, * yet by Thy suffering Thou hast undergone change in the flesh, * and creation, unable to bear seeing Thee hanging upon a Cross, * was shaken with fear, * groaning as it sang the praise of Thy long- suffering; * and having descended into Hades, Thou didst arise on the third day, ** granting to the world life and great mercy.`,tier:2,src:{file:`3-1.pdf`,locus:`Great Vespers, aposticha sticheron 3`}},{text:`In order to ransom our race from death, O Christ, * Thou didst suffer death; * and arising on the third day from the dead * Thou hast raised with Thyself those who acknowledged Thee as God, * and Thou hast enlightened the world. ** O Lord, glory be to Thee!`,tier:2,src:{file:`3-1.pdf`,locus:`Great Vespers, aposticha sticheron 4`}}],aposticha_verses:{ref:`shared.saturday_gv_aposticha_verses`},aposticha_glory_rubric:`Glory from the Menaion, if appointed, otherwise:`,aposticha_theotokion:{text:`By the will of the Father and without seed * thou didst conceive through the divine Spirit the Son of God * Who hath existed from the Father without a mother from before the ages, * and Who for our sake came forth from Thee in the flesh without a father, * and Him hast thou suckled as a babe. * Wherefore, cease not to beseech Him, ** that our souls be delivered from tribulations.`,tier:2,src:{file:`3-1.pdf`,locus:`Great Vespers, aposticha Theotokion — the REAL Saturday fallback (§4.3/§8)`}},vigil_rubric:{ref:`shared.theotokos_virgin_rejoice`},no_vigil_rubric:`If a Vigil is not served, we chant (Once):`},nocturns:{frame_rubric:`The priest saith: “Blessed is our God ...,” and we say: Amen. Glory to Thee, our God, glory to Thee. O heavenly King... Trisagion through Our Father... Priest: For Thine is the kingdom ..., And we say: Amen. Lord, have mercy (12 times), Glory..., Both now..., O come, let us worship (Thrice). Psalm 50 (Have mercy on me, O God ...,)`,canon:{title:`Canon to the Holy & Life-creating Trinity`,composer:`Metrophanes`,acrostic:`I hymn Thee, O Trinity, the One Godhead`,heading_rubric:`And then, the Canon to the Holy & Life-creating Trinity, the acrostic whereof is “I hymn Thee, O Trinity, the One Godhead,” the composition of Metrophanes, in Tone III:`,odes:{1:{irmos:{text:`He who of old gathered the waters * into one by His divine decree, * divided the sea for the people of Israel. * For He is our God and supremely glorious, * to Him alone let us sing, for He hath been glorified.`,tier:2,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 1 irmos`}},items:[{text:`Refrain: O Most Holy Trinity our God, glory to Thee!`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 1, item 1`},label:`plain`},{text:`O sole unapproachable Dominion, Thou one Godhead of the Trinity, grant me Thy thrice-radiant light, that I may hymn Thee Who art unceasingly hymned with thrice-holy hymns by the angels.`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 1, item 2`},label:`plain`},{text:`All the immaterial ranks hymn Thee in sanctity as the one creative, thrice- radiant and clearly originate Cause; and with them we, the multitudes of peoples, likewise hymn and faithfully glorify Thee with our mouths of clay.`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 1, item 3`},label:`plain`},{text:`In symbolic manner the theologians fittingly call Thee Mind, and Word and Spirit, signifying the dispassionate begetting of the Son from the unbegotten Father, as well as the procession of the divine Spirit, O God Who art the sole Source of all.`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 1, item 4`},label:`glory`},{text:`Having assumed human nature in that by nature Thou lovest mankind, O Word of God, Thou didst shine forth the trinitarian Light of the one Godhead, which is the sole and only Source, pointing out to all the most pure and most glorious Virgin who gave birth to Thee.`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 1, item 5`},label:`both_now`}]},3:{irmos:{text:`O Most High, Ruler of all, * who out of nothing hath established all things, * fashioned by Thy Word, * perfected by the Spirit, * confirm me in Thy love.`,tier:2,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 3 irmos`}},items:[{text:`Elijah of old, having commanded that water be poured forth on the split wood, mystically manifested the trinitarian Hypostasis of the one divine Dominion.`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 3, item 1`},label:`plain`},{text:`The corrupt nature of mortals hymneth Thee, the one, thrice-radiant and immutable Creator; and cries out unto thee, O Master: Deliver and save me from every manner of uncertainty.`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 3, item 2`},label:`plain`},{text:`Uttering the same words as the prophets, the glorious apostles and the preachers of the Faith, we, the faithful, glorify Thee, the Trinity equal in activity, O God of all.`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 3, item 3`},label:`glory`},{text:`Through thee, O most pure one, Christ descended from His exalted throne, elevating mankind, in that He is the Lover of mankind; and He hath shone forth the three-sunned Light upon all.`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 3, item 4`},label:`both_now`},{text:`Lord, have mercy. (Thrice)`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 3, item 5`},label:`plain`}]},4:{irmos:{text:`Thou hast shown us steadfast love, O Lord, * for Thou gavest Thine only-begotten Son over to death for our sake. * Wherefore with thanksgiving we cry unto Thee, * ‘Glory to Thy power, O Lord!’`,tier:2,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 4 irmos`}},items:[{text:`A double branch sprouted forth from the Father, as from a root: the Son and the upright Spirit, consubstantial offshoots divinely planted, blossoms equally without beginning. For there are the three Lights of the Godhead.`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 4, item 1`},label:`plain`,repeat:2},{text:`The multitudes of noetic intelligences unceasingly hymn thee, the inconceivable God; and with them we render glory, saying: O transcendent Trinity, save Thy servants, in that Thou lovest mankind.`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 4, item 2`},label:`glory`},{text:`Thou hast set us afire with Thy love, O greatly merciful Word of God Who for our sake became incarnate without undergoing change, mystically teaching us about the one thrice-radiant Godhead. Wherefore, we glorify Thee.`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 4, item 3`},label:`both_now`}]},5:{irmos:{text:`In a vision Isaiah saw upon a throne, * God lifted up on high * borne aloft by angels of glory; * and he cried: ‘Woe is me! * For I have foreseen God made flesh, * the Lord of the never-setting light * and the King of peace.’`,tier:2,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 5 irmos`}},items:[{text:`When Isaiah mystically beheld God, the one Sovereign Lord, glorified in three Hypostases by the most pure voices of the seraphim, whereupon he was straightway sent to proclaim the thrice-radiant Essence, the three-sunned Unity.`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 5, item 1`},label:`plain`,repeat:2},{text:`O three-sunned Unity Who in the beginning created the essence of all things, visible and invisible, out of nothing, and Who hast delivered from all temptations those who with faith hymn Thee as the one God: grant unto us Thy glory.`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 5, item 2`},label:`glory`},{text:`With love we hymn and bless thee, O Virgin, Who hast become the radiant and pure bridal chamber of God; for from thee Christ Who is one of the Trinity and the Lord of glory, was born in two natures and wills.`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 5, item 3`},label:`both_now`}]},6:{irmos:{text:`The uttermost depths of sin have surrounded me, * and my spirit perisheth, * but do Thou, O Master, stretch forth Thy lofty arm * and like Peter O Helmsman, * do Thou save me.`,tier:2,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 6 irmos`}},items:[{text:`As a sojourner, Abraham was deemed worthy to mystically to receive the one Lord in three Hypostases, made manifest in the forms of men.`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 6, item 1`},label:`plain`,repeat:2},{text:`Guide the hearts of Thy servants to the unapproachable light, O three-sunned Lord, and grant the effulgence of Thy glory unto our souls, that we may be illumined by Thine ineffable goodness.`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 6, item 2`},label:`glory`},{text:`Open unto me the portals of the light of Him Who was born of thy womb, O most pure one, that I may behold the thrice-brilliant rays of His divinity and glorify thee, O most radiant Lady.`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 6, item 3`},label:`both_now`},{text:`Lord, have mercy. (Thrice)`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 6, item 4`},label:`plain`}]},7:{irmos:{text:`As of old Thou didst bedew * the three pious children in the Chaldean flames, * so also with the radiant fire of Thy divinity * illumine us who cry to Thee, * ‘Blessed art Thou, the God of our fathers!’`,tier:2,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 7 irmos`}},items:[{text:`Through Thy light-giving radiance, O Master, show me to be a splendid temple of Thy thrice-radiant Godhead, far above the cruel darkness of sin and the passions. Blessed art Thou, O God of our fathers!`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 7, item 1`},label:`plain`},{text:`We proclaim the one face of the Godhead in three Hypostases and individual characteristics: the Father, the Son and the Spirit; crying aloud: Blessed art Thou, the God of our fathers!`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 7, item 2`},label:`plain`},{text:`Of old, God in three Hypostases appeared to Abraham at the Oak of Mamre, mercifully giving him Isaac as a reward for his hospitality. Him do we now glorify as the God of our fathers.`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 7, item 3`},label:`glory`},{text:`The Creator of all appeared on earth, divinely becoming a man through thy virginal and all-pure womb; and He hath deified us, O blessed, all- pure and most pure Theotokos.`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 7, item 4`},label:`both_now`}]},8:{irmos:{text:`United together in the unbearable fire, * yet not harmed by the flame, * the children, champions of godliness, sang a divine hymn: * O all ye works of the Lord, * bless ye the Lord and supremely exalt Him throughout all ages.`,tier:2,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 8 irmos`}},items:[{text:`The Word and the Spirit Who are equally without beginning came from the root of the beginningless Father, and as offshoots of the transcendent Godhead they have shown forth the one glory and power of the Trinity, Whom all of us, the faithful, hymn forever.`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 8, item 1`},label:`plain`,repeat:2},{text:`By Thine effulgences Thou dost direct the ranks of heaven to continually chant thrice-holy divine hymns to the thrice-radiant Dominion, equal in power, O Father, O Word of like form with Him, and Thou, O Spirit. Wherefore, we hymn Thee throughout all ages.`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 8, item 2`},label:`glory`},{text:`Perceiving thy birthgiving from afar, the sayings of the prophets praised it as being without seed, O Theotokos, and praised Him Who was born from thee in a manner transcending nature, O Lady. And with them, we also sing to Him as Lord and supremely exalt Him throughout all ages.`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 8, item 3`},label:`both_now`}]},9:{irmos:{text:`New is the wonder and befitting of God: * for the Lord clearly passes through the closed gate of the Virgin: * naked at His going in and God bearing flesh at His coming out, * while the gate remaineth closed. * As ineffably the Theotokos and Mother of our God we magnify her.`,tier:2,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 9 irmos`}},items:[{text:`The God-beholding ranks of the incorporeal ones desire to mount on high with their wings, to see clearly the thrice-radiant glory; yet they are in exceeding great awe of the unapproachable Light, and unceasingly cry out hymns. And together with them we glorify Thee, the only Trinity.`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 9, item 1`},label:`plain`,repeat:2},{text:`Having received from Thee a noetic and reason-endowed soul with insatiable love, O Master, God of all, with our whole heart we hymn Thee, Who art truly the one Essence, the trinity of Hypostases. Wherefore, as Thou art greatly merciful, O compassionate One, have pity on us.`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 9, item 2`},label:`glory`},{text:`Show me to be a splendid temple of Thy thrice-radiant Godhead Which alone is the source of all, that I may serve Thee, the Creator of all, in purity, and noetically behold Thine ineffable glory: through the supplications of the only Theotokos, whom we fittingly magnify as most glorious.`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, Ode 9, item 3`},label:`both_now`}]}}},after_ode3:{sessional:{text:`O Christ, our only transcendent Lord, Scion of the beginningless Father, and Thou, O most divine Spirit, have mercy upon Thy servants: for we all have sinned, yet have we not turned away from Thee. Wherefore, we beseech Thee, O Lord in three Hypostases: In that Thou hast authority, save Thy creation from every evil circumstance.`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, sessional after Ode III`},spec_mel:`Awed by the beauty of thy virginity ...`,sourceLabel:`Sessional Hymn`},theotokion:{text:`In His goodness, the transcendent God and Lord became incarnate from thee, assuming our essence; and He dwelt among us. Wherefore, honoring His divine manhood, we proclaim thee to be the Theotokos O all-pure one who knew not wedlock, glorifying the supreme wonder of thy seedless birthgiving.`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, sessional theotokion after Ode III`},type:`theotokion`}},after_ode6:{sessional:{text:`We hymn the three-sunned Dominion of the consubstantial divine nature, and with thrice-holy voices we cry: Holy art Thou, O beginningless Father! Holy art Thou, O equally-beginningless Son, and Thou, O Holy Spirit, O our only God Who art indivisible, O Creator of all, Who lovest mankind!`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, sessional after Ode VI`},spec_mel:`Of the divine Faith ...`,sourceLabel:`Sessional Hymn`},theotokion:{text:`O supreme wonder! How did the infinite One come to be contained within thy womb, and become incarnate, and appear as a man, without enduring change or separation from the divine and immutable Divinity, O all-pure maiden? Wherefore with faith, we ever proclaim and glorify thee, the Theotokos.`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, Trinity canon, sessional theotokion after Ode VI`},type:`theotokion`}},gregory_rubric:{rubric:`Then, the hymn of Gregory the Sinaite: (which is chanted every Sunday after the canon)`,stanzas:[{text:`It is truly meet to glorify Thee, the Word of God, before Whom the cherubim tremble and quake, and Whom the hosts of heaven glorify. And with fear we glorify Christ, the Bestower of life, Who rose from the tomb on the third day.`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, hymn of Gregory the Sinaite, stanza 1`}},{text:`With divine songs let us all in a godly manner hymn the Father, the Son and the Spirit divine, the one Might in three Hypostases, the Sovereignty and Dominion. Whom all mortals hymn and the hosts of heaven glorify, the essential Unity in three Hypostases, Who is worshipped with faith by all. We magnify Thee, the Godhead, the Lord of the cherubim, the incomparable divine Origin of the seraphim, the indivisible Trinity in Unity. I worship God: the beginningless Father, the Son Who is equally without beginning, and the Spirit. With hymns let us honor the one indivisible and unified Essence, the threefold Unity. Shine forth Thy dazzling lightning flashes upon me, O my God in three Hypostases, Creator of all, and show me to be a splendid, luminous and immutable habitation of Thine unapproachable glory. With fear let us glorify Christ the Bestower of life, Who ineffably became incarnate of the Virgin, for the cherubim tremble and quake before Him, and the angelic armies glorify Him. The rest of Nocturns, and the Dismissal.`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, hymn of Gregory the Sinaite, stanza 2 — word-order divergence vs shared ("the one Might … the Sovereignty"; the 4-1 variant; §5 per-tone)`}},{text:`Whom all mortals hymn and the hosts of heaven glorify, the essential Unity in three Hypostases, Who is worshipped with faith by all.`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, hymn of Gregory the Sinaite, stanza 3`}},{text:`We magnify Thee, the Godhead, the Lord of the cherubim, the incomparable divine Origin of the seraphim, the indivisible Trinity in Unity.`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, hymn of Gregory the Sinaite, stanza 4`}},{text:`I worship God: the beginningless Father, the Son Who is equally without beginning, and the Spirit. With hymns let us honor the one indivisible and unified Essence, the threefold Unity.`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, hymn of Gregory the Sinaite, stanza 5`}},{text:`Shine forth Thy dazzling lightning flashes upon me, O my God in three Hypostases, Creator of all, and show me to be a splendid, luminous and immutable habitation of Thine unapproachable glory.`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, hymn of Gregory the Sinaite, stanza 6`}},{text:`With fear let us glorify Christ the Bestower of life, Who ineffably became incarnate of the Virgin, for the cherubim tremble and quake before Him, and the angelic armies glorify Him.`,tier:1,src:{file:`3-1.pdf`,locus:`Nocturns, hymn of Gregory the Sinaite, stanza 7`}}],provenance_note:`RULED (Bill, July 8 2026): Gregory hymn stored PER-TONE in every tone — four prints yield three distinct byte-states with no majority reading (2-1+5-1 vs 3-1+4-1 at the stanza-2 clause, plus 5-1-only variants), falsifying the §5 shared hypothesis for this hymn. 3-1 diverges from shared at stanza 2 only (word order); the remaining stanzas byte-match. Retro-fix of the cont.-6 session, which left the ref in place.`},closing_rubric:`The rest of Nocturns, and the Dismissal.`},matins:{god_is_lord_rubric:`On “God is The Lord ...,” the Resurrection Troparion, in Tone III: [troparion printed "(Twice)"] Glory ..., the Troparion from the Menaion, otherwise Glory ..., Both now ..., the Theotokion, in Tone III, (or in the Tone of that from the Menaion):`,sessionals:[{rubric:`After the 1st chanting of the Psalter (Kathisma II), the Sessional Hymns of the Resurrection, in Tone III:`,items:[{text:`Christ hath arisen from the dead, * the first fruits of those that sleep. * The first-born of creation * and Creator of all that hath come to be, * hath renewed in Himself the corrupted nature of our race. * Death, no longer art thou lord, ** for the Master of all things hath destroyed thy dominion.`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins, Kathisma II, sessional 1`},label:`plain`},{text:`Having tasted death in the flesh, O Lord, * Thou hast blotted out the bitterness of death by Thine arising * strengthening mankind against it, * and announcing the abolition of the ancient curse. ** Defender of our lives, O Lord, glory be to Thee!`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins, Kathisma II, sessional 2`},label:`plain`}],verses:[{text:`Arise, O Lord my God, let Thy hands be lifted on high; * forget not Thy paupers to the end.`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins, Kathisma II, sessional verse`}}],closer:{text:`Spec. Mel.: “Awed by the beauty of thy virginity ...”:`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins, Kathisma II, Glory/Both-now closer`},type:`theotokion`}},{rubric:`After the 2nd chanting of the Psalter (Kathisma III), the Sessional Hymns of the Resurrection, in Tone III:`,items:[{text:`Awed by Thine immutable Godhead * and by Thy voluntary passion, O Lord, * Hades lamented, “I tremble at Thy body’s essence, which remaineth incorrupt. * I behold Thee, the One who is invisible, mystically making war against me; * wherefore those whom I hold cry out: ** Glory, O Christ, to Thy Resurrection!”`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins, Kathisma III, sessional 1`},label:`plain`},{text:`We the faithful contemplate an ineffable mystery: * Thine incomprehensible Crucifixion and Thine inexplicable arising. * For today death and Hades have been despoiled, * but mankind hath been clothed in incorruption. * Wherefore with thanksgiving we cry aloud unto Thee, * “Glory, O Christ, to Thy Resurrection!”`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins, Kathisma III, sessional 2`},label:`plain`}],verses:[{text:`I will confess Thee, O Lord, with my whole heart, * I will tell of all Thy wonders.`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins, Kathisma III, sessional verse`}}],closer:{text:`Mystically didst thou contain in thy womb * the incomprehensible and uncircumscribed One, * consubstantial with the Father and the Spirit; * and we acknowledge in thine Offspring one unconfused energy of the Trinity Who is glorified in the world. * And so with thanksgiving we cry unto thee, ** “Rejoice, thou Full of grace!”`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins, Kathisma III, Glory/Both-now closer`},type:`theotokion`}}],polyeleos_rubric:{ref:`shared.polyeleos`},evlogitaria_rubric:{ref:`shared.evlogitaria`},hypakoe:{text:`A cause of amazement by his appearance, * and source of refreshment by his speech, * the radiant angel spake unto the myrrh-bearing women saying, * “Why do ye seek the living in a grave? * He hath arisen, emptying the graves. * Know that the unchangeable One hath changed corruption. * Wherefore cry unto God saying: * How fearful are Thy works! ** For Thou hast saved mankind.”`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins, after the Evlogitaria`},sourceLabel:`The Sessional Hymn`},anabathmoi:[{troparia:[{text:`Thou, O Word, didst deliver the captivity of Zion from Babylon, * deliver me also ** from the passions unto life.`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins, Anabathmoi antiphon 1, troparion 1`}},{text:`Those who sow in the South * with tears inspired by God, ** shall in joy reap sheaves of everlasting life.`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins, Anabathmoi antiphon 1, troparion 2`}}],gloria:{text:`By the Holy Spirit, together with the Father and the Son * shineth forth the reflection of every good gift, ** In Him all things live and have their being.`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins, Anabathmoi antiphon 1, Glory/Both-now`}}},{troparia:[{text:`Except the Lord build the house of the virtues, * in vain do we labor. ** While He doth protect our soul no one layeth waste our city.`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins, Anabathmoi antiphon 2, troparion 1`}},{text:`The saints, O Christ, fruits of the womb, * are by the Spirit, always sons to Thee, ** as Thou art to the Father.`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins, Anabathmoi antiphon 2, troparion 2`}}],gloria:{text:`The Holy Spirit is the inspiration of all that is holy and wise; * for He doth quicken every creature. ** Let us worship Him together with the Father and the Son, for He is God.`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins, Anabathmoi antiphon 2, Glory/Both-now`}}},{troparia:[{text:`Those who fear the Lord are blessed * as they walk along the paths of His commandments; * for they partake of the life-giving Fruit.`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins, Anabathmoi antiphon 3, troparion 1`}},{text:`Be glad, Chief Shepherd, * beholding Thine offspring around Thy table * bearing the branches of good works.`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins, Anabathmoi antiphon 3, troparion 2`}}],gloria:{text:`In the Holy Spirit is a superabundance of glory; * for from Him proceedeth forth grace and life into all creation; * wherefore He is praised together with the Father and the Word.`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins, Anabathmoi antiphon 3, Glory/Both-now`}}}],prokeimenon:{tone:3,text:{text:`Say among the nations that the Lord is king; * for He hath established the universe which shall not be shaken The Verse: O Sing unto the Lord a new song. Sing unto the Lord all the earth.`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins prokeimenon`}}},canon:{title:`Resurrection Canons Tone III`,heading_rubric:`After which: “O God, save Thy people ...,” Then the Canons: Resurrection Canons Tone III.`,odes:{1:{irmos:{text:`He who of old gathered the waters * into one by His divine decree, * divided the sea for the people of Israel. * For He is our God and supremely glorious, * to Him alone let us sing, for He hath been glorified.`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 1 irmos`}},resurrection:{refrain:`Glory to Thy holy Resurrection O Lord.`,troparia:[{text:`He who sentenced the earth to bring forth thorns as the fruit of the sweat of the transgressor, hath accepted in the body a crown of thorns from a lawless hand, abolishing the curse. He is our God, wherefore He is glorified.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 1, resurrection troparion 1`}},{text:`Our God hath been shown to be a triumphant victor and vanquisher of death, for death was smitten with fear when our God, having taken living flesh subject to suffering, wrestled with the tyrant and raised all with Himself, wherefore He hath been glorified.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 1, resurrection troparion 2`}}],closer:{text:`All the nations glorify thee as the true Theotokos, O thou who hast given birth without seed; for having come into thy hallowed womb, our God assumed that which was according to our nature, and as both God and man He was born from thee.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 1, resurrection closer`},type:`theotokion`,refrain:`Most holy Theotokos save us.`,sourceLabel:`Theotokion`}},cross_resurrection:{refrain:`Glory to Thy precious Cross and Resurrection O Lord.`,troparia:[{text:`By His divine blood, Christ hath redeemed the race of mankind, enslaved to the sin-loving tyrant, and making us divine He hath renewed us, wherefore He hath been glorified.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 1, cross_resurrection troparion 1`}},{text:`Christ, the Guardian of life, as a mortal willingly tasted death; while by nature being immortal He hath granted life to the dead, wherefore He hath been glorified.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 1, cross_resurrection troparion 2`}}]},theotokos:{refrain:`Most holy Theotokos save us.`,troparia:[{text:`Every order of heavenly beings fittingly bends the knee, O Virgin, to Him who was incarnate from thee, and together with them, those below the earth, and those upon the earth, for He hath been glorified.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 1, theotokos troparion 1`}},{text:`O the mysteries which took place within thee! For God, who abundantly bestoweth all good things, hath given us the divine Spirit, and taken flesh from thee, O maiden, wherefore He hath been glorified.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 1, theotokos troparion 2`}}]},menaion_rubric:`The Troparia from the Menaion, then the appointed Katavasia.`},3:{irmos:{text:`O Most High, Ruler of all, * who out of nothing hath established all things, * fashioned by Thy Word, * perfected by the Spirit, * confirm me in Thy love.`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 3 irmos`}},resurrection:{refrain:`Glory to Thy holy Resurrection O Lord.`,troparia:[{text:`Through Thy Cross the wicked one hath been shamed, for he hath fallen into the pit which he himself hath dug; while the horn of the humble, O Christ, hath been exalted in Thy Resurrection.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 3, resurrection troparion 1`}},{text:`The preaching of true religion hath covered like flowing waters the seas of the nations, O Lover of mankind; for by arising from the tomb Thou hast revealed the light of the Trinity.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 3, resurrection troparion 2`}}],closer:{text:`Glorious things are spoken of thee, O living city of Him who is King forever; for through thee, O Sovereign Lady, God dwelt among those on earth.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 3, resurrection closer`},type:`theotokion`,refrain:`Most holy Theotokos save us.`,sourceLabel:`Theotokion`}},cross_resurrection:{refrain:`Glory to Thy precious Cross and Resurrection O Lord.`,troparia:[{text:`O immaculate Cross, thou wast revealed to be a purification from the abominations of idols, for Jesus, supremely divine, stretched out His arms upon thee.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 3, cross_resurrection troparion 1`}},{text:`May we the faithful worship thee, O Life-bearing tomb, for Christ, who is truly our God, hath been buried in thee and arose from thee.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 3, cross_resurrection troparion 2`}}]},theotokos:{refrain:`Most holy Theotokos save us.`,troparia:[{text:`A rod from the root of Jesse hath budded forth, as the prophet said, for the Virgin blossomed forth with a flower for us - Thee O Christ; Holy art Thou, O Lord.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 3, theotokos troparion 1`}},{text:`That Thou mightest make those born of earth partakers of the divine nature, Thou didst impoverish Thyself in assuming our flesh from the Virgin; Holy art Thou, O Lord.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 3, theotokos troparion 2`}}]},menaion_rubric:`The Troparia from the Menaion, then the appointed Katavasia.`},4:{irmos:{text:`Thou hast shown us steadfast in love, O Lord, * for Thou gavest Thine only-begotten Son over to death for our sake. * Wherefore with thanksgiving we cry unto Thee, * ‘Glory to Thy power, O Lord!’`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 4 irmos`}},resurrection:{refrain:`Glory to Thy holy Resurrection O Lord.`,troparia:[{text:`In Thy compassion, O Christ, Thou didst bear marks and wounds, bravely bearing the injurious blows and with long-suffering even endured being spat upon, wherewith Thou hast wrought salvation for me; Glory to Thy power, O Lord!`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 4, resurrection troparion 1`}},{text:`In a mortal body, O Life, Thou hast partaken of death, for the sake of the wretchedness of Thy needy and the sighing of Thy poor, and having despoiled the seducing destroyer, Thou hast raised all with Thee, O glorious One, gloriously hast Thou been glorified.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 4, resurrection troparion 2`}}],closer:{text:`Remember, O Christ, the flock which Thou hast procured by Thy Passion. Accept the compassionate supplications of Thy most blessed Mother and watching over it in its affliction, deliver it by Thy power, O Lord.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 4, resurrection closer`},type:`theotokion`,refrain:`Most holy Theotokos save us.`,sourceLabel:`Theotokion`}},cross_resurrection:{refrain:`Glory to Thy precious Cross and Resurrection O Lord.`,troparia:[{text:`O Lover of mankind, Who hath fashioned mankind according to Thine image, when it was slain by sin through transgression, Thou didst save it by Thy crucifixion on Calvary.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 4, cross_resurrection troparion 1`}},{text:`Death hath given up the dead whom it had swallowed, while the dominion of Hades, which brought forth corruption, was destroyed when Thou didst arise from the tomb, O Lord.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 4, cross_resurrection troparion 2`}}],closer:{text:`O Mary, thou art like a pure golden censor filling the world with the sweetest fragrance, for without commingling, one of the Holy Trinity, the Incarnate Word of God, hath made His abode in thee.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 4, cross_resurrection closer`},type:`theotokion`,refrain:`Most holy Theotokos save us.`,sourceLabel:`Theotokion`}},theotokos:{refrain:`Most holy Theotokos save us.`,troparia:[{text:`Thou, O Master, Who hath established the mountains in accordance with the ordinances of divine knowledge, art the stone which, without hands, hath been hewn from the Virgin. To Thy power be glory, O Lover of mankind.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 4, theotokos troparion 1`}},{text:`O Word, Thou hast healed our diseased nature, by uniting with it in the Virgin, the most effectual medicine of Thine immaculate Godhead, O Master.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 4, theotokos troparion 2`}},{text:`O Lord, Thou art my portion and my most desired heritage; for, Thou O Word, hast from the Virgin united with me Thine own Hypostasis, having been manifest a person in the flesh.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 4, theotokos troparion 3`}}]},menaion_rubric:`The Troparia from the Menaion, then the appointed Katavasia.`},5:{irmos:{text:`The Invisible One hath appeared on earth, * and the Unapproachable One hath willingly dwelt among mankind; * and, rising early at dawn, we hymn Thee, * O Lover of mankind.`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 5 irmos`}},resurrection:{refrain:`Glory to Thy holy Resurrection O Lord.`,troparia:[{text:`Handed over to an unjust judge by the envy of the Jews, Thou the all-seeing One who justly judgest all the earth, didst deliver Adam from the ancient condemnation.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 5, resurrection troparion 1`}},{text:`O Christ, who arose from the dead, grant peace to Thy Churches, and by the invincible power of Thy Cross, save our souls.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 5, resurrection troparion 2`}}],closer:{text:`Thou alone hast appeared, O Ever-virgin, as a Holy Tabernacle wider than the heavens, for thou hast received the Word of God, whom all of creation cannot contain.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 5, resurrection closer`},type:`theotokion`,refrain:`Most holy Theotokos save us.`,sourceLabel:`Theotokion`}},cross_resurrection:{refrain:`Glory to Thy precious Cross and Resurrection O Lord.`,troparia:[{text:`O Christ, when Thy side was pierced by the lance, Thou didst deliver from the curse her who was formed from man’s side and who had become the agent of ruin for all mankind.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 5, cross_resurrection troparion 1`}},{text:`Christ, our Savior, equal in being with the Father, hath raised from the dead the sacred temple of His most pure and all-honored body.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 5, cross_resurrection troparion 2`}}]},theotokos:{refrain:`Most holy Theotokos save us.`,troparia:[{text:`The Word of God, O Virgin, thy Son, and the Creator of Adam the first- formed, is not a creature, though He hath fashioned for Himself living flesh from thee.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 5, theotokos troparion 1`}},{text:`Equal to the Father, is thy Son O Virgin, the Word of God, a perfect person in two natures, Jesus the Lord, perfect God and perfect man.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 5, theotokos troparion 2`}}]},menaion_rubric:`The Troparia from the Menaion, then the appointed Katavasia.`},6:{irmos:{text:`The uttermost depths of sin have surrounded me, * and my spirit perisheth, * but do Thou, O Master, stretch forth Thy lofty arm * and like Peter save me, * O my Helmsman.`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 6 irmos`}},resurrection:{refrain:`Glory to Thy holy Resurrection O Lord.`,troparia:[{text:`By Thy gracious descent, an abyss of mercy and compassion hath surrounded me; for becoming incarnate and taking the form of a servant, O Master, Thou hast made me divine and glorified me together with Thyself.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 6, resurrection troparion 1`}},{text:`The man-slayer became as one dead when he saw the One who had been put to death restored to life. These are the tokens of Thy Resurrection, O Christ, and the rewards of Thine immaculate Passion.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 6, resurrection troparion 2`}}],closer:{text:`O most pure one, who beyond understanding art alone the mediatress between the Creator and mankind, beseech thy Son to be merciful to thy sinful servants and make thyself their protectress.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 6, resurrection closer`},type:`theotokion`,refrain:`Most holy Theotokos save us.`,sourceLabel:`Theotokion`}},cross_resurrection:{refrain:`Glory to Thy precious Cross and Resurrection O Lord.`,troparia:[{text:`Tried by stripes, and by the Passion of Thy Cross, Thou hast raised with Thee, those who lay slain in Hades; therefore I cry unto Thee, “Raise up my life up from corruption, O Lover of mankind.”`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 6, cross_resurrection troparion 1`}},{text:`The gates of Hades now open to Thee in fear, O Christ, and the enemy’s possessions are ravished, wherefore the women met Thee receiving gladness instead of sorrow.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 6, cross_resurrection troparion 2`}}]},theotokos:{refrain:`Most holy Theotokos save us.`,troparia:[{text:`He who by nature hath no part in any created form, hath taken our form from the undefiled maiden, becoming a man in form and substance, yet unchanged in His divinity.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 6, theotokos troparion 1`}},{text:`From an abyss of sins and from the tempest of the passions do thou deliver me, O pure one, for thou art a safe haven and an abyss of wonders for those who in faith have recourse to thee.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 6, theotokos troparion 2`}}]},menaion_rubric:`The Troparia from the Menaion, then the appointed Katavasia.`},7:{irmos:{text:`As of old Thou didst bedew * the three pious children in the Chaldean flames, * so also with the radiant fire of Thy divinity * illumine us who cry to Thee, * “O God of our fathers, blessed art Thou!”`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 7 irmos`}},resurrection:{refrain:`Glory to Thy holy Resurrection O Lord.`,troparia:[{text:`The shining veil of the temple was rent in twain by the crucifixion of the Creator, revealing the truth hidden in the scriptures to the faithful who cry, “O God of our fathers, blessed art Thou!”`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 7, resurrection troparion 1`}},{text:`When Thy side was pierced, O Christ, drops of Thy life-bearing blood, flowed by the divine dispensation of God, and fell upon the earth refashioning those who cry, “O God of our fathers, blessed art Thou!”`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 7, resurrection troparion 2`}}],closer:{text:`Let us believers glorify the good Spirit, along with the Father and the only-begotten Son, as we honor one Principle and one Godhead in three Hypostases and cry, “O God of our fathers, blessed art Thou!”`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 7, resurrection closer`},type:`trinitarion`,refrain:`We bless the Lord; Father, Son, and Holy Spirit.`,sourceLabel:`Trinitarian`}},cross_resurrection:{refrain:`Glory to Thy precious Cross and Resurrection O Lord.`,troparia:[{text:`The sun is not darkened for a mere man hanging upon a cross, but rather, upon beholding God incarnate, to whom we also sing, “O God of our fathers, blessed art Thou!”`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 7, cross_resurrection troparion 1`}},{text:`Cowardly Hades, trembling before Him who is strong in His Godhead and who granteth incorruption, spewed forth the souls of the just, who cried out, “O God of our fathers, blessed art Thou!”`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 7, cross_resurrection troparion 2`}}],closer:{text:`O most pure one, thou art a precious treasury of blessings for those who, with a pure heart, confess thee to be the Mother of God; for from thee the God of our fathers became incarnate.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 7, cross_resurrection closer`},type:`theotokion`,refrain:`Glory to Thy precious Cross and Resurrection O Lord.`,sourceLabel:`Theotokion`}},theotokos:{refrain:`Most holy Theotokos save us.`,troparia:[{text:`O Lord of glory and ruler of the powers on high, Thou who art seated with the Father and wast carried in the arms of the Virgin; “Blessed art Thou, O Lord, the God of our fathers.”`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 7, theotokos troparion 1`}},{text:`Death is bold, but when it battled with Thee, O God, made flesh from the Virgin as a man, Thou didst destroy it; “Blessed art Thou, O Lord, the God of our fathers.”`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 7, theotokos troparion 2`}},{text:`We all acknowledge thee to be the Theotokos who didst bear God in thy womb; for thou hast given birth to one of the Trinity, incarnate from thee. Blessed, O most pure one, is the Fruit of thy womb.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 7, theotokos troparion 3`}}]},menaion_rubric:`The Troparia from the Menaion, then the appointed Katavasia.`},8:{irmos:{text:`United together in the unbearable fire, * yet not harmed by the flame, * the children, champions of godliness, sang a divine hymn: * O all ye works of the Lord, * bless ye the Lord, and supremely exalt Him throughout all ages.`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 8 irmos`}},resurrection:{refrain:`Glory to Thy holy Resurrection O Lord.`,troparia:[{text:`The radiance of the temple was shattered when Thy Cross was set upon Calvary, and all creation was shaken as it sang in fear, “All ye works of the Lord, bless ye the Lord, and supremely exalt Him throughout all ages.”`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 8, resurrection troparion 1`}},{text:`Thou didst rise from the tomb, O Christ, and by Thy divine power, the Tree hath restored him who had fallen through temptation as he cried aloud, “All ye works of the Lord, bless ye the Lord, and supremely exalt Him throughout all ages.”`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 8, resurrection troparion 2`}}],closer:{text:`Thou hast been declared a living temple of God, and a spiritual ark; for thou, O most pure Birthgiver of God, didst reconcile the Creator to mortal mankind, wherefore we, all His works, fittingly praise thee and supremely exalt thee throughout all ages.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 8, resurrection closer`},type:`theotokion`,refrain:`Most holy Theotokos save us.`,sourceLabel:`Theotokion`}},cross_resurrection:{refrain:`Glory to Thy precious Cross and Resurrection O Lord.`,troparia:[{text:`The Word was not subject to suffering, for in His Godhead He cannot suffer; but it was in the flesh that God suffered, to Whom we also sing, “All ye works of the Lord, bless ye the Lord, and supremely exalt Him throughout all ages.”`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 8, cross_resurrection troparion 1`}},{text:`Having fallen asleep as a mortal, Thou wast raised up as immortal, O Savior, delivering from death those who sing, “All ye works of the Lord, bless ye the Lord, and supremely exalt Him throughout all ages.”`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 8, cross_resurrection troparion 2`}}],closer:{text:`Devoutly do we worship the Godhead, united in three Hypostases, and we sing without ceasing, “All ye works of the Lord bless ye the Lord, and supremely exalt Him throughout all ages.”`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 8, cross_resurrection closer`},type:`trinitarion`,refrain:`We bless the Lord; Father, Son, and Holy Spirit.`,sourceLabel:`Trinitarian`}},theotokos:{refrain:`Most holy Theotokos save us.`,troparia:[{text:`O Blessed Virgin Mother, who hath been raised above the spiritual powers and set next to God, we bless thine Offspring, and supremely exalt Him throughout all ages.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 8, theotokos troparion 1`}},{text:`Thou hast revealed thy natural comeliness to be most fair when Thou hast given birth to the Godhead in the flesh, O Blessed Virgin, wherefore we bless thine Offspring, and supremely exalt Him throughout all ages.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 8, theotokos troparion 2`}}]},menaion_rubric:`After the Troparia from the Menaion for ODE VIII, we chant:`},9:{irmos:{text:`New is the wonder and befitting of God: * for the Lord clearly passes through the closed gate of the Virgin: * naked at His going in and God bearing flesh at His coming out, * while the gate remaineth closed. * As ineffably the Theotokos and Mother of our God we magnify her.`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 9 irmos`}},resurrection:{refrain:`Glory to Thy holy Resurrection O Lord.`,troparia:[{text:`Fearful it is, O Word of God, to behold Thee the Creator elevated upon the Tree, suffering in the flesh on behalf of Thy servants, and lying lifeless in a grave, and yet releasing the dead from Hades. Wherefore, O Christ, as All-powerful we magnify Thee.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 9, resurrection troparion 1`}},{text:`By being placed as one dead in a tomb, O Christ, Thou hast saved the forefathers from the corruption of death, and Thou didst make life blossom forth by Thine arising from the dead, leading mortal nature to the light and clothing it with divine incorruption. Wherefore as the source of the ever-living Light we magnify Thee.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 9, resurrection troparion 2`}}],closer:{text:`Thou wast revealed, O all-pure one, as the temple and throne of God, in which He who liveth in the highest made His abode, born without a man, and in no way opening the gates of thy flesh. Therefore by thine unceasing prayers, O holy one, finally defeat the tribes of the barbarians and subject them to our King.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 9, resurrection closer`},type:`theotokion`,refrain:`Most holy Theotokos save us.`,sourceLabel:`Theotokion`}},cross_resurrection:{refrain:`Glory to Thy precious Cross and Resurrection O Lord.`,troparia:[{text:`O Christ our Savior, Thou hast become a source of glory for mortals by a dishonorable death, which Thou didst taste through crucifixion in Thy mortal nature, and by which Thou hast granted unto me incorruption, for Thou lovest mankind.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 9, cross_resurrection troparion 1`}},{text:`By rising from the tomb, O Christ, Thou hast saved me, and for the sake of Thy compassionate mercy, Thou hast exalted me and brought me to the Father, Thy Begetter, at Whose right hand Thou hast taken Thy seat, O Lord.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 9, cross_resurrection troparion 2`}}]},theotokos:{refrain:`Most holy Theotokos save us.`,troparia:[{text:`For the devout faithful, who experience the ever-increasing spiritual and divine desire that cometh from singing praises in honor of thee, O Virgin, there can never be enough; wherefore we ever magnify thee as the Mother of God.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 9, theotokos troparion 1`}},{text:`Thou hast enthroned her who bare Thee, O Christ as an unfailing intercessor for us. By her supplications, O merciful One, grant unto us the Spirit who giveth freely of His goodness, and who proceedeth through Thee from the Father.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Matins canon, Ode 9, theotokos troparion 2`}}]},post_rubric:`The small litany: Then, “Holy is our God ...,”: (Thrice)`}}},exapostilarion_rubric:`Exapostilarion (Svetilen). Note: The Exapostilarion is taken from the prescribed Eothinon according to the Resurrection Gospel, however, If the Menaion service is ‘feasted’ the Exapostilarion, with the appointed Theotokion, are taken from the Menaion.`,praises:{rubric:`On the Praises: “Let every breath ...,” 8 Stichera of the Resurrection, however, if the service from the Menaion is ‘feasted’ sing the first 4 Stichera from the Resurrection, and the last 4 from the Menaion, with the appointed verses.`,stichera:[{text:`Come all ye nations, * acknowledge the power of the dread mystery; * for Christ our Savior, the beginningless Word, * was crucified for us and was willingly buried * and arose from the dead * to save the whole universe. ** Him let us worship.`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins, Praises sticheron 1`}},{text:`Thy guards recounted all the marvels, O Lord, * but, by filling their right hands with money, * the Sanhedrin of folly thought to conceal Thy Resurrection, * which the world doth glorify; ** have mercy upon us.`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins, Praises sticheron 2`}},{text:`All things have been filled with joy on receiving proof of the Resurrection. * For Mary Magdalene having come to the tomb, * found an angel seated upon the stone, * radiant in shining raiment, saying, * “Why dost Thou seek the living among the dead? * He is not here, but He hath arisen, as He foretold, ** and goeth before thee into Galilee.”`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins, Praises sticheron 3`}},{text:`In Thy light, O Master and Lover of mankind, * shall we see light. * For Thou didst rise from the dead, * granting salvation unto the race of mankind, * wherefore all creation doth glorify Thee, the only sinless One; ** have mercy upon us.`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins, Praises sticheron 4`}},{text:`As a morning hymn, O Lord, * the myrrh-bearing women offered Thee their tears. * For bringing perfumes of sweet fragrances, they came to Thy grave, eager to anoint Thy most pure body. * An angel seated upon the stone declared unto them the good tidings, * “Why seek ye the living among the dead? * For He hath trampled down death, He hath arisen as God, ** granting unto all His great mercy.”`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins, Praises sticheron 5`},provenance_note:`sub-group "Other Stichera of Anatolius"`},{text:`A radiant angel seated by Thy life-giving tomb * spake to the myrrh-bearing women saying, * “The Redeemer hath emptied the tombs, * He hath despoiled Hades ** and hath arisen on the third day as alone God and All-powerful.”`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins, Praises sticheron 6`},provenance_note:`sub-group "Other Stichera of Anatolius"`},{text:`On the first day of the week Mary Magdalene came to the tomb seeking Thee. * When she did not find Thee, she lamented and cried out with grief, * “Alas, my Savior, how hast Thou, the King of all, been stolen?” * But a pair of radiant angels from within the sepulcher cried out, * “Why dost thou weep, woman?” * “I weep,” she said, “because they have taken my Lord from the tomb * and I know not where they have laid Him.” * Whereupon, turning back and seeing Thee, she at once cried out, ** “My Lord and my God, glory be to Thee!”`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins, Praises sticheron 7`},provenance_note:`sub-group "Other Stichera of Anatolius"`},{text:`The Hebrews shut Life within the tomb; * but the thief opened the paradise of pure delight with his voice when he cried aloud saying, * “The One who wast crucified with me and who wast hung with me upon the Tree * also appeareth to me seated upon a throne together with the Father. ** For He is Christ our God, Who hath great mercy.”`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins, Praises sticheron 8`},provenance_note:`sub-group "Other Stichera of Anatolius"`}],verses:{ref:`shared.praises_verse_ladder`},gloria_rubric:`Glory ..., The Eothinon of the Resurrection Gospel Note: If the service from the Menaion is ‘feasted’ the Eothinon is taken from the Menaion, and the Eothinon of the Gospel is read at the end of Matins.`,theotokion:{text:`Thou art most blessed, O Virgin Theotokos, * for through Him who took flesh from thee, Hades hath been captured, * Adam recalled, the curse slain, Eve set free, * death put to death, and we have been given life. * Therefore in praise we cry: ** Blessed art Thou, O Christ our God, who hast been thus well-pleased, glory be to Thee.`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins, Praises Both-now Theotokion`}}},doxology_troparion:{text:`Today is salvation come unto the world; * let us sing praises to Him that arose from the tomb, * and is the Author of our life. * For, having destroyed death by death, ** He hath given us the victory and great mercy.`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Matins, troparion after the Great Doxology`}}},liturgy:{beatitudes:{rubric:`Typika and Beatitudes. At The Liturgy Beatitudes, in Tone III`,troparia:[{text:`From paradise didst Thou drive our forefather Adam, who had broken Thy commandment, O Christ; but, O compassionate One, Thou didst cause to dwell therein the thief who confessed Thee on the Cross, crying out: “Remember me, O Savior, in Thy kingdom!”`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Liturgy, Beatitude troparion 1`}},{text:`With the curse of death didst Thou condemn us who had sinned, O Lord, Bestower of life; yet having suffered in Thy flesh, O sinless Master, Thou hast granted life unto mortals who cry out: “Remember us also in Thy kingdom!”`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Liturgy, Beatitude troparion 2`}},{text:`In rising from the dead, Thou hast raised us up from the passions with Thyself through Thy Resurrection, O Lord; and all the power of death hast Thou destroyed, O Savior. Wherefore, with faith we cry out to Thee: “Remember us also in Thy kingdom!”`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Liturgy, Beatitude troparion 3`}},{text:`O Thou who as God grantest life, by Thy three days in the tomb Thou didst raise up with Thyself the dead in Hades, and as One Who is good Thou hast poured forth incorruption upon all of us who with faith ever cry out: “Remember us also in Thy kingdom!”`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Liturgy, Beatitude troparion 4`}},{text:`Risen from the dead, O Savior, Thou didst first appear to the myrrh-bearing women, crying out: “Rejoice!” and through them Thou didst announce Thy Resurrection to Thy friends, O Christ. Wherefore, with faith we cry out to Thee, “Remember us also in Thy kingdom!”`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Liturgy, Beatitude troparion 5`}},{text:`Moses, stretching out his arms on the mountain, prefigured the Cross and thus conquered Amalek. And, receiving it with faith as a mighty weapon against the demons, we all cry out: “Remember us also in Thy kingdom!”`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Liturgy, Beatitude troparion 6`}}],gloria:{text:`O ye faithful, let us hymn the Father, Son, and Holy Spirit, the one God, the one Lord, as from a single Sun; for the Trinity is thrice-luminous and enlightening all who cry out: “Remember us also in Thy kingdom!”`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Liturgy, Beatitudes Gloria (Triadicon — final pre-Theotokion item)`}},theotokion:{text:`Rejoice, O portal of God, through which the incarnate Creator passed without breaking thy seal! Rejoice, thou illumined cloud which bore Christ, the divine Rain! Rejoice, ladder and throne of heaven! Rejoice, honored mountain of God, fruitful and unquarried!`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Liturgy, Beatitudes Theotokion`},sourceLabel:`Theotokion`}},prokeimenon:{tone:3,text:{text:`Chant unto our God, chant ye; * chant unto our King, chant ye.`,tier:2,src:{file:`3-1.pdf`,locus:`Sunday Liturgy prokeimenon`}},verse:{text:`Clap your hands all ye nations; shout unto God with a voice of rejoicing.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Liturgy prokeimenon verse`}}},alleluia:{tone:3,verses:[{text:`In Thee, O Lord, have I hoped; let me never be put to shame.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Liturgy Alleluia`}},{text:`Be Thou unto me a God to defend me, and a house of refuge to save me.`,tier:1,src:{file:`3-1.pdf`,locus:`Sunday Liturgy Alleluia verse 2`}}]}},vespers_weekday:{sun:{rubric:`On “Lord, I have cried ...,” 3 Stichera of compunction, in Tone III: Spec. Mel.: “Great is the power of Thy martyrs ...”:`,lic:{octoechos:[{text:`O heavenly father, accept me as Thou didst the repentant prodigal son, though I sin exceedingly and embitter Thee, the good Master Who art merciful by nature; and make me one of Thy hirelings.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-evening Vespers, LIC Octoechos sticheron 1`},label:`plain`,spec_mel:`Great is the power of Thy martyrs`},{text:`I have passed the time of my life in slothfulness and have drawn nigh to the end, wretch that I am. I give no thought to the judgment which awaiteth me, nor to my falling away from God. But, having turned me back to Thee, O Savior, rescue me from them.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-evening Vespers, LIC Octoechos sticheron 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`,spec_mel:`Great is the power of Thy martyrs`},{text:`From Gehenna, from the gnashing of teeth, and every other eternal retribution do Thou deliver my lowly soul, O supremely good Lord; that with faith I may hymn the merciful God, Who art by nature the Lover of mankind.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-evening Vespers, LIC Octoechos sticheron 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`,spec_mel:`Great is the power of Thy martyrs`}],octoechos_verses:[{text:`If Thou shouldest mark iniquities, O Lord, O Lord, who shall stand? * For with Thee there is forgiveness.`,tier:2,src:{file:`3-2.pdf`,locus:`Sunday-evening Vespers, LIC ladder verse 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}]},{text:`For Thy name’s sake have I patiently waited for Thee, O Lord; my soul hath waited patiently for Thy word, * my soul hath hoped in the Lord.`,tier:2,src:{file:`3-2.pdf`,locus:`Sunday-evening Vespers, LIC ladder verse 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]},{text:`From the morning watch until night, from the morning watch * let Israel hope in the Lord.`,tier:2,src:{file:`3-2.pdf`,locus:`Sunday-evening Vespers, LIC ladder verse 3`}}],menaion_rubric:`Then the Stichera from the Menaion; or if there is no Menaion, these Stichera of the holy incorporeal angels, in the same tone:`,menaion_fallback:[{text:`Thou didst create the choirs of incorporeal beings, O Lord, unto all showing forth the richness of Thy goodness; and out of non-existence Thou didst bring into being those who now glorify Thy glory with never silent voices.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-evening Vespers, Menaion-fallback sticheron 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Great is the power of Thine angels, O Christ; for, though bodiless, they protect the world, preserving the Churches by Thy power, O Master; and they entreat Thee on behalf of the whole world.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-evening Vespers, Menaion-fallback sticheron 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`Beholding Thy single and three-Sunned beauty, the hosts who minister to Thee reveal derivative splendors to those in the world; and shining forth as one, they impart divine glory unto us.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-evening Vespers, Menaion-fallback sticheron 3`},label:`plain`}],menaion_verses:[{text:`For with the Lord there is mercy, and with Him there is plenteous redemption; * and He shall redeem Israel out of all his iniquities.`,tier:2,src:{file:`3-2.pdf`,locus:`Sunday-evening Vespers, ladder tail verse 1`}},{text:`O praise the Lord, all ye nations; * praise Him, all ye peoples.`,tier:2,src:{file:`3-2.pdf`,locus:`Sunday-evening Vespers, ladder tail verse 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]},{text:`For He hath made His mercy to prevail over us, * and the truth of the Lord abideth forever.`,tier:2,src:{file:`3-2.pdf`,locus:`Sunday-evening Vespers, ladder tail verse 3`}}]},lic_theotokion:{text:`O most pure one, who hast dominion over all creation, by thy fervent intercession and maternal prayer free my mind, which is grievously beset by the passions, and enslave me to thy Son and God.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-evening Vespers, LIC Glory/Both-now closer`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],type:`theotokion`},prokeimenon:{ref:`shared.daily_vespers_prokeimena.sun`,rubric:`Then, “O Joyous Light ...,” the Prokeimenon, in Tone VIII:`},aposticha:{rubric:`Vouchsafe, O Lord ..., Litany: Let us complete ..., Then: On the Aposticha, these Stichera of compunction, in Tone III:`,items:[{text:`Our evening hymnody do we bring to Thee, O Christ, with incense and spiritual odes, Have mercy and save our souls.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-evening Vespers, aposticha item 1`},label:`plain`},{text:`Save me, O Lord my God, in so far as Thou art the salvation of all. For the storm of the passions disquieteneth me, and the yoke of my transgressions weigheth heavily upon me. Stretch out Thy helping hand and lead me up to the light of compunction, for Thou alone art compassionate and the Lover of mankind.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-evening Vespers, aposticha item 2`},label:`plain`},{text:`Great is the power of Thy Cross, O Lord! For though it was planted in one place, it worketh throughout the whole world, making apostles of fishermen and martyrs of the heathen, that they might pray for our souls.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-evening Vespers, aposticha item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`}],verses:{ref:`shared.weekday_aposticha_verses.sets.standard_vespers`}},aposticha_theotokion:{text:`O Lady, intercessor for all who pray to thee: In thee we find boldness, of thee do we boast, and in thee have we placed all our hope. Entreat Him Who was born of thee on behalf of thine unprofitable servants.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-evening Vespers, aposticha Glory/Both-now closer`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],type:`theotokion`},closing_rubric:`Then, “Now lettest Thou Thy servant depart ...,” Trisagion through Our`},mon:{rubric:`On “Lord, I have cried ...,” 3 Stichera of compunction, in Tone III: Spec. Mel.: “In crosswise manner ...”:`,lic:{octoechos:[{text:`Perceiving in me a slothfulness toward profitable works, the multifarious formed serpent transforms itself, luring me towards ever more bitter evils. By displaying for me the sweetness of sin, through his own bitter activity which is opposed to the commandments of God, he taketh advantage of my wicked character, O Christ, and seduceth me to accept evils as good.`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-evening Vespers, LIC Octoechos sticheron 1`},label:`plain`,spec_mel:`In crosswise manner`},{text:`Having eagerly trodden the whole path of iniquity and sin, and utterly departed from that which is straight, I have now drawn nigh to the gates of death; and, thereby trapped, I cry aloud: O my supremely good Jesus, Thou Path of our life, turn me to the broad expanse of true repentance; save and grant me correction; and before my death, grant me divine forgiveness!`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-evening Vespers, LIC Octoechos sticheron 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`,spec_mel:`In crosswise manner`},{text:`I have been slain by divers sins, by multitudes of transgressions and great misdeeds; and I lie dead, truly helpless. Only my hope in Thy loving-kindness remaineth alive, O Christ, Who dost grant both breath and life unto the dead and ever slayeth the passions which kill us. Wherefore, going before me, rescue me from everlasting death.`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-evening Vespers, LIC Octoechos sticheron 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`,spec_mel:`In crosswise manner`}],octoechos_verses:[{text:`If Thou shouldest mark iniquities, O Lord, O Lord, who shall stand? * For with Thee there is forgiveness.`,tier:2,src:{file:`3-3.pdf`,locus:`Monday-evening Vespers, LIC ladder verse 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}]},{text:`For Thy name’s sake have I patiently waited for Thee, O Lord; my soul hath waited patiently for Thy word, * my soul hath hoped in the Lord.`,tier:2,src:{file:`3-3.pdf`,locus:`Monday-evening Vespers, LIC ladder verse 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]},{text:`From the morning watch until night, from the morning watch * let Israel hope in the Lord.`,tier:2,src:{file:`3-3.pdf`,locus:`Monday-evening Vespers, LIC ladder verse 3`}}],menaion_rubric:`Then the Stichera from the Menaion; or if there is no Menaion, these Stichera of the holy forerunner, in the same tone:`,menaion_fallback:[{text:`O Forerunner, who in thy birth loosed the barrenness of thy mother and the muteness of thy father: By thy right acceptable supplications to the loving Son of the Father, the Master and God of all, Whom the Mind dispassionately begot as the Word, do away with the sterility of my heart and the irrationality of my soul, and strengthen me to say and do works of love for Him.`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-evening Vespers, Menaion-fallback sticheron 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Thou wast sent before the face of Christ to prepare His paths and make straight His ways. By thy supplications and manifest help, show my heart to be well trodden by Him. O thou who wast deemed worthy to appear at His precious feet, grant that I may walk the ground of heaven, which the feet of the meek tread, that with love I may honor thee as my mediator.`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-evening Vespers, Menaion-fallback sticheron 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`On earth thou didst emulate the life of the angels, O culmination of the prophets, first martyr of the New Covenant, who wast the first preacher to announce to those beneath the earth that the divine Word would descend thither, and wast borne witness to by Christ. O John the Baptist, friend of the Lamb and Redeemer, by thy supplications deliver thy servant from all the temptations of the enemy and from his multifarious trials.`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-evening Vespers, Menaion-fallback sticheron 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`}],menaion_verses:[{text:`For with the Lord there is mercy, and with Him there is plenteous redemption; * and He shall redeem Israel out of all his iniquities.`,tier:2,src:{file:`3-3.pdf`,locus:`Monday-evening Vespers, ladder tail verse 1`}},{text:`O praise the Lord, all ye nations; * praise Him, all ye peoples.`,tier:2,src:{file:`3-3.pdf`,locus:`Monday-evening Vespers, ladder tail verse 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]},{text:`For He hath made His mercy to prevail over us, * and the truth of the Lord abideth forever.`,tier:2,src:{file:`3-3.pdf`,locus:`Monday-evening Vespers, ladder tail verse 3`}}]},lic_theotokion:{text:`O blessed Mary, divinely joyous maiden, cloud of the never-waning Light: Shine the light of repentance upon me who am mindlessly stuck fast in the darkness of sin; and by thy supplications deliver me from the fire of Gehenna and the unremitting darkness, O most pure Virgin, and show me to share in the never- setting day, for I flee beneath thy protection.`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-evening Vespers, LIC Glory/Both-now closer`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],type:`theotokion`},prokeimenon:{ref:`shared.daily_vespers_prokeimena.mon`,rubric:`Then, “O Joyous Light ...,” the Prokeimenon, in Tone IV:`},aposticha:{rubric:`Vouchsafe, O Lord ..., Litany: Let us complete ..., Then: On the Aposticha, these Stichera of compunction, in Tone III:`,items:[{text:`Our evening hymn do we bring unto Thee, O Christ, * with incense and spiritual odes, ** Have mercy on us and save our souls.`,tier:2,src:{file:`3-3.pdf`,locus:`Monday-evening Vespers, aposticha item 1`},label:`plain`},{text:`Save me, O Lord my God, insofar as Thou art the salvation of all. For the storm of the passions disquieteneth me, and the yoke of my transgressions weigheth heavily upon me. Stretch out Thy helping hand and lead me up to the light of compunction, for Thou alone art compassionate and the Lover of mankind.`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-evening Vespers, aposticha item 2`},label:`plain`},{text:`Great is the power of Thy martyrs, O Christ; for while lying in their graves they drive evil spirits away; and, having struggled for piety with their faith in the Trinity, they abolished the authority of the enemy.`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-evening Vespers, aposticha item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`}],verses:{ref:`shared.weekday_aposticha_verses.sets.standard_vespers`}},aposticha_theotokion:{text:`O Theotokos - holy among women, thou Mother unwedded: entreat the King and God Whom thou didst bear, that He save us, insofar as He is the Lover of mankind.`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-evening Vespers, aposticha Glory/Both-now closer`},type:`theotokion`},closing_rubric:`Then, “Now lettest Thou Thy servant depart ...,” Trisagion through Our`},tue:{rubric:`On “Lord, I have cried ...,” 3 Stichera of the precious Cross, in Tone III: Spec. Mel.: “Great is the power of Thy Cross ...”:`,lic:{octoechos:[{text:`Creation was transformed by Thy crucifixion, O Word: the sun withdrew its rays in fear and the veil of the temple was rent in twain; and every one of the faithful is saved. Wherefore, we glorify Thine immeasurably abundant noetic riches.`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-evening Vespers, LIC Octoechos sticheron 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`,spec_mel:`Great is the power of Thy Cross`},{text:`God the Master, Who in His compassion assumed our flesh, having been well- pleased to be nailed to the Tree, and lifted up thereon bodily, hath thereby, in the tender compassion of His mercy, raised us up who were cast down.`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-evening Vespers, LIC Octoechos sticheron 2`},label:`plain`,spec_mel:`Great is the power of Thy Cross`},{text:`The world was renewed by the drops of divinely shed blood and water which flowed from Thy side, O Lord; for Thou dost wash away all sins with water, and as Thou art compassionate, dost grant us to partake of forgiveness by Thy blood.`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-evening Vespers, LIC Octoechos sticheron 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`,spec_mel:`Great is the power of Thy Cross`}],octoechos_verses:[{text:`If Thou shouldest mark iniquities, O Lord, O Lord, who shall stand? * For with Thee there is forgiveness.`,tier:2,src:{file:`3-4.pdf`,locus:`Tuesday-evening Vespers, LIC ladder verse 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}]},{text:`For Thy name’s sake have I patiently waited for Thee, O Lord; my soul hath waited patiently for Thy word, * my soul hath hoped in the Lord.`,tier:2,src:{file:`3-4.pdf`,locus:`Tuesday-evening Vespers, LIC ladder verse 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]},{text:`From the morning watch until night, from the morning watch * let Israel hope in the Lord.`,tier:2,src:{file:`3-4.pdf`,locus:`Tuesday-evening Vespers, LIC ladder verse 3`}}],menaion_rubric:`Then the Stichera from the Menaion; or if there is no Menaion, these Stichera of the most holy Theotokos, in the same melody:`,menaion_fallback:[{text:`Lying upon the bed of my negligence, I have reached the end of my Life in slothfulness; and I fear the hour of my departure. Yet, rousing me to repentance by thy supplication, O maiden, save me.`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-evening Vespers, Menaion-fallback sticheron 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Heal thou the sicknesses of my heart, bringing an end to the deception of my mind, O pure one, and grant that with a pure heart I may hymn thee, and ask grace, and find mercy on the day of judgment.`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-evening Vespers, Menaion-fallback sticheron 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Cast off the heavy burden of evil, and draw nigh, weeping and crying aloud: O pure Virgin, grant that I may bear the easy yoke of thy Son and God.`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-evening Vespers, Menaion-fallback sticheron 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`}],menaion_verses:[{text:`For with the Lord there is mercy, and with Him there is plenteous redemption; * and He shall redeem Israel out of all his iniquities.`,tier:2,src:{file:`3-4.pdf`,locus:`Tuesday-evening Vespers, ladder tail verse 1`}},{text:`O praise the Lord, all ye nations; * praise Him, all ye peoples.`,tier:2,src:{file:`3-4.pdf`,locus:`Tuesday-evening Vespers, ladder tail verse 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]},{text:`For He hath made His mercy to prevail over us, * and the truth of the Lord abideth forever.`,tier:2,src:{file:`3-4.pdf`,locus:`Tuesday-evening Vespers, ladder tail verse 3`}}]},lic_theotokion:{text:`A sword pierced thy heart, O most pure one, * when thou didst behold thy Son upon the Cross; * whereupon thou didst cry aloud: * “Show me not to be childless, O my Son and my God, ** Thou Who hast kept me a Virgin even after birthgiving!”`,tier:2,src:{file:`3-4.pdf`,locus:`Tuesday-evening Vespers, LIC Glory/Both-now closer`},type:`stavrotheotokion`,sourceLabel:`Stavrotheotokion`},prokeimenon:{ref:`shared.daily_vespers_prokeimena.tue`,rubric:`Then, “O Joyous Light ...,” the Prokeimenon, in Tone I:`},aposticha:{rubric:`Vouchsafe, O Lord ..., Litany: Let us complete ..., Then: On the Aposticha, these Stichera of the precious Cross, in Tone III:`,items:[{text:`I bow down, O Christ, before Thy precious Cross: the guardian of the world, the salvation of us sinners, the great purification and boast of the whole world.`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-evening Vespers, aposticha item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`The tree of disobedience put forth death for the world; but the Tree of the Cross hath put forth life and incorruption. Wherefore, we worship the crucified Lord, crying: Let the light of Thy countenance be signed upon us!`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-evening Vespers, aposticha item 2`},label:`plain`},{text:`The prophets, the apostles of Christ and the martyrs enlightened and taught the erring nations to hymn the consubstantial Trinity, and made the children of mankind companions of the angels.`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-evening Vespers, aposticha item 3`},label:`martyrs`}],verses:{ref:`shared.weekday_aposticha_verses.sets.standard_vespers`}},aposticha_theotokion:{text:`When Thy Mother, the unblemished Ewe-lamb who gave birth to Thee, saw Thee lifted up upon the Cross, O my Christ, she lamented and cried out, weeping: “Show me not to be childless, whom Thou didst preserve pure even after giving birth!”`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-evening Vespers, aposticha Glory/Both-now closer`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],type:`stavrotheotokion`,spec_mel:`Great is the power of Thy Cross`,sourceLabel:`Stavrotheotokion`},closing_rubric:`Then, “Now lettest Thou Thy servant depart ...,” Trisagion through Our`},wed:{rubric:`On “Lord, I have cried ...,” 3 Stichera of holy apostles, in Tone III: Spec. Mel.: “Great is the power of Thy martyrs, O Christ ...”:`,lic:{octoechos:[{text:`Through the supplications of Thine honored and divine apostles, O only Merciful and Compassionate Lover of mankind, grant Thy humility to Thy servants, and save from misfortunes those who hymn and worship Thee with faith.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-evening Vespers, LIC Octoechos sticheron 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`,spec_mel:`Great is the power of Thy martyrs, O Christ`},{text:`When with the Judge of all ye shall sit on twelve thrones to judge all creation, show me not to be condemned, but deliver me from darkness and all affliction, O divine apostles, my benefactors.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-evening Vespers, LIC Octoechos sticheron 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`,spec_mel:`Great is the power of Thy martyrs, O Christ`},{text:`As ye were eyewitnesses to God, deliver me from the arrows of the ungodly one, foiling his machinations; and bedew me with the dew of the Spirit, I pray you, O divine apostles, my wise benefactors.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-evening Vespers, LIC Octoechos sticheron 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`,spec_mel:`Great is the power of Thy martyrs, O Christ`}],octoechos_verses:[{text:`If Thou shouldest mark iniquities, O Lord, O Lord, who shall stand? * For with Thee there is forgiveness.`,tier:2,src:{file:`3-5.pdf`,locus:`Wednesday-evening Vespers, LIC ladder verse 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]},{text:`For Thy name’s sake have I patiently waited for Thee, O Lord; my soul hath waited patiently for Thy word, * my soul hath hoped in the Lord.`,tier:2,src:{file:`3-5.pdf`,locus:`Wednesday-evening Vespers, LIC ladder verse 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]},{text:`From the morning watch until night, from the morning watch * let Israel hope in the Lord.`,tier:2,src:{file:`3-5.pdf`,locus:`Wednesday-evening Vespers, LIC ladder verse 3`}}],menaion_rubric:`Then the Stichera from the Menaion; or if there is no Menaion, these Stichera of the holy hierarch Nicholas, the wonderworker, in the same melody:`,menaion_fallback:[{text:`Wretch that I am, I have been wounded by the sting of the serpent and lie downcast, dead, bereft of breath. But by thy vigilant supplications do thou quickly raise me up, O all-blessed hierarch, that I may glorify thy speedily attentive grace.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-evening Vespers, Menaion-fallback sticheron 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Seeing me lying before him, my mind darkened by evil thoughts, he of deceitful mind in nowise ceaseth his pursuit of me; but, in that Thou art God, have pity and save me, by the prayers of Nicholas.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-evening Vespers, Menaion-fallback sticheron 2`},label:`plain`},{text:`O most blessed Nicholas, thou hast been revealed as great salvation for all of us, for thou deliverest thy servants from all manner of misfortunes and perils, from temptations, infirmities and evil circumstances, and from the invisible foe.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-evening Vespers, Menaion-fallback sticheron 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`}],menaion_verses:[{text:`For with the Lord there is mercy, and with Him there is plenteous redemption; * and He shall redeem Israel out of all his iniquities.`,tier:2,src:{file:`3-5.pdf`,locus:`Wednesday-evening Vespers, ladder tail verse 1`}},{text:`O praise the Lord, all ye nations; * praise Him, all ye peoples.`,tier:2,src:{file:`3-5.pdf`,locus:`Wednesday-evening Vespers, ladder tail verse 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]},{text:`For He hath made His mercy to prevail over us, * and the truth of the Lord abideth forever.`,tier:2,src:{file:`3-5.pdf`,locus:`Wednesday-evening Vespers, ladder tail verse 3`}}]},lic_theotokion:{text:`Great is the power of thy wonders, O pure one! For thou dost deliver from misfortune, save from death, rescue from unexpected perils, release from tribulations, and wipe away the offenses of all mankind.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-evening Vespers, LIC Glory/Both-now closer`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],type:`theotokion`},prokeimenon:{ref:`shared.daily_vespers_prokeimena.wed`,rubric:`Then, “O Joyous Light ...,” the Prokeimenon, in Tone V:`},aposticha:{rubric:`Vouchsafe, O Lord ..., Litany: Let us complete ..., Then: On the Aposticha, these Stichera of the holy apostles, in Tone III:`,items:[{text:`Your sound went forth into all the earth, O holy apostles, destroying the deception of the idols, and preaching the knowledge of God. Behold, your struggle is good, O blessed ones; wherefore, we hymn and glorify your memory.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-evening Vespers, aposticha item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`As branches of the life-bearing Vine, O glorious apostles, ye brought yourselves to God as the fruit of piety; wherefore, as ye have boldness before Him, ask that He grant peace and great mercy to our souls.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-evening Vespers, aposticha item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Rendered steadfast by faith, strengthened by hope, and spiritually united by the love of Thy Cross, O Lord, Thy martyrs abolished the tyranny of the enemy; and having received crowns, with the incorporeal ones they pray for our souls.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-evening Vespers, aposticha item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`}],verses:{ref:`shared.weekday_aposticha_verses.sets.standard_vespers`}},aposticha_theotokion:{text:`O maiden, I have sinned exceedingly, do thou rescue me from the flame of want by thy great supplications, and set me aright O pure one by thine entreaties, and guide me to the paths of salvation by thy maternal supplications.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-evening Vespers, aposticha Glory/Both-now closer`},type:`theotokion`},closing_rubric:`Then, “Now lettest Thou Thy servant depart ...,” Trisagion through Our Father ..., Troparia. Litany: Have mercy on us ..., and Dismissal. WEDNESDAY NIGHT: TONE III AT COMPLINE Canon of supplication to the most holy Theotokos`},thu:{rubric:`On “Lord, I have cried ...,” 3 Stichera of the precious Cross, in Tone III: Spec. Mel.: “They set up ...”:`,lic:{octoechos:[{text:`O Lord, Who in Thy divine nature dost transcend suffering, but endured suffering in Thy human nature. Thou wast nailed to the Cross and pierced in the side by a spear, pouring forth upon me a pair of rivers, from whence flow ineffable mysteries.`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-evening Vespers, LIC Octoechos sticheron 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`,spec_mel:`They set up`},{text:`With mockery Thou wast wounded by the plaited crown of thorns, O King and Savior of all, tearing apart the proscription of thorny sin; And having taken the reed in Thy hands, Thou hast recorded in the book of heaven all of us who believe in Thee.`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-evening Vespers, LIC Octoechos sticheron 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`,spec_mel:`They set up`},{text:`The undeserved envy of the Jews who crucified Thee did not cease even when Thou wast dead, O innocent Christ; but the wicked ones slandered Thee as a liar and asked Pilate to guard Thy tomb. O what incurable wrath!`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-evening Vespers, LIC Octoechos sticheron 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`,spec_mel:`They set up`}],octoechos_verses:[{text:`If Thou shouldest mark iniquities, O Lord, O Lord, who shall stand? * For with Thee there is forgiveness.`,tier:2,src:{file:`3-6.pdf`,locus:`Thursday-evening Vespers, LIC ladder verse 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}]},{text:`For Thy name’s sake have I patiently waited for Thee, O Lord; my soul hath waited patiently for Thy word, * my soul hath hoped in the Lord.`,tier:2,src:{file:`3-6.pdf`,locus:`Thursday-evening Vespers, LIC ladder verse 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]},{text:`From the morning watch until night, from the morning watch * let Israel hope in the Lord.`,tier:2,src:{file:`3-6.pdf`,locus:`Thursday-evening Vespers, LIC ladder verse 3`}}],menaion_rubric:`Then the Stichera from the Menaion; or if there is no Menaion, these Stichera of the most holy Theotokos, in the same tone:`,menaion_fallback:[{text:`When thou didst behold Him Who is the never-setting Sun setting upon the Cross, even He Who shone forth from thy womb and sustaineth the brilliance of the sun, thou didst cry aloud, thy soul weighed down by ten thousand griefs: “O Thou Who hast willingly set, Thou shalt shine forth again, for the enlightenment of me and the world!”`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-evening Vespers, Menaion-fallback sticheron 1`},label:`plain`},{text:`O Lady who hast given birth unto Him Who will come to judge the living and the dead: Through repentance and by the divine blood which flowed from the side of thy Son enliven my soul, which hath been slain by sickness, and show me to be a doer of His commandments of life.`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-evening Vespers, Menaion-fallback sticheron 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`She who once painlessly gave birth to Thee as a child, the Ewe-lamb and Mother, said: “In birthgiving I escaped sorrow and the gloom of griefs, but now beholding Thee lifted up upon the Cross, my womb and heart are wounded with bitter arrows, O Master, and I am sunk in immeasurable grief.”`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-evening Vespers, Menaion-fallback sticheron 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`}],menaion_verses:[{text:`For with the Lord there is mercy, and with Him there is plenteous redemption; * and He shall redeem Israel out of all his iniquities.`,tier:2,src:{file:`3-6.pdf`,locus:`Thursday-evening Vespers, ladder tail verse 1`}},{text:`O praise the Lord, all ye nations; * praise Him, all ye peoples.`,tier:2,src:{file:`3-6.pdf`,locus:`Thursday-evening Vespers, ladder tail verse 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]},{text:`For He hath made His mercy to prevail over us, * and the truth of the Lord abideth forever.`,tier:2,src:{file:`3-6.pdf`,locus:`Thursday-evening Vespers, ladder tail verse 3`}}]},lic_theotokion:{text:`“Through Thy crucifixion the world hath found mercy, creation hath been illumined, and the nations have received salvation, O Master,” cried the most pure one; “But I am now rent apart, beholding Thy voluntary suffering.”`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-evening Vespers, LIC Glory/Both-now closer`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],type:`stavrotheotokion`,sourceLabel:`Stavrotheotokion`},prokeimenon:{ref:`shared.daily_vespers_prokeimena.thu`,rubric:`Then, “O Joyous Light ...,” the Prokeimenon, in Tone VI:`},aposticha:{rubric:`Vouchsafe, O Lord ..., Litany: Let us complete ..., Then: On the Aposticha, these Stichera of the precious Cross, in Tone III:`,items:[{text:`I bow down, O Christ, before Thy precious Cross: the guardian of the world, the salvation of us sinners, the great purification and boast of the whole world.`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-evening Vespers, aposticha item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Lifting up his arms in the form of the Cross on the mountain, Moses vanquished Amalek; and Thou, O Savior, stretched out upon the precious Cross, embraced me, saving me from slavery to the enemy, and didst give it to me as the sign of life, enabling me to evade the arrows of mine adversaries. Wherefore, O Word, I bow down before Thy precious Cross.`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-evening Vespers, aposticha item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`Great is the power of Thy Cross, O Lord! For though it was planted in one place, it worketh throughout the whole world, making apostles of fishermen and martyrs of the heathen, that they might pray for our souls.`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-evening Vespers, aposticha item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`}],verses:{ref:`shared.weekday_aposticha_verses.sets.standard_vespers`}},aposticha_theotokion:{text:`The all-immaculate one, beholding Thee lifted up upon the Tree, cried out, weeping maternally: “O my supremely good Christ, my most beloved Son! How hath the iniquitous assembly lifted Thee up upon the Cross?”`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-evening Vespers, aposticha Glory/Both-now closer`},type:`stavrotheotokion`,sourceLabel:`Stavrotheotokion`},closing_rubric:`Then, “Now lettest Thou Thy servant depart ...,” Trisagion through Our`},fri:{rubric:`On “Lord, I have cried ...,” 3 Stichera of the righteous ones, in Tone III: Spec. Mel.: “Great is the power of Thy martyrs, O Christ ...”:`,lic:{octoechos:[{text:`Having endured wounds, fetters and divers tortures, suffering mightily, the valiant martyrs were brought to their divine inheritance which is truly devoid of pain, the heritage of their pangs.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-evening Vespers, LIC sticheron 1`},label:`plain`,provenance_note:`On “Lord, I have cried ...,” 3 Stichera of the righteous ones, in Tone III: Spec. Mel.: “Great is the power of Thy martyrs, O Christ ...”:`},{text:`O holy hierarchs of the Lord, who piously uttered divine discourse, and thereby set at naught all the arguments of the heretics, showing yourselves to be exceedingly sure paragons for all the faithful; wherefore ye are honored.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-evening Vespers, LIC sticheron 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`,provenance_note:`On “Lord, I have cried ...,” 3 Stichera of the righteous ones, in Tone III: Spec. Mel.: “Great is the power of Thy martyrs, O Christ ...”:`},{text:`While in your material bodies, ye emulated the ranks of the immaterial and incorporeal beings, O God-bearing fathers, most gloriously exhibiting their manner of life; wherefore, ye dwell in their habitations.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-evening Vespers, LIC sticheron 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`,provenance_note:`On “Lord, I have cried ...,” 3 Stichera of the righteous ones, in Tone III: Spec. Mel.: “Great is the power of Thy martyrs, O Christ ...”:`},{text:`Great is the power of Thy Cross, O Lord! For though it was planted in one place, it worketh throughout the whole world, making apostles of fishermen and martyrs of the heathen, that they might pray for our souls.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-evening Vespers, LIC sticheron 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`,provenance_note:`Then these other Stichera, of the holy martyrs, in the same melody:`},{text:`Great is the power of Thy martyrs, O Christ; for while lying in their graves they drive evil spirits away; and, having struggled for piety with their faith in the Trinity, they abolished the authority of the enemy.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-evening Vespers, LIC sticheron 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`,provenance_note:`Then these other Stichera, of the holy martyrs, in the same melody:`},{text:`The prophets, the apostles of Christ and the martyrs enlightened and taught the erring nations to hymn the consubstantial Trinity, and made the children of mankind companions of the angels.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-evening Vespers, LIC sticheron 6`},label:`plain`,provenance_note:`Then these other Stichera, of the holy martyrs, in the same melody:`}],octoechos_verses:[{text:`If Thou shouldest mark iniquities, O Lord, O Lord, who shall stand? * For with Thee there is forgiveness.`,tier:2,src:{file:`3-7.pdf`,locus:`Friday-evening Vespers, LIC ladder verse 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}]},{text:`For Thy name’s sake have I patiently waited for Thee, O Lord; my soul hath waited patiently for Thy word, * my soul hath hoped in the Lord.`,tier:2,src:{file:`3-7.pdf`,locus:`Friday-evening Vespers, LIC ladder verse 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]},{text:`From the morning watch until night, from the morning watch * let Israel hope in the Lord.`,tier:2,src:{file:`3-7.pdf`,locus:`Friday-evening Vespers, LIC ladder verse 3`}},{text:`For with the Lord there is mercy, and with Him there is plenteous redemption; * and He shall redeem Israel out of all his iniquities.`,tier:2,src:{file:`3-7.pdf`,locus:`Friday-evening Vespers, LIC ladder verse 4`}},{text:`O praise the Lord, all ye nations; * praise Him, all ye peoples.`,tier:2,src:{file:`3-7.pdf`,locus:`Friday-evening Vespers, LIC ladder verse 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]},{text:`For He hath made His mercy to prevail over us, * and the truth of the Lord abideth forever.`,tier:2,src:{file:`3-7.pdf`,locus:`Friday-evening Vespers, LIC ladder verse 6`}}]},lic_theotokion:{text:`How can we, O all-honored one, * not marvel at thine Offspring? * Who is both God and man. * For without knowing a man, O all-immaculate one, * without a father thou hast given birth to a Son in the flesh, * who without a mother was begotten from the Father before all ages, * yet in no way undergoing change, fusion or separation, * but preserving fully the characteristics of both natures. * Wherefore, O Lady, and Virgin Mother, * beseech Him to save the souls of those ** who with Orthodox faith confess thee to be the true Theotokos.`,tier:2,src:{file:`3-7.pdf`,locus:`Friday-evening Vespers, LIC Glory/Both-now closer — the dogmatikon printed IN FULL as its own site (§9.2)`},type:`dogmatic_theotokion`,sourceLabel:`Glory ..., Both now ..., Dogmatic Theotokion:`},prokeimenon:{ref:`shared.daily_vespers_prokeimena.fri`,rubric:`Then, “O Joyous Light ...,” the Prokeimenon, in Tone VII:`},aposticha:{rubric:`Vouchsafe, O Lord ..., Litany: Let us complete ..., Then: On the Aposticha, these Stichera, in Tone III:`,items:[{text:`Made steadfast by faith, strengthened by hope, and spiritually united by the love of Thy Cross, O Lord, Thy martyrs put an end to the tyranny of the enemy and have received crowns; and with the incorporeal ones they pray on behalf of our souls.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-evening Vespers, aposticha item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`All things human, which endure not after death, are vain. Our wealth will not remain, our glory will not go with us upon the way: for when death cometh, all these things will fade away. Wherefore let us cry out to Christ the immortal King: Grant rest to our departed brethren, where all who rejoice have their abode with Thee.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-evening Vespers, aposticha item 2`},label:`for_the_reposed`},{text:`O race of mankind, why are ye rebellious in vain? Short is the course on which we run. Life is but smoke, vapor, ashes and dust; No sooner doth it appear, than it quickly vanisheth. Wherefore let us cry unto Christ the immortal King: Grant rest to our departed brethren, where all who rejoice have their abode with Thee.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-evening Vespers, aposticha item 3`},label:`for_the_reposed`}],verses:[{text:`Blessed are they whom Thou hast chosen * and taken to Thyself, O Lord.`,tier:2,src:{file:`3-7.pdf`,locus:`Friday-evening Vespers aposticha, departed verse 1 (final period present, unlike the 2-7 print — §5 per-tone)`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]},{text:`Their souls * shall dwell among good things.`,tier:2,src:{file:`3-7.pdf`,locus:`Friday-evening Vespers aposticha, departed verse 2`}}]},aposticha_theotokion:{text:`O Theotokos - holy among women, * thou Mother unwedded: * entreat the King and God Whom thou didst bear, * that He save us, ** insofar as He is the Lover of mankind.`,tier:2,src:{file:`3-7.pdf`,locus:`Friday-evening Vespers, aposticha Glory/Both-now closer`},type:`theotokion`},closing_rubric:`Then, “Now lettest Thou Thy servant depart ...,” Trisagion through Our`}},compline:{sun:{canon:{title:`Canon of supplication to the most holy Theotokos`,heading_rubric:`Canon of supplication to the most holy Theotokos`,odes:{1:{irmos:{text:`He who of old gathered the waters * into one by His divine decree, * divided the sea for the people of Israel. * For He is our God and supremely glorious, * to Him alone let us sing, for He hath been glorified.`,tier:2,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 1 irmos`}},items:[{text:`O most holy Virgin Mary who alone art of great renown, more glorious than, the cherubim, O daughter of David and beauty of Jacob, the Mother of our God: thy glory hath been magnified exceedingly, and we all glorify thee with faith.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 1, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`Thou didst bear in thine arms as a man Him Who stretched out the sky like a skin by His word. Wherefore, do thou constantly beseech Him, O pure one, that He deliver my soul from the irrationality of the passions and from all sorrow.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 1, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O Virgin who wast foretold before all ages, thou art the most pure purple robe of the King of glory, wherein He Who had clothed our forefather Adam in garments of skin clad Himself in the latter days: cover me also with thy protection.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 1, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`O Virgin who hast given birth to Christ, thou hast extinguished the unbearable fire of sin, which of old wrought corruption for the race of mankind. Wherefore, dry up the torrents of the passions of my soul by thy prayers.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 1, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},3:{irmos:{text:`O Most High, Ruler of all, * who out of nothing hath established all things, * fashioned by Thy Word, * perfected by the Spirit, * confirm me in Thy love.`,tier:2,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 3 irmos`}},items:[{text:`The Master and Lord Who hath dominion over fire hath been called thy Son, O pure one; wherefore, deliver me from the works of the passions by thine intercessions, O Lady.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 3, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`From the tempest of carnal passions do thou quickly deliver me, thy servant, O most pure one who hast given birth to the Calm of salvation and the Wellspring of dispassion.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 3, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`As the luminous lampstand of the never-waning Light, O most pure one, thou hast enlightened the world. Wherefore, with thy beams dispel the clouds from my soul.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 3, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`O Lady who hast given birth ineffably to Christ, the Bestower of life, enliven me who am dead of soul because of the multitude of mine evil passions.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 3, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]},4:{irmos:{text:`Thou hast shown us steadfast love, O Lord, * for Thou gavest Thine only-begotten Son over to death for our sake. * Wherefore with thanksgiving we cry unto Thee, * ‘Glory to Thy power, O Lord!’`,tier:2,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 4 irmos`}},items:[{text:`The siege of carnal understanding hath beset me and made my soul captive; yet do thou, O Lady who hast given birth to the Mind which transcendeth all the understanding of the world, grant me thy peace.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 4, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`From thy womb thou didst pour forth the noetic Myrrh upon the world; wherefore, free my soul from the defilements of the passions, O most pure one, and grant me the myrrh of dispassion by thy supplications.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 4, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Knowing thee to be the golden jar manifestly holding Christ, the God-man, the Manna of life, I pray: feed thou my soul which is famished with hunger, and give it the torrent of the Spirit to drink.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 4, item 3`},label:`glory`},{text:`Of old, unrestrained, Eve brought about death; but thou hast brought about true life by thy pure virginity. Wherefore, deliver me from a sinful death by thy supplications.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 4, item 4`},label:`both_now`}]},5:{irmos:{text:`The Invisible One hath appeared on earth, * and the Unapproachable One hath willingly dwelt among mankind; * and, rising early at dawn, we hymn Thee, * O Lover of mankind.`,tier:2,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 5 irmos`}},items:[{text:`As our deliverance, thy Son hath delivered all from corruption, O Virgin; wherefore, deliver me from a carnal understanding and from the presence of the passions.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 5, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`By the fire of thy prayers burn up all the thorns of my passion-filled thoughts, O Theotokos who hast purified the nature of man as with tongs and ember.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 5, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Thou art the divine heifer of the divine Bullock Who in His love for mankind was slaughtered for our sake. With His divine blood do thou purify my heart.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 5, item 3`},label:`glory`},{text:`Of old I acquired the beautiful robe of the virtues, yet I have cast it off in my slothfulness; but do thou, O Virgin, now clothe me in one that is yet more splendid by thy supplications.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 5, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]},6:{irmos:{text:`The uttermost depths of sin have surrounded me, * and my spirit perisheth, * but do Thou, O Master, stretch forth Thy lofty arm * and like Peter O Helmsman, * do Thou save me.`,tier:2,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 6 irmos`}},items:[{text:`The cruel wiles of evil have shaken the temple of my soul, yet do thou who hast given birth to Christ, Who established the earth upon the waters, make me steadfast by thy prayers.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 6, item 1`},label:`plain`},{text:`In giving birth to the Pearl of great price, thou hast released mortals from their debt; wherefore, O most pure one, quickly loose the bonds of my transgressions, passions and sorrows.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 6, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`The supremely good God Who was born from thy womb hath given thee to the faithful as a refuge and divine protection; wherefore, O most pure one, cover me with thy hands, and preserve me.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 6, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`Often engulfed in frenzy by the billows of life, and ever tempest- tossed by the works of the enemy, I now cry out to thee: O Theotokos, help me!`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 6, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]},7:{irmos:{text:`As of old Thou didst bedew * the three pious children in the Chaldean flames, * so also with the radiant fire of Thy divinity * illumine us who cry to Thee, * ‘Blessed art Thou, the God of our fathers!’`,tier:2,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 7 irmos`}},items:[{text:`Crowds of wicked demons and hordes of carnal passions have surrounded me; yet as thou hast given birth to Christ, Who is mighty in battles, deliver me from frequent griefs and cruel falls.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 7, item 1`},label:`plain`},{text:`He Who alone cannot be approached by the cherubic beings and is held in awe by the ranks of the angels made His abode within thee, O pure one, and hath renewed us. O Lady, through Him render me terrible to invisible foes.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 7, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`O Virgin, thou wast a noetic garden of paradise which put forth the Tree of life; and Adam, partaking thereof, hath been delivered from, the fruit of death. Wherefore, bring sweetness to me now, and deliver me from the taste of the passions.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 7, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`Deliver me from the mire of the passions of my body, and from the temptations of the demons, O thou who hast given birth to the Redeemer for our sake, as the habitation of the Most High and hallowed temple of the God of our fathers.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 7, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]},8:{irmos:{text:`United together in the unbearable fire, * yet not harmed by the flame, * the children, champions of godliness, sang a divine hymn: * O all ye works of the Lord, * bless ye the Lord and supremely exalt Him throughout all ages.`,tier:2,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 8 irmos`}},items:[{text:`O cloud of the Light Who fashioned the great luminaries in the universe: with thy rays dispel all the darkness, day and night, of all my passions and transgressions, and show me to be a child of the light, O Birthgiver of God.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 8, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`By the Rain which descended from heaven into thy womb, O Theotokos, enlighten and bedew my soul and heart, and extinguish the flame of passions and sorrows, that I may glorify thee fervently throughout all ages.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 8, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O pure one, thou didst give birth ineffably to the Wisdom of God which united the earthly and the heavenly, bringing all things forth from nonexistence; by His word grant me wisdom and understanding, that I may hymn clearly thy divine birthgiving.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 8, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`O Sovereign Lady of the world, I cry aloud and pray that my soul and body may be bedewed through thy supplications, and that I may be quickly delivered from the pangs of sin and the evil of the passions; for thou art the healing of all mankind.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 8, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]},9:{irmos:{text:`Upon Mount Sinai Moses saw thee in the bush, * as one who didst conceive the fire of the Godhead within thy womb, * and yet remained unconsumed. * Daniel saw thee as a mountain not cut by the hand of man, * and Isaiah proclaimed thee as the Rod that blossomed forth * from the root of David.`,tier:2,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 9 irmos`}},items:[{text:`Thou wast shown to be cloth divinely woven for Christ, from whence the Spirit prepared the divine raiment of the flesh. Wherefore, by thy supplications, O pure one, clothe me also in the vesture of chastity.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 9, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O noetic vine who hast put forth for us the divine Grapes, by Whom we have been given the water of incorruption to drink: by thy prayers pour forth upon my soul compunction and the wine of purification.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 9, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O pure and holy bridal chamber, by whose nature God wedded His nature to that of mortals, I beseech thee: unite me to thy Son, and impart unto me divine life by thy prayers.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 9, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`O Virgin who hast given birth to Christ, the Wellspring of incorruption, thou hast transformed the pasture of corrupt human nature. Wherefore, by thy supplications deaden the stormy assaults of the passions which consume me.`,tier:1,src:{file:`3-2.pdf`,locus:`Sunday-night Compline canon, Ode 9, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]}}},after_ode6:{rubric:`Lord, have mercy, (Thrice). Glory ..., Both now ..., Sessional Hymn, in Tone III:`,sessional:{text:`Thou wast the divine tabernacle of the Word, * O only all-pure Virgin Mother * who surpassed the angels in purity. * By the divine waters of thy supplications * cleanse me who, more than all others, * have become dust, defiled by carnal transgressions; ** and grant me great mercy, O pure one.`,tier:2,src:{file:`3-2.pdf`,locus:`Sunday-night Compline, sessional after Ode VI`},spec_mel:`Of the divine Faith`}},closing_rubric:`Then, “It is truly meet to bless thee ...,” and a prostration. Trisagion through Our Father ..., Troparion. The rest as usual. Dismissal.`},mon:{canon:{title:`Canon of supplication to the most holy Theotokos`,heading_rubric:`Canon of supplication to the most holy Theotokos`,odes:{1:{irmos:{text:`He who of old gathered the waters * into one by His divine decree, * divided the sea for the people of Israel. * For He is our God and supremely glorious, * to Him alone let us sing, for He hath been glorified.`,tier:2,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 1 irmos`}},items:[{text:`Having lived out my life in slothfulness, I have drawn nigh unto the end of my life; yet do thou thyself, O most pure one, if but one last time, grant me compunction, I pray, that I may weep bitterly over my countless transgressions.`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 1, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`With the passions of my flesh, O Virgin, I have mindlessly defiled the beauty of the divine image, and am afraid of God’s displeasure and the terrible threat of fire; yet do thou thyself have mercy upon me who flee to thee.`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 1, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Falling to my knees, wretch that I am, I beg thy help, O most holy Virgin: hearken thou to my pain-wracked soul, and by the radiance of thy prayers dispel the cloud of grief which weighs heavily upon me.`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 1, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`Grant that the furrows of my passion-plagued soul may be watered abundantly with tears, and grant that I may produce fruit an hundredfold, O Lady; and fill my heart with all manner of gladness, that I may glorify thee.`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 1, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]},3:{irmos:{text:`O Most High, Ruler of all, * who out of nothing hath established all things, * fashioned by Thy Word, * perfected by the Spirit, * confirm me in Thy love.`,tier:2,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 3 irmos`}},items:[{text:`O good Theotokos, grant me a torrent of tears, and thereby quench the furnace of my passions, and wash away all defilement from my soul.`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 3, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`In iniquities have I defiled the nobility of my soul, O most pure one, and I tremble at the thought of the interrogation, when the Word will examine the state of my worthiness.`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 3, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Beset now by the tempest of transgressions, I have been brought down into the abyss of despair; yet grant me thy hand, O pure one, and lead me to repentance.`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 3, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`Deliver thy servant from Gehenna and every other threat at the hour of judgment, O most immaculate one, and cause me to share in the kingdom of thy Son and God.`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 3, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]},4:{irmos:{text:`Thou hast shown us steadfast love, O Lord, * for Thou gavest Thine only-begotten Son over to death for our sake. * Wherefore with thanksgiving we cry unto Thee, * ‘Glory to Thy power, O Lord!’`,tier:2,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 4 irmos`}},items:[{text:`The waters of unseemly deeds have flooded my wretched soul, O pure one; wherefore, beset by worldly thoughts, I cry out in pain: Spurn not thy servant, O Lady!`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 4, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`Noetic beasts have now mercilessly surrounded me and have striven pitilessly to seize my lowly soul, O all-immaculate one; yet do thou, O most pure one, break their soul-destroying jaws.`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 4, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`O all-pure Lady, be thou merciful to thy servant, I pray, and rescue thy people from the coming threat, that we may cry out to thee in thanksgiving: Glory to Thee, O Queen of all!`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 4, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`glory`},{text:`When the Bridegroom will come at night to judge the earth, O most pure one, then be thou well-pleased that I may go forth to meet Him with a lighted lamp, and may worship His coming.`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 4, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]},5:{irmos:{text:`The Invisible One hath appeared on earth, * and the Unapproachable One hath willingly dwelt among mankind; * and, rising early at dawn, we hymn Thee, * O Lover of mankind.`,tier:2,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 5 irmos`}},items:[{text:`Many dogs have truly set themselves against me, and a horde of evil spirits have surrounded me; yet set their counsels now at naught, O most pure one.`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 5, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Having dug now a pit for me, the evil one strives to cast me into it; yet with thy right hand, O Lady, may he fall into the pit which he hath made.`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 5, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Let me not be denounced by the wrath of thy Son at the time of His coming, neither let me be punished by His anger, O all-hymned one; but save me by thine entreaties.`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 5, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`Behold my weakness, behold the lowliness of my soul, O pure one, and the uprising of mine incorporeal enemies; and deliver me from their harm.`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 5, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]},6:{irmos:{text:`The uttermost depths of sin have surrounded me, * and my spirit perisheth, * but do Thou, O Master, stretch forth Thy lofty arm * and like Peter O Helmsman, * do Thou save me.`,tier:2,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 6 irmos`}},items:[{text:`At the behest of the Creator of all, when my soul must needs part from the flesh, O all-immaculate and all-hymned Theotokos, free me from the hands of those who hate me.`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 6, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`With streams of compunction dry up the turbulent rivers of my wicked deeds, O Birthgiver of God, and guide me to the waters of tranquility on the day of judgment.`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 6, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Thou knowest the weakness of my soul, the feebleness of my mind and the infirmity of my flesh, O most pure one. Wherefore, save thy servant, for thee have I acquired as an invincible ally.`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 6, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`Grant me streams of spiritual tears, O most immaculate Lady, whereby I may wash away the mire of my transgressions, the tumult of the passions and the defilement of my body.`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 6, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]},7:{irmos:{text:`Of old the three children did not worship the golden image, * of the Persian idol, * but chanted in the midst of the furnace: * O God of our fathers, blessed art Thou!`,tier:2,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 7 irmos`}},items:[{text:`The waters of transgressions have been poured out upon me and my soul drowns, O pure one, and the uttermost abyss hath engulfed me; yet rescue me from its threefold billows.`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 7, item 1`},label:`plain`},{text:`Sprinkle me with the blood which flowed from the side of thine Offspring and by the multitude of thy mercies; wash thou and cleanse me of all defilement with streams of tears.`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 7, item 2`},label:`plain`},{text:`Grant thou contrition to my soul and humility to my heart, O all- pure one, that I may be delivered from all the wiles of those who ever pitilessly pursue me.`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 7, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`As thou art merciful, O Lady Mother of God, grant mercy to those who with faith cry out to thy Son: O God of our fathers, blessed art Thou!`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 7, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`both_now`}]},8:{irmos:{text:`United together in the unbearable fire, * yet not harmed by the flame, * the children, champions of godliness, sang a divine hymn: * O all ye works of the Lord, * bless ye the Lord and supremely exalt Him throughout all ages.`,tier:2,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 8 irmos`}},items:[{text:`With the might of thy Son thou hast broken the arrows of the archer, O pure one. Let his unrighteousness now descend upon his own head, that I may cry out: All ye works of the Lord, hymn the Lord and supremely exalt Him throughout the ages!`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 8, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`With thy light do thou illumine my darkened heart, O maiden, and with the sword of light open thou the portals of light to me who cry: All ye works of the Lord, hymn the Lord and supremely exalt Him throughout the ages!`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 8, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Falling into the sleep of death, I lie in the grave of despondency; yet do thou thyself raise me up, O Virgin, and grant that I may chant with vigilance: All ye works of the Lord, hymn the Lord and supremely exalt Him throughout the ages!`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 8, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`O pure one, cease thou never to pray for those who honor thee, that, delivered in compunction from the snares of the devil, we may cry out to thy Son: All ye works of the Lord, hymn the Lord and supremely exalt Him throughout the ages!`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 8, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]},9:{irmos:{text:`In the shadow and the letter of the Law, * let us, the faithful, discern a figure: * every male child that openeth the womb * shall be sanctified to God. * Therefore we magnify the firstborn Word * and Son of the beginningless Father, * the firstborn Child of a Mother who hath not known a man.`,tier:2,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 9 irmos`}},items:[{text:`The turbulence of the passions and the turmoil of vile thoughts bestorm my soul, and evil men ever smite me like a tempest; yet as thou lovest mankind, O Virgin, quickly deliver me from my besetting needs`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 9, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O my lowly soul, leave off thy wicked deeds and cease from doing evil and angering God; but earnestly embrace His commandments, for thou hast the Theotokos directing thy ways.`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 9, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`As thou hast given birth to the Lord of all, free me from the passions and from grievous sins, and in thy surpassing loving-kindness enrich me wholly with good works, that, rejoicing, I may magnify thee, O all-immaculate one.`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 9, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`The end approacheth, O my soul, judgment is at the door! Forsake thy shameful works and undertake to live a good life; for thou hast the Theotokos as thine ally, delivering thee from all oppression.`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-night Compline canon, Ode 9, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]}}},after_ode6:{rubric:`Lord, have mercy, (Thrice). Glory ..., Both now ..., Sessional Hymn, in Tone III:`,sessional:{text:`O Lady who bore the Merciful One within thy womb, have pity on me who flee beneath thy protection and with all my soul ask thy divine help, and grant mercy unto me when we will stand before the Author of creation, O pure one, and deliver me from everlasting fire and all condemnation.`,tier:1,src:{file:`3-3.pdf`,locus:`Monday-night Compline, sessional after Ode VI`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],spec_mel:`Awed by the beauty of thy virginity`}},closing_rubric:`Then, “It is truly meet ...,” and a prostration. Trisagion through Our Father ..., Troparion. The rest as usual, and the dismissal.`},tue:{canon:{title:`Canon of supplication to the most holy Theotokos`,heading_rubric:`Canon of supplication to the most holy Theotokos`,odes:{1:{irmos:{text:`He who of old gathered the waters * into one by His divine decree, * divided the sea for the people of Israel. * For He is our God and supremely glorious, * to Him alone let us sing, for He hath been glorified.`,tier:2,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 1 irmos`}},items:[{text:`Knowing thee, the Mother of God, to be a wellspring of loving-kindness and mercy, approaching thy goodness, I pray: Grant me compunction, that I may grieve and weep over my transgressions, O all-pure Lady.`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 1, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Grant me drops of spiritual tears to wash away all the defilement of my acts and wicked thoughts, to cleanse my soul of impurity and make me a temple of the divine Spirit.`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 1, item 2`},label:`plain`},{text:`Beset by the waves and threefold billows of my transgressions, and ever cruelly drowned by the works of the adversary, sinking now into the abyss of destruction, I cry to thee, O most immaculate one: Save me!`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 1, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`For the sake of thy tender compassion, O Lady of all, have mercy on my wretched soul, and deliver me from everlasting fire and the assault of the demons, for I flee now beneath thy protection, O Theotokos.`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 1, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`both_now`}]},3:{irmos:{text:`O Most High, Ruler of all, * who out of nothing hath established all things, * fashioned by Thy Word, * perfected by the Spirit, * confirm me in Thy love.`,tier:2,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 3 irmos`}},items:[{text:`With divine light illumine my mind, which hath been darkened by evil thoughts, O all-hymned one; for thou hast given birth to the everlasting Light Who hath shone forth from the Father.`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 3, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Tripping the feet of my soul, the enemy of the righteous hath caused me to fall to the ground; yet with thy right hand, O pure Lady, raise me up again.`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 3, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`With the voice of the publican I cry to thee, wretch that I am: Cleanse me, O Lady, and by thy supplication grant remission of sins unto thy servant.`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 3, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`Heal thou the wounds of my soul, O Lady, and still the most turbulent waves of my thoughts; and grant me the armor of peace.`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 3, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]},4:{irmos:{text:`Thou hast shown us steadfast love, O Lord, * for Thou gavest Thine only-begotten Son over to death for our sake. * Wherefore with thanksgiving we cry unto Thee, * ‘Glory to Thy power, O Lord!’`,tier:2,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 4 irmos`}},items:[{text:`I have defiled my flesh with pleasures and luxuries, and have besmirched the purity of my soul with vile thoughts, darkening my mind. O Lady, disdain not thy servant.`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 4, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Be thou my deliverance, refuge and might, the horn of my salvation, O pure helper, ever delivering me from all sorrow and putting all mine enemies to shame.`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 4, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`I am now beset by many perils, wretch that I am, and am ever engulfed by the wiles of the demons; yet I flee to thee now; by thy fervent supplication save me, thy servant.`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 4, item 3`},label:`glory`},{text:`The night of the passions, devoid of light, embraceth me, wretch that I am; yet by thy light, O good one, dispel the clouds of my soul and guide me to the light of the precepts of God, O all-immaculate one.`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 4, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`both_now`}]},5:{irmos:{text:`In a vision Isaiah saw upon a throne, * God lifted up on high * borne aloft by angels of glory; * and he cried: ‘Woe is me! * For I have foreseen God made flesh, * the Lord of the never-setting light * and the King of peace.’`,tier:2,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 5 irmos`}},items:[{text:`The time of my life hath vanished like smoke, and I have arrived at the gateway of death. I fear the assault of the demons, for I have ever done their works. O all-immaculate one, have pity and save me!`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 5, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Drying up the abyss of mine evils, O Virgin, grant me rivers of tears. Quench all the flame of my passions, O maiden, and grant that I may be delivered from fire and other torments on the day of judgment.`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 5, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`With the oil of thy mercy heal my soul which is tormented with the pain of my sins, and grant that I may ever observe the precepts of thy Son in humility, that I may receive His goodness.`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 5, item 3`},label:`glory`},{text:`“Thy divine Church, stripped of its bridal raiment, O my Son, hath been arrayed in the holy blood which flowed from Thy side. And I, beholding all Thy pain on the Cross, do likewise suffer!” said the Mother of the Word, lamenting.`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 5, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]},6:{irmos:{text:`The uttermost depths of sin have surrounded me, * and my spirit perisheth, * but do Thou, O Master, stretch forth Thy lofty arm * and like Peter O Helmsman, * do Thou save me.`,tier:2,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 6 irmos`}},items:[{text:`The Son of God, assuming flesh from thy pure blood, hath shown thee, O Bride of God, to be a great refuge; wherefore, be thou merciful to thy servants.`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 6, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O good one, with thy radiance illumine the eyes of my heart which have been darkened by unseemly thoughts; make me a child of the Light, and cause me to dwell in a place of light.`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 6, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Waves of passionate thoughts ever batter me, O most pure one, and the tempests of the evil spirits engulf me; yet set me firmly upon the rock of dispassion.`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 6, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`I have fallen asleep in the death of my soul, and lie in the grave of despondency; but grant me thy hand, I pray, and raise me up, guiding me to the life of repentance.`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 6, item 4`},label:`both_now`}]},7:{irmos:{text:`Of old the three children did not worship the golden image, * of the Persian idol, * but chanted in the midst of the furnace: * O God of our fathers, blessed art Thou!`,tier:2,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 7 irmos`}},items:[{text:`O pure one, with strength do thou gird my soul, which hath grown weak through sins, and save me who cry out to thy Son: O God of our fathers, blessed art Thou!`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 7, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`Fearing the hour of death because of eternal and everlasting torment, I fall down before thee: O Lady, Birthgiver of God, save me from the snares of those who pursue me!`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 7, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O Theotokos who didst contain the infinite God within thy womb, free my mind, which hath been confined by many transgressions, from their condemnation.`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 7, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`The race of mankind entreateth thee, O Theotokos: O Lady, have mercy on thy servants who with faith cry out to thy Son: O God of our fathers, blessed art Thou!`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 7, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:3}],label:`both_now`}]},8:{irmos:{text:`United together in the unbearable fire, * yet not harmed by the flame, * the children, champions of godliness, sang a divine hymn: * O all ye works of the Lord, * bless ye the Lord and supremely exalt Him throughout all ages.`,tier:2,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 8 irmos`}},items:[{text:`Having truly emulated the prodigal and ended my whole life in sins, I now cry out: I have sinned against thee! O Lady, make me as one of the hirelings of thy Son and Creator, that I may glorify thee throughout all ages!`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 8, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`My soul hath been filled with evils, and I have been reckoned with all who go down into the pit; yet do thou, O Virgin Theotokos, lead me up from the pit of the passions and from the miry clay of mine evils.`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 8, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Pray thou to Christ, O Theotokos who hast given birth to Him from thy holy womb, that He grant me forgiveness of my manifold transgressions, that I may chant: O all ye works of the Lord, hymn the Lord, and supremely exalt Him throughout the ages!`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 8, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`glory`},{text:`When my soul must needs depart from this life at the command of God, from the snares of those who pursue us, O most pure one, rescue those who cry out to thee: O all ye works of the Lord, hymn the Lord, and supremely exalt Him throughout the ages!`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 8, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`both_now`}]},9:{irmos:{text:`In the shadow and the letter of the Law, * let us, the faithful, discern a figure: * every male child that openeth the womb * shall be sanctified to God. * Therefore we magnify the firstborn Word * and Son of the beginningless Father, * the firstborn Child of a Mother who hath not known a man.`,tier:2,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 9 irmos`}},items:[{text:`The race of mankind, now enriched by thine invincible supplication, O most immaculate one, crieth out day and night: Cease thou never to entreat thy Creator and Son, that He take pity on those who hymn thee.`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 9, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`The darts of unseemly passions have wounded my soul with demonic assaults, and ever trouble my mind with the arrows of adverse thought; wherefore, heal mine incurable wounds, O maiden.`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 9, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O pure Bride of God, quickly remove from me the wounds inflicted upon me by the enemies who war against me, for, wretch that I am, I can no longer bear their assaults, their great wickedness and insolence; yet hasten thou to deliver me.`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 9, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`Thou knowest the weakness of my lowly body, the wounds of my soul, the groaning of my heart, and the error and deception of my mind; wherefore by thy tender compassion grant me healing of them all.`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline canon, Ode 9, item 4`},label:`both_now`}]}}},after_ode6:{rubric:`Lord, have mercy, (Thrice). Glory ..., Both now ..., Sessional Hymn, in Tone III:`,sessional:{text:`We who have acquired the Cross of thy Son as a staff of power, O Theotokos, thereby cast down the arrogance of the enemy, magnifying thee unceasingly with love.`,tier:1,src:{file:`3-4.pdf`,locus:`Tuesday-night Compline, sessional after Ode VI`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]}},closing_rubric:`Then, “It is truly meet ...,” and a prostration. Trisagion through Our Father ..., Troparion. The rest as usual. Dismissal.`},wed:{canon:{title:`Canon of supplication to the most holy Theotokos`,heading_rubric:`Canon of supplication to the most holy Theotokos`,odes:{1:{irmos:{text:`He who of old gathered the waters * into one by His divine decree, * divided the sea for the people of Israel. * For He is our God and supremely glorious, * to Him alone let us sing, for He hath been glorified.`,tier:2,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 1 irmos`}},items:[{text:`O Theotokos, grant me contrition and spiritual tears, that I may weep for my many transgressions and my failure to correct my conscience. O maiden, I entreat thy loving-kindness.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 1, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`Stumbling over my thoughts, I fall headlong into the abyss of destruction. O Virgin, I now entreat thy help: set thou unshakably the weakness of my mind upon the firm rock of the commandments of God.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 1, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`I bear the barrenness of the fig tree, and fear felling and disputation, lest my Creator and God send me into the fire. O Lady, anticipating my needs, render me fruitful in works of repentance, that I may glorify thee.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 1, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`Both now. ..., I beseech thee, O most pure one who art full of grace, in that thou art the immaculate temple of the King, with chastity and a pure life cleanse thou my heart, which hath been defiled by unseemly passions, and enrich it with grace.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 1, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`}]},3:{irmos:{text:`O Most High, Ruler of all, * who out of nothing hath established all things, * fashioned by Thy Word, * perfected by the Spirit, * confirm me in Thy love.`,tier:2,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 3 irmos`}},items:[{text:`Many are they who war against me and afflict me, and I can find no ease of deliverance from those who beset me; yet disdain not my prayer, O pure one.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 3, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Weighed down by a multitude of evils and my manifold transgressions, I am unable to lift up mine eyes to the heights of heaven; yet do thou grant me remission, O most pure one.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 3, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`All my days the evil serpent strives to destroy my lowly soul; yet do thou break his soul-destroying fangs, O Theotokos.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 3, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`O Theotokos, deliver me from all the misfortunes which beset me, thy servant, and from tempests of sin, and by thy supplications direct me to the haven of salvation.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 3, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]},4:{irmos:{text:`Thou hast shown us steadfast love, O Lord, * for Thou gavest Thine only-begotten Son over to death for our sake. * Wherefore with thanksgiving we cry unto Thee, * ‘Glory to Thy power, O Lord!’`,tier:2,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 4 irmos`}},items:[{text:`I tremble, considering the depths of my sins and the grievous and great billows of mine adverse thoughts; yet do thou direct and pilot me to the calm haven, O most pure one.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 4, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Grievous ignorance, incomprehension and the heedlessness of mine evils have now come upon my soul; yet do thou, O most pure one, lead me to repentance for those things which I have done.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 4, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`With streams of tears extinguish the fire of the passions and with the fire of the Spirit bum up the thorns and billows of life which choke my mind, O Birthgiver of God, for thou art my protection and boast.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 4, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`I am wholly engulfed by the tumult and threefold billows of perils and evil thoughts, and ever dragged down into the abyss of despair, I cry to thee: O Lady, save me, thy servant!`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 4, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]},5:{irmos:{text:`In a vision Isaiah saw upon a throne, * God lifted up on high * borne aloft by angels of glory; * and he cried: ‘Woe is me! * For I have foreseen God made flesh, * the Lord of the never-setting light * and the King of peace.’`,tier:2,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 5 irmos`}},items:[{text:`Thou knowest the pain of my soul, the weakness of my flesh and the corruption and inconstancy of my mind, O Lady. Wherefore, grant me thy mercy and grace, that, saved by thy protection, I may glorify thee.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 5, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Deny me not thy loving-kindness and compassion, O all-immaculate Lady; but grant thy mercies, and the release and forgiveness of mine evil deeds to me who approach thee in compunction, that I may hymn thy mighty acts with thanksgiving.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 5, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Those who hate me in vain and oppress me have now increased in number more than the hairs of my head, O pure Virgin, seeking to destroy me and make of me food for them to devour; wherefore, turn them back, filling them with shame.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 5, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`O pure Virgin who hast given peace to the world and salvation unto all, having given birth to divine Peace, with the peace and love of Christ the Savior quell thou the battle of the passions against my soul and body.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 5, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]},6:{irmos:{text:`The uttermost depths of sin have surrounded me, * and my spirit perisheth, * but do Thou, O Master, stretch forth Thy lofty arm * and like Peter O Helmsman, * do Thou save me.`,tier:2,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 6 irmos`}},items:[{text:`There is no one on earth who lives as wickedly as I do in deed, word and action. Wherefore, O Lady, I beg thee to grant me the mercies of thy love for mankind.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 6, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Actions of evil transgression beget grief for all; wherefore, we are now beset by bitter perils. Help us, O thou who alone art the salvation of Christians!`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 6, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Thou hast given birth, yet hast remained pure after birthgiving, O Virgin Theotokos; wherefore, do thou ever entreat thine Offspring, that we, thy servants, may be delivered from all the harm of the enemy.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 6, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`Through the supplications of Thy most pure Mother, of all the prophets, martyrs and sacred disciples, O Word of God, grant us peace and the cleansing of transgressions.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 6, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]},7:{irmos:{text:`As of old Thou didst bedew * the three pious children in the Chaldean flames, * so also with the radiant fire of Thy divinity * illumine us who cry to Thee, * ‘Blessed art Thou, the God of our fathers!’`,tier:2,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 7 irmos`}},items:[{text:`Defiled in body and soul, and sullied by mine unclean acts, I beseech thee, the pure and immaculate Mother of God, O Lady, trusting in thy mercy: Have pity on me, O most pure one!`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 7, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`The multitude of my transgressions and temptation of evils fill me greatly with perplexity and drag me down into the abyss of despondency; but do thou, O most pure Lady, save me who am perishing and cruelly drowning.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 7, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`In the magnitude of the compassions of thy goodness, O good One, overlook the multitude of our sins, and be thou well disposed toward those who cry out unceasingly: Blessed art Thou, O Lord God of our fathers!`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 7, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`glory`},{text:`Both now.... O pure and blessed one, from the mire of the passions and the depths of sorrows and the perils of life do thou draw toward dispassion and gladsome joy us who cry: Thou alone art full of the grace of God!`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 7, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`}]},8:{irmos:{text:`The flame of material fire withered * through the immaterial flame brought about by the god-seeing children, * wherefore they chanted: * Bless the Lord, all ye works of the Lord!`,tier:2,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 8 irmos`}},items:[{text:`The bitterness of pleasures, overcoming all the senses of my body, doth foully sully my soul, drawing me toward death. O Sovereign Lady of the world, be thou my salvation!`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 8, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`To thee have I entrusted soul, heart and body, for I have no other help than thee, O Lady, through whom I obtain mercy; wherefore, grant me thy rich mercy and grace.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 8, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Poisoning me with his venom, the serpent hath grievously slain my wretched soul with bodily death; yet bring it to life again, using thy supplications as remedies to counter the adversary.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 8, item 3`},label:`glory`},{text:`O thou who hast given birth to God the Savior, the Prince of peace, beseech Him, that He quickly bestow peace upon the world, that we may glorify Him in peace.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 8, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]},9:{irmos:{text:`We magnify thee, the unburnt bush, * the holy Virgin, * and the Mother of the Light, * the Theotokos, the hope of us all.`,tier:2,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 9 irmos`}},items:[{text:`Wash away the defilement of passionate thought from my mind, O pure one, clothing me in the splendid robe of dispassion.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 9, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Open unto me the divine portals of repentance, O Virgin, terminating and hindering my passions and pleasures.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 9, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Hearken unto the voice of my groaning, the voice of my lamentation, and grant cleansing and salvation to my wretched soul, O all-immaculate Virgin.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 9, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`Verily and in truth Daniel the prophet beheld thine Offspring, O Virgin, and he called Him Who sitteth on the throne the Ancient of days.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline canon, Ode 9, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]}}},after_ode6:{rubric:`Lord, have mercy, (Thrice). Glory ..., Both now ..., Sessional Hymn, in Tone III:`,sessional:{text:`I have passed my whole life in great slothfulness, O most pure one, and have now drawn nigh unto my departure from this time; and I am afraid of mine enemies, lest they destroy my soul, O all-immaculate one, and cast me into the abyss of destruction. Yet take pity on thy servant, O Virgin, and deliver me from their affliction.`,tier:1,src:{file:`3-5.pdf`,locus:`Wednesday-night Compline, sessional after Ode VI`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:3}]}},closing_rubric:`Then, “It is truly meet ...,” and a prostration. Trisagion through Our Father ..., Troparia, and the rest as usual. Dismissal.`},thu:{canon:{title:`Canon of supplication to the most holy Theotokos`,heading_rubric:`Canon of supplication to the most holy Theotokos`,odes:{1:{irmos:{text:`He who of old gathered the waters * into one by His divine decree, * divided the sea for the people of Israel. * For He is our God and supremely glorious, * to Him alone let us sing, for He hath been glorified.`,tier:2,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 1 irmos`}},items:[{text:`I entreat thee, O most pure one, thou mountain overshadowed which the prophet Habbakuk beheld in the Spirit, that thou cover me who am burned by the heat of the passions, and that I be delivered from the deadly shadow of grievous misfortunes.`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 1, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`With the sprinkling of the divine blood which flowed from the divine side of thy Son, O pure one, wash the wounds of my heart, that I may magnify and glorify thee, the ever-blessed and most immaculate one, as is meet.`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 1, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Thou hast given birth to the Word Who is equally active with the Father and hath deified our nature. Him do thou beseech, O pure one, that He grant divine ease unto me who am confused and weakened by the wiles of the enemy.`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 1, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`Grant me cleansing of transgressions by thy divine supplications, O Virgin, for thou art possessed of powerful supplications. O Lady, from transgressions, sufferings, sorrows and evil circumstances deliver those who hymn thee.`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 1, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`both_now`}]},3:{irmos:{text:`O Most High, Ruler of all, * who out of nothing hath established all things, * fashioned by Thy Word, * perfected by the Spirit, * confirm me in Thy love.`,tier:2,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 3 irmos`}},items:[{text:`As thou art merciful, O most pure one, entreat Him Who is ineffable in mercy and rich in compassions, that He take pity upon us, the oppressed.`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 3, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`As thou art the temple of the Creator of all, entreat the Comforter, that He make His abode within me for I have become the den of soul-destroying robbers, O pure Virgin.`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 3, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`At the command of Him Who as God upholdest all, Whom thou didst bear in thine arms, O Theotokos, look upon me and deliver me from looking upon the passions as I ought not to do.`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 3, item 3`},label:`glory`},{text:`O most pure Theotokos, open unto me the tender compassion of thy mercy, and show thyself to be my fervent helper and salvation amid perils.`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 3, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]},4:{irmos:{text:`Thou hast shown us steadfast love, O Lord, * for Thou gavest Thine only-begotten Son over to death for our sake. * Wherefore with thanksgiving we cry unto Thee, * ‘Glory to Thy power, O Lord!’`,tier:2,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 4 irmos`}},items:[{text:`O only abundantly merciful Christ, Who as God willingly endured wounds and execution, by the supplications of her who gave birth to Thee heal my soul, which hath been wounded by the robbers’ afflictions of the demons.`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 4, item 1`},label:`plain`},{text:`I am the work and creation of Thy hands, O Creator, but the malice of the serpent hath broken me through the pleasures of life. Wherefore, O Christ the Word, renew me by the supplications of her who gave birth to Thee.`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 4, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`In a manner transcending description thou hast given birth to the Word Who looseth men from all irrationality. Him do thou earnestly entreat, that He free me who am enslaved by irrational pleasures, O only Ever-virgin.`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 4, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`O all-sacred tabernacle wholly filled with light, thou dost ever cause healing to gush forth upon us from thy hand, pouring forth fragrant myrrh upon all, O all-pure Bride of God.`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 4, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]},5:{irmos:{text:`In a vision Isaiah saw upon a throne, * God lifted up on high * borne aloft by angels of glory; * and he cried: ‘Woe is me! * For I have foreseen God made flesh, * the Lord of the never-setting light * and the King of peace.’`,tier:2,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 5 irmos`}},items:[{text:`Transform the pangs of my flesh and the grief of my soul, and drive away the clouds of despondency, O Virgin, thou cloud of the Light; and grant health and release from pain to me who hymn and glorify thee with love.`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 5, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Full of every sin, I now set thee as mediatress and advocate before Him Who was born from thee. O Virgin, be thou the correction of my life and my guide to the path of divine understanding.`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 5, item 2`},label:`plain`},{text:`Sanctify my mind, enlighten my soul, and make me a partaker of divine glory, O Virgin. For, lo! I have been filled with evils and am enslaved to all manner of pleasures; yet I offer unto thee my defiled conscience.`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 5, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`O holy Virgin maiden, thou divine vine who produced the beautiful Grapes which pour forth abundant drink upon our souls: give me to drink of His sweetness, take the drunkenness of the passions away from me, and save me.`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 5, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]},6:{irmos:{text:`O Lover of mankind, disdain not those * who have reached the end of the ages * and are assailed with destruction by the threefold billows of perils, * yet cry aloud: O Savior, save us, * as Thou didst save the prophet from the sea monster!`,tier:2,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 6 irmos`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}]},items:[{text:`Ever arrogant, I have surpassed the haughty Pharisee in mind and have joined myself to the defilements of boundless transgressions. O thou who alone art pure, deliver and take pity on me who am grievously humbled.`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 6, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O thou whose conceiving and birthgiving were most wondrous, show forth now the wonder of thy mercies upon me, wretch though I am; for I have been conceived and born in iniquities, and have become enslaved by pleasures.`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 6, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`I lament, weep and groan when I remember the dread judgment; for I have amassed only evil deeds. Yet stand up for me at that awesome hour, O Virgin Mother of God who knewest not a man.`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 6, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`No mind can understand or describe the strange and most glorious miracle wrought within thee, O pure Virgin. How didst thou give birth, yet remain pure? God it is Who was born from thee in essence.`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 6, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]},7:{irmos:{text:`The three children in the furnace, prefiguring the Trinity: * trampled underfoot the threat of the fire * and cried aloud, chanting: * Blessed art Thou, O God of our fathers!`,tier:2,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 7 irmos`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]},items:[{text:`There are no works fit for salvation within me, O Lady, for I add sins unto sins and heap evil upon evil. O pure one, by thy prayers stand before me and save me.`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 7, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`The judgment is at the gates, the tribunal hath been made ready, O my lowly soul. But cry out: When Thou shalt judge me, O Word, condemn me not, through the supplications of her who gave birth to Thee!`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 7, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`Laying hold of the fruits of sin, I have been slain; yet do I offer thee my barren soul, and cry to thee, O most pure one: Show me to be fruitful, O thou who by thy Fruit hast destroyed corruption!`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 7, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`glory`},{text:`O strange mystery! O awesome concept! How hath God appeared on earth as a man? As He knoweth, as He desireth, as is His good pleasure: for He acteth as He wisheth.`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 7, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`both_now`}]},8:{irmos:{text:`United together in the unbearable fire, * yet not harmed by the flame, * the children, champions of godliness, sang a divine hymn: * O all ye works of the Lord, * bless ye the Lord and supremely exalt Him throughout all ages.`,tier:2,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 8 irmos`}},items:[{text:`As thou art wholly good, having become the favorite of the King of all, O Theotokos, fill me with good works, who have lived in evil and have reached the end of my life in slothfulness, that I may glorify thee throughout all ages.`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 8, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`As of old thou didst most gloriously deliver the prophet from the belly of the sea monster, O Word of God, so deliver my soul, O Word, which hath been plunged into the abyss of destruction, for I have thee to pray for me, the Virgin who gave birth without knowing wedlock.`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 8, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`The workers of evil, finding me clad in beautiful raiment, have stripped me naked; yet do thou thyself, O Virgin Birthgiver of God, array me in a divine vesture through repentance, by thy prayers, O Theotokos.`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 8, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`glory`},{text:`O pure one, thou didst hold in thine arms Him before Whom every creature doth tremble, Who for our sake became a babe in His loving- kindness. Him do thou beseech, that He save all who cry out with faith: Thee do we supremely exalt, O most pure one, throughout all ages!`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 8, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`both_now`}]},9:{irmos:{text:`In the shadow and the letter of the Law, * let us, the faithful, discern a figure: * every male child that openeth the womb * shall be sanctified to God. * Therefore we magnify the firstborn Word * and Son of the beginningless Father, * the firstborn Child of a Mother who hath not known a man.`,tier:2,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 9 irmos`}},items:[{text:`O incorrupt and immaculate Virgin, disdain me not who have become corrupt in mind and soul, have defiled my conscience with evil and am shown to be devoid of all good deeds; but adorn me with the works of piety.`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 9, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`I have been filled with evils and am satiated with thoughts which alienate me from Thee the Lover of mankind. Wherefore, I groan and cry: Accept me who repent, and reject me not, through the supplications of her who gave birth to Thee, O greatly merciful Benefactor!`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 9, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`By thy prayers, O all-immaculate maiden, may I be delivered from all wrath, deadly sufferings, the cruel fire of Gehenna, unjust men and evil enemies, for I flee to thy protection and cry out to thee for aid.`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 9, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`The supremely beauteous One, having found thee to be beautiful of soul, beautiful of mind, and comely of body, became incarnate from thy virginal womb in a way which He alone knew, thereby adorning our ugliness. O Virgin, entreat Him, that we be saved.`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-night Compline canon, Ode 9, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]}}},after_ode6:{rubric:`Lord, have mercy, (Thrice). Glory ..., Both now ..., Sessional Hymn, in Tone III:`,sessional:{text:`Beholding Thee hanging dead upon the Tree, O Christ, Thy pure Mother who knew not wedlock said, lamenting maternally: “How hath the iniquitous and ungrateful assembly of the Jews rewarded Thee, having enjoyed Thy many and great gifts, O my Son? I hymn Thy divine condescension!”`,tier:1,src:{file:`3-6.pdf`,locus:`Thursday-night Compline, sessional after Ode VI`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}]}},closing_rubric:`Then, “It is truly meet ...,” and a prostration. Trisagion through Our Father..., and Troparia. The rest as usual. Dismissal.`},fri:{canon:{title:`Canon of supplication to the most holy Theotokos`,heading_rubric:`Canon of supplication to the most holy Theotokos`,odes:{1:{irmos:{text:`He who of old gathered the waters * into one by His divine decree, * divided the sea for the people of Israel. * For He is our God and supremely glorious, * to Him alone let us sing, for He hath been glorified.`,tier:2,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 1 irmos`}},items:[{text:`Having given birth to the Author of salvation and Bestower of life, in a manner transcending understanding, O pure Birthgiver of God, thou hast thereby loosed the bonds of the condemnation of Eve our first mother; wherefore, all creation doth call thee blessed.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 1, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`From the depths of despair do thou rescue me who am afflicted by cruel pangs in soul and body, O most holy Virgin, delivering me from all want; for thou art the wellspring of loving-kindness, O most pure one.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 1, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`I have cast off the vesture of gladness, falling into sorrow and pain, and have been cruelly wounded in every place. But go thou before me and deliver me from the falsehood which assails me, for thou art my refuge and hope, O Lady.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 1, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`Having acquired thee as a steadfast intercessor, O Bride of God, I flee to thy protection, praying: Spurn not thy servant, who am weighed down by many passions, pangs and sorrows, but heal me by thy prayers, O Mother of God.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 1, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`both_now`}]},3:{irmos:{text:`O Most High, Ruler of all, * who out of nothing hath established all things, * fashioned by Thy Word, * perfected by the Spirit, * confirm me in Thy love.`,tier:2,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 3 irmos`}},items:[{text:`Wretch that I am, I find myself in painful perplexity and sorrow, beholding death following close upon me; wherefore, O most pure one, save me by thy supplications.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 3, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`All my life, which hath become corrupt through evil and prodigal works, doth accuse me and plungeth me into despair. O pure one, save me!`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 3, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`The abyss of thy compassions, O Lady, poured forth everywhere solely because of thy goodness, doth anoint with rich oil all who ever hymn thee.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 3, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`Thy Son and Lord, receiving thee as from the origin of our nature, O Bride of God, joineth those who hymn thee by thy prayers.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 3, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]},4:{irmos:{text:`Thou hast shown us steadfast love, O Lord, * for Thou gavest Thine only-begotten Son over to death for our sake. * Wherefore with thanksgiving we cry unto Thee, * ‘Glory to Thy power, O Lord!’`,tier:2,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 4 irmos`}},items:[{text:`All my hope have I placed in thee, O Lady. I pray and fall down before thee with all my soul: Deliver me from deadly sickness, and lead me up to the life of salvation, O thou who hast given birth to our Life.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 4, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`By thy supplications, O pure one, heal me, thy servant who have become desperate because of grievous and corrupt wounds; for thou hast given birth to the Physician, our God Who is rich in mercy.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 4, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`By thy divine enlightenment deliver me who have fallen into cruel passions and grant me a vesture of gladness, O Virgin who hast caused the Joy which passeth all understanding to blossom forth.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 4, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`Thou hast been revealed to be another heaven, O pure Theotokos, who hast ineffably shone forth the Sun of righteousness on earth, by Whom the everlasting light of divine knowledge hath shone forth.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 4, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]},5:{irmos:{text:`I rise at dawn unto Thee, * the Creator of all, * surpassing all worldly understanding; * for Thy commandments are light, * wherein do Thou guide me.`,tier:2,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 5 irmos`}},items:[{text:`Because of my boundless sins I have drawn nigh unto the passions, bringing about death. O Mother of God, I earnestly beseech thee to become my deliverance from many evils.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 5, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`I stretch forth the hands of my soul unto thee, O pure one, for, wretch that I am, I have been enfeebled by carnal deeds. Yet do thou deliver me from many wounds, imparting healing unto me.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 5, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`I have cast off the garments of health and in pain have clothed myself in a robe of tears. To thee I pray, O Lady: Clothe me again in health!`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 5, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`In that thou art the sacred majesty of the martyrs and apostles and the help of the faithful, O Theotokos, we all glorify thee as is meet.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 5, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]},6:{irmos:{text:`Lead me up from corruption, O Lord my God! * cried Jonah unto Thee; * and I also cry aloud to Thee: * Deliver me from the abyss of my many evils, O Savior, * and guide me I pray, to Thy light!`,tier:2,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 6 irmos`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}]},items:[{text:`A multitude of pangs hath assailed me because of my boundless offenses, corrupt as I am, and clothed me in mortality; yet do thou, O Theotokos, deliver me from them and rescue me from all want.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 6, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`I have been cast into the abyss of transgressions, pangs and boundless sorrows, and I can in nowise deliver myself from them; yet, stretching forth thy hand, O Birthgiver of God, lead me up to salvation.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 6, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`We know thee to be a steadfast foundation and a mighty help for those in sorrow, O Theotokos; wherefore, having fled to thy protection, I beseech thee: Deliver me from grievous misfortunes and from cruel pangs.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 6, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`Let us hymn the divine ark, the Virgin Mother of God, the furrow which hath put forth the divine Grain whereby the hearts of the faithful are fed with faith and spiritual famine is brought to an end.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 6, item 4`},label:`both_now`}]},7:{irmos:{text:`As of old Thou didst bedew * the three pious children in the Chaldean flames, * so also with the radiant fire of Thy divinity * illumine us who cry to Thee, * ‘Blessed art Thou, O God of our fathers!’`,tier:2,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 7 irmos`}},items:[{text:`Take pity on me, O Virgin Bride of God, for I have stumbled headlong into the depths of despair. I entreat thee to be tranquility for me, O most pure one, for thou art ever a haven of salvation for those in need.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 7, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`Ineffably, in a manner transcending understanding, thou hast given birth to Christ, the Wisdom and Power of God; wherefore, as thou art mighty in mercy and compassionate, grant me thy saving healing, O Theotokos, thou hope of the faithful.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 7, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Having enriched the ends of the earth and granting the sweetness of incorruption by thy divine birthgiving, free me from corrupting sickness and the bitter passions, O most glorious Mother of God.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 7, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`Setting thee forth as the mystical door to Himself and the wondrous helper of those on earth, O pure one, through thee, He hath given to mankind a portal leading all to eternal life, in that He is compassionate and the God of all.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 7, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]},8:{irmos:{text:`The Babylonian furnace burnt not the children, * neither did the fire of the Godhead consume the Virgin, * wherefore with the faithful children we cry aloud: * 'Bless ye the Lord, all ye works of the Lord'.`,tier:2,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 8 irmos`}},items:[{text:`Having accumulated an unfathomable abyss of transgressions, I am now drowning, engulfed in sickness, O pure one. Wherefore, stretching forth to me a helping hand, I pray thee; lead me up from the abyss of pain.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 8, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1},{from:`U+043E о (Cyrillic)`,to:`o`,count:1}],label:`plain`},{text:`O pure Ever-virgin, all-hymned Theotokos, thou hast been revealed to be the earthly throne of God and the portal of heaven; wherefore, open unto me the door of salvation, O Mother of God, and free me from the darkness: of the passions.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 8, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Like a vine thou didst produce the uncultivated Grape, exuding the wine which maketh glad the souls of those who hymn Him with faith, O pure and all-immaculate one.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 8, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`Remaining incorrupt after giving birth, O all-immaculate and pure one we pray: Deliver from corruption thy servants, who faithfully chant with oneness of soul: Bless the Lord, all ye works, and supremely exalt Him, throughout the ages!`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 8, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]},9:{irmos:{text:`Upon Mount Sinai Moses saw thee in the bush, * as one who didst conceive the fire of the Godhead within thy womb, * and yet remained unconsumed. * Daniel saw thee as a mountain not cut by the hand of man, * and Isaiah proclaimed thee as the Rod that blossomed forth * from the root of David.`,tier:2,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 9 irmos`}},items:[{text:`O good Virgin, thou joy and refuge of the world! protection of the faithful and deliverance from sorrows! Do thou stand before me at the hour of my death, and deliver me from the demons who seek to destroy me.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 9, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`In that thou didst conceive the Creator and God within thy womb, O pure Virgin Mother, by the power which is in thee cast down the arrogance of the demons and lift up the horn of those who hymn thy divine might and venerate thine image with faith.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 9, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`He Who became incarnate from thee, O pure Virgin, restoring our nature, hath made new and renewed through thy maternal supplications, those who in hymns unceasingly magnify thee, our radiant and vigilant ally, the Theotokos.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 9, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`Thou art the joy of the angels, the beauty of the righteous; thou art the hope of the faithful and our preservation. Thou art the bridge, which conveyeth to the life which groweth not old, those who magnify thee with faith and love.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-night Compline canon, Ode 9, item 4`},label:`both_now`}]}}},after_ode6:{rubric:`Lord, have mercy, (Thrice). Glory ..., Both now ..., Sessional Hymn, in Tone III:`,sessional:{text:`Without separating Himself from the divine Essence, and becoming incarnate within thy womb, God became a man yet remained God, the one Lord, preserving thee, the Virgin Mother, as immaculate after giving birth as thou wast before birthgiving. Him do thou earnestly entreat, that He grant us great mercy.`,tier:1,src:{file:`3-7.pdf`,locus:`Friday-night Compline, sessional after Ode VI`}}},closing_rubric:`Then, “It is truly meet ...,” and a prostration. Trisagion through Our Father ..., Troparia, and the rest as usual. Dismissal.`},sat:{frame_rubric:`The priest saith: Blessed is our God..., and we respond: Amen. Glory to Thee, our God, glory to Thee. O heavenly King..., Trisagion through Our Father. Lord, have mercy (12 times). Glory ..., Both now ..., O come, let us worship ..., (Thrice). Psalm 50 (Have mercy on me, O God...); Psalm 69 (O God, be attentive unto helping me...); and Psalm 142 (O Lord, hear my prayer...). Then, Glory to God in the highest..., and the Symbol of Faith (I believe in one God...).`,canon:{title:`Canon of supplication to the most holy Theotokos, in Tone III`,heading_rubric:`Canon of supplication to the most holy Theotokos, in Tone III`,odes:{1:{irmos:{text:`He who of old gathered the waters * into one by His divine decree, * divided the sea for the people of Israel. * For He is our God and supremely glorious, * to Him alone let us sing, for He hath been glorified.`,tier:2,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 1 irmos`}},items:[{text:`With pure hymns, O most pure Bride of God, we, the faithful, crown thee as her who, through the divine Spirit and at the good pleasure of the Father, wast revealed to be the Mother of God; and with the archangel we greet thee with hymns, unto our salvation.`,tier:1,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 1, item 1`},label:`plain`},{text:`Of old, Eve was formed from the side of Adam by God’s creative action, and Christ, Who is our God, appeared out of the womb of the Theotokos and became immutably man: the Pre-eternal came under time.`,tier:1,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 1, item 2`},label:`plain`},{text:`He Who is our God condemned the womb of Eve to give birth amid grief and pain, yet He made His abode within thy womb, appeared in the flesh in a manner past all telling, and loosed the debt of our first mother.`,tier:1,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 1, item 3`},label:`glory`},{text:`Having fallen, heavy laden, into the abyss of despair, O Birthgiver of God, we earnestly cry out to thee: O Lady, help us who are drowning because of our deeds of wicked transgression! For thee alone do we have as our hope after God.`,tier:1,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 1, item 4`},label:`both_now`}]},3:{irmos:{text:`O Most High, Ruler of all, * who out of nothing hath established all things, * fashioned by Thy Word, * perfected by the Spirit, * confirm me in Thy love.`,tier:2,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 3 irmos`}},items:[{text:`The staff of Aaron, which blossomed forth without being watered, showed thee forth, O most pure Theotokos, who without seed hast given birth to God Who became incarnate without undergoing change.`,tier:1,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 3, item 1`},label:`plain`},{text:`In the Spirit, O most pure one, the prophet foresaw thee as a lampstand bearing the divine Fire, conveying sweet fragrance and life everlasting to those in the world.`,tier:1,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 3, item 2`},label:`plain`},{text:`Let us approach the archangel Gabriel, in hymns declaring to the Theotokos: Rejoice! for through thee the curse of our first parents’ condemnation hath been loosed!`,tier:1,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 3, item 3`},label:`glory`},{text:`Having thee as a bulwark of salvation, O most holy Theotokos, we sinners are saved. O Lady, disdain not, neither spurn thou our supplications!`,tier:1,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 3, item 4`},label:`both_now`}]},4:{irmos:{text:`Thou hast shown us steadfast love, O Lord, * for Thou gavest Thine only-begotten Son over to death for our sake. * Wherefore with thanksgiving we cry unto Thee, * ‘Glory to Thy power, O Lord!’`,tier:2,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 4 irmos`}},items:[{text:`Of old, Habbakuk, perceiving thee with divine vision, O most pure one, proclaimed thee to be the noetic mountain, the tabernacle of the virtues, for the Word Who came forth from the south received flesh from thee.`,tier:1,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 4, item 1`},label:`plain`},{text:`In the Spirit Daniel beheld thee as a great and unquarried mountain, revealing the purity of thy virginity as remaining inviolate, O Lady, from whom Christ the Word, the Rock, was cut, casting down the falsehood of idolatry.`,tier:1,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 4, item 2`},label:`plain`},{text:`David foretold thee to be a wondrous and rich mountain; for the only-begotten Son of the Father was well-pleased to make His abode within thee, in the flesh. Wherefore, in the Spirit we cry out to thee: Rejoice!`,tier:1,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 4, item 3`},label:`glory`},{text:`As thou art the wholly good and fervent intercessor for the sinful and lowly, O most pure Lady and Birthgiver of God, save Thy servants from misfortunes, sorrows and sins.`,tier:1,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 4, item 4`},label:`both_now`}]},5:{irmos:{text:`In a vision Isaiah saw upon a throne, * God lifted up on high * borne aloft by angels of glory; * and he cried: ‘Woe is me! * For I have foreseen God made flesh, * the Lord of the never-setting light * and the King of peace.’`,tier:2,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 5 irmos`}},items:[{text:`The Virgin Mary, the rod of Jesse, without seed, through the divine Spirit of the Father, put forth the never-fading Blossom of the beginningless God, Who hath dominion over the mighty kingdoms of the nations, and upon Whom the gentiles set their hope.`,tier:1,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 5, item 1`},label:`plain`},{text:`Taking flesh from thee, O Theotokos, the Prince of peace hath come to reign upon the throne of David. O the wonder! He hath shown thee to be the Queen who gave birth to Him Who set warfare at naught, striking down the princes of Moab.`,tier:1,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 5, item 2`},label:`plain`},{text:`Revealing thine immaculate goodness, through which Christ was clad in the flesh without seed, O Virgin, Isaiah cried out, exclaiming: The Lord of glory cometh upon a light cloud, and dispelling the darkness of delusion, He hath bestowed light upon us!`,tier:1,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 5, item 3`},label:`glory`},{text:`Having conceived by the Holy Spirit the Word Who is consubstantial with the Father, O Virgin, thou hast given birth to Him in two natures, perfect God and perfect man. His manifestation in the flesh do we honor with faith.`,tier:1,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 5, item 4`},label:`both_now`}]},6:{irmos:{text:`The uttermost depths of sin have surrounded me, * and my spirit perisheth, * but do Thou, O Master, stretch forth Thy lofty arm * and like Peter O Helmsman, * do Thou save me.`,tier:2,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 6 irmos`}},items:[{text:`In hymns the most wise one described thee beforehand, O all-hymned one, as the couch whereon God, Who was hypostatically incarnate from thee, did rest; and He Who was born from thee without commingling hath glorified thee.`,tier:1,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 6, item 1`},label:`plain`},{text:`O all-hymned Virgin, as one chosen thou didst become the chosen vesture of the Word, for, taking flesh from thee as it were a robe of divine purple, He hath reigned, arrayed in majesty.`,tier:1,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 6, item 2`},label:`plain`},{text:`O Bride of God, thou didst become the receptacle of the divine Union, more lustrous than gold; for through thee God became a man and conversed with mankind as a man.`,tier:1,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 6, item 3`},label:`glory`},{text:`The evil of heresy hath brought death upon those who refuse to honor thee, O all-hymned Virgin; for in their malice they hide at the sight of the most glorious likeness of thine image.`,tier:1,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 6, item 4`},label:`both_now`}]},7:{irmos:{text:`Of old the three children did not worship the golden image, * of the Persian idol, * but chanted in the midst of the furnace: * O God of our fathers, blessed art Thou!`,tier:2,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 7 irmos`}},items:[{text:`Having been united conformably and been revealed to be incorrupt, the bush and the flame manifestly show thee forth, O Virgin; for thou hast given birth to God, yet remained a virgin.`,tier:1,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 7, item 1`},label:`plain`},{text:`The fleece and the dew, shown forth in change, prefigured thy birthgiving for Gideon; for thou alone hast borne the divine Word in thy womb, as though He were rain, O Virgin Mother.`,tier:1,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 7, item 2`},label:`plain`},{text:`The fire of my sin created a flame surpassing that of Gehenna for me, O pure one. By thy mercy do thou quench it, guiding me to the light by repentance.`,tier:1,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 7, item 3`},label:`glory`},{text:`Venerating the appearance of thy countenance as the primal image, O most pure Theotokos, we all have thee as a helper and a right effective protection before God forever.`,tier:1,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 7, item 4`},label:`both_now`}]},8:{irmos:{text:`The Babylonian furnace burnt not the children, * neither did the fire of the Godhead consume the Virgin, * wherefore with the faithful children we cry aloud: * 'Bless ye the Lord, all ye works of the Lord'.`,tier:2,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 8 irmos`}},items:[{text:`Finding thee as an all-radiant lily amid thorns, shining with the splendor of beauty through the divine Spirit, the Father desired thee, the Bride who knew not wedlock, as a habitation for His Son.`,tier:1,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 8, item 1`},label:`plain`},{text:`Without hesitation I manifestly glorify thee, the most immaculate Virgin, as more holy than the host on high; for thou didst bear in thy womb their Creator, Who in an uncommingled union received flesh from thee.`,tier:1,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 8, item 2`},label:`plain`},{text:`Having preserved thy virginity intact, O Virgin, thou wast truly shown to be the Mother of the Son of God, becoming a Bride through the Father’s good pleasure and the incorrupt receptacle of the Spirit of glory.`,tier:1,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 8, item 3`},label:`glory`},{text:`God Who is immaterial and invisible by nature was ineffably and supra-naturally born as a man from the holy Virgin, becoming visible, two natures in a single Hypostasis, wherein He is seen and depicted.`,tier:1,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 8, item 4`},label:`both_now`}]},9:{irmos:{text:`New is the wonder and befitting of God: * for the Lord clearly passes through the closed gate of the Virgin: * naked at His going in and God bearing flesh at His coming out, * while the gate remaineth closed. * As ineffably the Theotokos and Mother of our God we magnify her.`,tier:2,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 9 irmos`}},items:[{text:`A holy fruit sprang forth from the holy root of the barren and sanctified one: the maiden Theotokos who, by the law of God the Father, hath blossomed forth never-withering and perfecting Life. And Anna rejoicing, receives in her old age a babe, the Mother of God, whom we glorify.`,tier:1,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 9, item 1`},label:`plain`},{text:`New and godly is the birthgiving of thy holy and God-bearing womb, O pure one; for therein the incarnate holy Son was depicted in human image by the finger of the Father and by the Holy Spirit. Him do we magnify as both God and man without commingling.`,tier:1,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 9, item 2`},label:`plain`},{text:`All judgment crieth out against me, for the deeds of my sinful actions lift up their voice to forbid me, and my whole soul knoweth those things whereby it will be condemned, and it trembleth before the flame of Gehenna. O Lady, before the end, from which do thou deliver me by thy prayers.`,tier:1,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 9, item 3`},label:`glory`},{text:`After giving birth thou wast shown to be incorrupt, O pure one, for in a manner transcending nature, O Theotokos, thou hast given birth immutably to the Creator of all as a man in the flesh, though He was not separated from the essence of the Father; and through the divine Spirit thou didst remain a virgin. Wherefore, glorifying thee, we lift our voices in hymnody.`,tier:1,src:{file:`3-1.pdf`,locus:`Saturday-night Compline canon, Ode 9, item 4`},label:`both_now`}]}}},after_ode6:{rubric:`Lord, have mercy, (Thrice). Glory ..., Both now ..., Sessional Hymn, in Tone III:`,sessional:{text:`In the fervor of faith I cry out to thee with unworthy lips and a defiled heart, O Theotokos: Save me who am drowning in sins! Take pity on one who is slain by despair, that, saved, I may cry aloud to thee: Rejoice, O Virgin, thou help of Christians!`,tier:1,src:{file:`3-1.pdf`,locus:`Saturday-night Compline, sessional after Ode VI`}}},closing_rubric:`Then, “It is truly meet ...,” and the rest as usual. Dismissal.`}},matins_weekday:{mon:{sessionals:[{rubric:`After the 1st chanting of the Psalter, the Sessional Hymns of compunction, in Tone III:`,spec_mel:null,items:[{text:`Dwelling on earth, O my soul, repent, for dust doth not chant in the grave, nor is it delivered from transgressions. But cry out to Christ God: O Thou Who knowest the hearts of men, I have sinned against Thee! Before Thou judgest me, have pity and mercy on me, O God.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, sessional set 1, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:3}],label:`plain`},{text:`Wherefore, O my soul, dost thou continue in offenses? Wherefore dost thou abide the setting aside of repentance? Call to mind the coming judgment, and cry out to Christ God: O sinless Lord Who knowest the hearts of men: I have sinned; have mercy on me!`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, sessional set 1, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`}],verses:[{text:`O Lord, rebuke me not in Thine anger, * nor chasten me in Thy wrath.`,tier:2,src:{file:`3-2.pdf`,locus:`Monday Matins, sessional set 1 verse 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]}],closer:{text:`Awed by the beauty of thy virginity * and the exceeding radiance of thy purity, * Gabriel called out unto thee, O Theotokos: * What worthy hymn of praise can I offer unto thee? * And what shall I name thee? * I am in doubt and stand in awe. * Wherefore as commanded, I cry to thee: ** Rejoice, O Full of grace.`,tier:2,src:{file:`3-2.pdf`,locus:`Monday Matins, sessional set 1 closer`},type:`theotokion`}},{rubric:`After the 2nd chanting of the Psalter, the Sessional Hymns, in Tone III:`,spec_mel:null,items:[{text:`At the dread judgment I shall denounce myself, there being no need for accusers, and shall condemn myself, there being no need for witnesses; for the books of my conscience will be opened, and the things I have done in secret will be exposed. Wherefore, O God Who wilt examine my deeds at that universal trial, cleanse me and save me.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, sessional set 2, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Thou knowest the depth of mine offenses, O Lord. Give me a helping hand, as Thou didst to Peter, and save me.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, sessional set 2, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`The goodly courage of your endurance vanquished the wiles of the enemy, the author of evil, O all-famed passion-bearers; wherefore, ye have been deemed worthy of eternal blessedness. But pray ye to the Lord, that He save the flock of Christ-loving people, in that ye are witnesses to the Truth.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, sessional set 2, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`}],verses:[{text:`O Lord, rebuke me not in Thine anger, * nor chasten me in Thy wrath.`,tier:2,src:{file:`3-2.pdf`,locus:`Monday Matins, sessional set 2 verse 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]},{text:`Wondrous is God in His saints, * the God of Israel.`,tier:2,src:{file:`3-2.pdf`,locus:`Monday Matins, sessional set 2 verse 2`}}],closer:{text:`Rejoice, O Mary, Virgin Mother, holy mountain, garden of Eden, from whom Christ God, the seedless Word was born, and through Whom life hath budded forth upon the world.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, sessional set 2 closer`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],type:`theotokion`}},{rubric:`After the 3rd chanting of the Psalter, the Sessional Hymns, in Tone III:`,spec_mel:`Awed by the beauty of thy virginity ...`,items:[{text:`When we shall stand before Thine inexorable tribunal and divine judgment, before which the hosts of heaven stand with trembling, how then shall I appear before Thee, O most righteous Judge? I have done deeds worthy of condemnation and fire. Yet at the supplications of Thine angels have pity on me then, and save me!`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, sessional set 3, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`By Thy word Thou didst bring into being those in heaven and those on earth, in that Thou art almighty; and the angelic choirs, standing before Thee with fear, offer Thee unceasing hymnody, O Master, illumining all the ends of the earth with Thy light. And with them we also cry out to Thee: In Thy tender compassion save us!`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, sessional set 3, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`}],verses:[],closer:{text:`As an uncultivated vine, O Virgin, * thou didst sprout forth the most comely Cluster of grapes * Which poureth forth upon us the wine of salvation * making glad the souls and bodies of all. * Wherefore, ever blessing thee as the cause of good things, * with the angel we cry out to thee: ** Rejoice, O thou who art full of grace!`,tier:2,src:{file:`3-2.pdf`,locus:`Monday Matins, sessional set 3 closer`},type:`theotokion`}}],canons:[{title:`Canon of compunction, to our Lord, Jesus Christ and His holy martyrs, the composition of Joseph, in Tone III`,heading_rubric:`Canon of compunction, to our Lord, Jesus Christ and His holy martyrs, the composition of Joseph, in Tone III:`,odes:{1:{irmos:{text:`Having engulfed the chariots of Pharaoh in the deep, * Thou didst part the sea, O Lord, * and save the people of Israel, * who praised Thee with hymns.`,tier:2,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 1 irmos`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]},items:[{text:`O Sinless One, deliver me from the myriads of transgressions I have mindlessly committed, granting me tears of compunction, as once Thou didst to the harlot.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 1, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Through the virtues show me to be Thy temple, though I am become a den of thieves through mine unseemly deeds, O Thou Who, as the Lover of mankind, wast willingly born in a cave.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 1, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Piloted by the divine Spirit, ye navigated the tempest of torments, O divinely inspired martyrs, and have put in at the harbor of God.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 1, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`Enlightened by the grace of the Spirit, O all-famed martyrs, rejoicing, ye escaped the most profound darkness of the madness of idolatry .`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 1, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`O all-holy and most pure one, helper of sinners, restoration of the fallen: Grant the repentance of compunction unto me who have sinned greatly.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 1, item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},3:{irmos:{text:`Do Thou firmly establish me O Lord * Who alone art abundantly merciful; * and extend Thy hand unto me, * as Thou didst to Peter, * and save me.`,tier:2,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 3 irmos`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]},items:[{text:`As Thou didst save drowning Peter, O Lover of mankind, so also lead me up from the depths of my transgressions.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 3, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`The deceiver hath brought death upon me, slaying me with the passions; but do Thou, O Bestower of life, revive me by examples of repentance.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 3, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Unjustly consumed by material fire, O martyrs, ye were immaterially consumed by the desire for the Immaterial One.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 3, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`Torn asunder, the martyrs set at naught the maiming and pursuits of the deceiver; and they were deemed worthy of crowns.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 3, item 4`},label:`martyrs`},{text:`O Mary of regal calling, by thy supplications free me who am beset by many soul-destroying passions.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 3, item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},4:{irmos:{text:`Wast Thou angered by the rivers?, * wast Thy wrath upon the rivers, * or Thy strivings upon the seas?`,tier:2,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 4 irmos`}},items:[{text:`Loose the bonds of my passions, O Lord, and, binding me with repentance, show me to be a sharer in Thy good things.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 4, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Illumine me with radiant examples of repentance, O Christ my Sun, dispelling the deep nighttime of mine evils.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 4, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O wise spiritual athletes, ye were shown to be burning coals consuming the tinder of ungodliness, and enlightening those in darkness.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 4, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`Ye emulated the death of Christ, O martyrs, having been subjected to divers pangs; wherefore, ye have inherited divine life.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 4, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`Grant me true repentance, and still the tumult of my passions, O pure intercessor for the sinful.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 4, item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},5:{irmos:{text:`By Thine unwaning light, O Christ, * do Thou illumine my humble soul * and guide it in Thy fear * for Thy commandments are light.`,tier:2,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 5 irmos`}},items:[{text:`Leave me not stripped naked of good deeds at Thy tribunal, O Lover of mankind; but through repentance clothe me in the raiment of godly deeds.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 5, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`I have been wounded by the sword of the passions and cast into the pit of despair. Disdain me not, O Master, but cure me with the medicine of conversion.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 5, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Though your nails were cruelly torn out, and ye were lacerated with wounds and slain with the sword, ye did not bend your knees before the graven images.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 5, item 3`},label:`martyrs`},{text:`The world is ever adorned by your sufferings, O martyrs; wherefore, ye have received a dwelling-place with the angels.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 5, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`O thou who, at the word of the archangel, didst alone give birth to the Word in the flesh, yet remained a virgin, deliver me from irrational acts, that I may hymn thee with honorable words.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 5, item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},6:{irmos:{text:`O Lover of mankind, disdain not those * who have reached the end of the ages * and are assailed with destruction by the threefold billows of perils, * yet cry aloud: O Savior, save us, * as Thou didst save the prophet from the sea monster!`,tier:2,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 6 irmos`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}]},items:[{text:`Puffed up in mind, like the Pharisee of old I have grievously fallen through transgressions O Christ, and seeing me, the deceiver is gladdened. O Thou Who didst humble him by the Cross, have pity on me who am now brought low.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 6, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Sin-loving in this life like no other, O Master, I have wasted Thy long- suffering, wretch that I am, and am still senseless. But by Thy tender compassion convert me.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 6, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`With wrathful eagerness condemning the divinely wise to be run through and to be consumed by fire, the violators of the law showed them to be truly more lustrous than gold, and heirs to Christ.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 6, item 3`},label:`martyrs`},{text:`Passing through trials full of battles and tremendous struggles, and wounds beyond the endurance of human nature, ye defeated the prince of darkness and received crowns from God, O spiritual athletes.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 6, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`We hymn thee, the true Mother of the Creator, as the ark of the law, the truly holy table, our mercy-seat, the animate temple of God, and the all- golden lampstand.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 6, item 5`},label:`theotokion`}]},7:{irmos:{text:`The three children in the furnace, prefiguring the Trinity: * trampled underfoot the threat of the fire * and cried aloud, chanting: * Blessed art Thou, O God of our fathers!`,tier:2,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 7 irmos`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]},items:[{text:`My time draweth to a close, O my soul. My departure is at hand. Wherefore, show forth the fruits of repentance before the doors are closed to thee, and cry out unto Christ: Save me, O Lord!`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 7, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`Let us till our hearts with the plough of a proper understanding, sowing the wheat of repentance, that we may reap the grain of righteousness for Christ, the Husbandman of our souls.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 7, item 2`},label:`plain`},{text:`O martyrs of the Lord, ye beacons of piety who fought against ungodliness and became the enrichment of the poor: Enrich with the virtues my most accursed, impoverished soul.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 7, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`O Christ, Who didst save the publican who sighed from the depths of his heart, accept my feeble sighing and save me, for the sake of the passion-bearers who glorified Thee by their own members.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 7, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`O wellspring who pourest forth the water of remission, dry up the stench of my transgressions, granting me a shower of tears, that I may ever hymn thee as the Theotokos.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 7, item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},8:{irmos:{text:`In His divine power the Lord descended into the flames * and was seen walking with the Children of the Hebrews: * O ye priests, bless and supremely exalt Him throughout all ages.`,tier:2,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 8 irmos`}},items:[{text:`For his mockery Ham was declared a slave by his father’s sentence. And what dost thou do, O my soul, enslaving thyself to the passions and riotously giving thyself over to mockery, lacking all sense of shame before the heavenly father?`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 8, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Mindlessly surrendering to enmity, Cain became the slayer of his brother. And thou hast shown thyself to be like unto him, for though thou hast not slain anyone, yet thou hast brought death upon thyself through the love of pleasures and the deceptions of life, O my soul.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 8, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Assembling in faith, let us hymn as is meet the choice pearls of the Lord, the precious vessels, the lamps shining with the radiance of divine grace, the passion-bearers of the Lord.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 8, item 3`},label:`martyrs`},{text:`Accepting the blood of the wise passion-bearers like incense, O Word, by their prayers save those who fall down before Thee in repentance, for Thou alone art merciful.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 8, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`Because of the magnitude of my prodigal life I have now drawn nigh unto Hades. O most tenderly compassionate maiden, have pity and save me, in that thou didst ineffably give birth to the loving God.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 8, item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},9:{irmos:{text:`Upon Mount Sinai Moses saw thee in the bush, * as one who didst conceive the fire of the Godhead within thy womb, * and yet remained unconsumed. * Daniel saw thee as a mountain not cut by the hand of man, * and Isaiah proclaimed thee as the Rod that blossomed forth * from the root of David.`,tier:2,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 9 irmos`}},items:[{text:`Once, because of his temperance, Jacob received the birthright, and, unable to restrain his stomach, Esau fell from his position as the elder son. How evil is intemperance, and how great is abstinence! Cease committing evil deeds, O my soul, and love the increase of good things.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 9, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Having endured many evils, the blameless Job was crowned; for the torrents of temptations, rushing at him, did not shake the tower of his heart. Him do thou ever emulate, remaining unaffected by the wiles of the evil one, O my soul.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 9, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Forged in the fire of the divine Spirit, ye were clearly shown to be swords which cut down the hordes of the adversary, O passion-bearers of Christ; and, glorified by great victories, ye have been crowned by the almighty right hand of the King of all.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 9, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`O ye multitude of martyrs, entreat God the Master, Who hath accepted your ineffable toils and enrolled you in the armies of the incorporeal ones, that He wash away the multitude of my countless evils.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 9, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`O splendid palace of the Master, show me to be a dwelling-place of light; O impassable gate, open unto me the ways of repentance; O holy land, guide me to the land of the meek. O Lady, show me to be free of all the dominion of the passions.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 1, Ode 9, item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:4}],label:`theotokion`}]}},composer:`Joseph`},{title:`Another canon, of the holy incorporeal angels, the acrostic whereof is “I compose a third hymn for the incorporeal ones,” the composition of Theophanes, in Tone III`,heading_rubric:`Another canon, of the holy incorporeal angels, the acrostic whereof is “I compose a third hymn for the incorporeal ones,” the composition of Theophanes, in Tone III:`,odes:{1:{irmos:{text:`Let us chant a new song O ye people, * unto Him Who was born from the Virgin for our salvation * and hath made those on earth one with those in heaven * for He hath been glorified.`,tier:2,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 1 irmos`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]},items:[{text:`As the Light without beginning, imparting all radiance, O Christ God, enlighten my thoughts through the intercessions of Thy hosts.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 1, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Rejoicing angelically, the choirs of the angels are mystically illumined by a most rich communion of Thy beauteous splendors, O Savior.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 1, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`As the good Creator of life, the Spirit, Who doeth good and Who proceedeth from the Father, hath made steadfast the heavenly hosts by His intangible divine grace.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 1, item 3`},label:`plain`},{text:`O most noetically rich Gabriel, divine chief captain of the incorporeal choirs: Unto her who is joyous utter the cry of joy: Rejoice, O all- immaculate one!`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 1, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`theotokion`}]},3:{irmos:{text:`Thou hast broken the bow of the enemy * and crushed their shields by Thy might, * O Master Christ, our confirmation, * holy art Thou O Lord!`,tier:2,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 3 irmos`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}]},items:[{text:`O good One, Thou hast shown the angelic choirs to be rivers and streams flowing with goodness, shining with the radiance of Thy hidden mystery.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 3, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`That Thou mightest manifestly show forth the treasures of Thy riches and Thy might, O Master Christ, Thou didst fashion the noetic hosts to share in Thy glory.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 3, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Standing with trembling before Thee and ministering to Thee, the angelic luminaries ever hymn Thine infinite power, O Christ.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 3, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`The Master of all that is, immutably taking on all of humanity from thee, O Mother of God, showed thee to be a source of grace.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 3, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},4:{irmos:{text:`Strange and ineffable was the mystery of Thy nativity. * I heard report of Thee, and was afraid; * and, rejoicing, I cry unto Thee: * Glory to Thy power, O Lover of mankind!`,tier:2,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 4 irmos`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]},items:[{text:`O clouds who received the effulgence of the threefold Sun, ornaments of the Trinity: Impelled by the power of the Spirit ye were borne aloft by the divine will.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 4, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`The angels were sent into the world as guardians of the salvation of the pious who would believe on Thee, O Savior; and they preserve Thy servants.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 4, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`The angels are mystically illumined by their pure proximity to Thee and Thy divine effulgence; and they cry aloud: Glory to Thy power, O Lover of mankind!`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 4, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Like a servant, I come as a supplicant before Thy protection, O most immaculate one. Deliver me from the turmoil of the passions, O Birthgiver of God, who without suffering hast given birth to our Cause.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 4, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`theotokion`}]},5:{irmos:{text:`The Invisible One hath appeared on earth, * and the Unapproachable One hath willingly dwelt among mankind; * and, rising early at dawn, we hymn Thee, * O Lover of mankind.`,tier:2,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 5 irmos`}},items:[{text:`Illumined with thrice-radiant light, O ye faithful, with the angelic armies let us hymn the one Godhead: the Father, the Son and the Spirit.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 5, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Luminaries moving within the never-waning radiance of the supremely divine Godhead, the angelic ranks, manifestly enriched, give utterance.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 5, item 2`},label:`plain`},{text:`The seraphim, angels illumined by the Spirit of the Godhead, teach us to worship the one divine Principle which is wholly without beginning, manifestly giving utterance to the thrice-holy cry.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 5, item 3`},label:`plain`},{text:`Descending from heaven, the Archangel Gabriel announced to thee, O all-pure maiden Theotokos, that thou wouldst give birth seedlessly to the Bestower of life.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 5, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},6:{irmos:{text:`As an image of habitation in the uttermost depths of Hades, * Jonah cried aloud: * Lead up my life from corruption, * O Lover of mankind!`,tier:2,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 6 irmos`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]},items:[{text:`Their voices never stilled, the archangels and angels, the principalities, authorities and powers mightily hymn the primal and all-accomplishing effulgence of the Godhead.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 6, item 1`},label:`plain`,repeat:2},{text:`O Thou Who didst invisibly adorn the noetic world with an all-harmonious arrangement of the ranks of angels, Thou wast well-pleased to have the honored Church emulate that goodly order.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 6, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`The Word Who dwelt within thee hath shown thee to be an ever- flowing wellspring of healings; wherefore, O Virgin Theotokos, heal thou the wounds of my soul`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 6, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},7:{irmos:{text:`Proud was the tyrant; * yet he was as a plaything for the children; * for, trampling underfoot the flame heated sevenfold, * they chanted: Blessed art Thou, * O Lord God of our fathers!`,tier:2,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 7 irmos`}},items:[{text:`Gazing upon the primal effulgence with steadfast mind and undaunted gaze, O ye angelic choirs, ye became secondary luminaries through partaking thereof, crying aloud: Blessed art Thou, O God of our fathers!`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 7, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`,repeat:2},{text:`Led on by unwavering desire and steadfast love, by proximity ye became secondary luminaries through the beauties of the Creator, O ye angelic choirs, crying aloud: Blessed art Thou, O God of our fathers!`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 7, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`In thy divine birthgiving, O Theotokos, thou hast given birth in the flesh to the pre-eternal Word, Who is wholly without beginning and was begotten of the Father without mother. Blessed is the Fruit of thy womb, O Lady!`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 7, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`theotokion`}]},8:{irmos:{text:`The flame of material fire withered * through the immaterial flame brought about by the god-seeing children, * wherefore they chanted: * Bless the Lord, all ye works of the Lord!`,tier:2,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 8 irmos`}},items:[{text:`As the Creator of all, by Thy thought Thou didst bring the angels into being; and they stand before Thee with fear, crying aloud: Bless the Lord, all ye works of the Lord, and supremely exalt Him throughout all ages!`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 8, item 1`},label:`plain`},{text:`Becoming like flames by partaking of the divine fire, the celestial intelligences cry aloud: Bless the Lord, all ye works of the Lord, and supremely exalt Him throughout all ages!`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 8, item 2`},label:`plain`},{text:`Before visible things Thou didst create the immaterial and noetic angels, who unceasingly cry out to Thee: Bless the Lord, all ye works of the Lord, and supremely exalt Him throughout all ages!`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 8, item 3`},label:`plain`},{text:`O Virgin Birthgiver of God, in a manner transcending description thou hast given birth to the Word of the Father, incarnate, Whom all the works of the Lord hymn and supremely exalt throughout all ages.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 8, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`},{text:`refrain: “More honorable than the cherubim ...,” and make prostrations.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 8, item 5`},label:`plain`}]},9:{irmos:{text:`Wounded with the sweet arrow of thy most pure birthgiving, * O pure one, * marveling at thy right desirable beauty, * with angelic hymnody we magnify thee as is meet * as the Mother of God.`,tier:2,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 9 irmos`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]},items:[{text:`Standing now before the great and primal Light, O most divine angels of God, ye have become most powerful advocates for all of us who magnify you as far as we are able.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 9, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`,repeat:2},{text:`Clearly deemed worthy to glorify the Trinity equal in power, and first illumined by the effulgence thereof, grant us who piously magnify you, that we may be illumined with reflected radiance.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 9, item 2`},label:`plain`},{text:`We all know thee to be the foundation of our salvation; for by thy deifying blood thy most pure birthgiving hath saved those who with faith hymn and glorify thee, O Theotokos.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, canon 2, Ode 9, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]}},acrostic:`I compose a third hymn for the incorporeal ones`,composer:`Theophanes`}],magnificat_rubric:`We then chant the hymn of the Theotokos (the Magnificat), with the`,post_canon_rubric:`Then, “It is truly meet to bless thee ...,” and a prostration. Small litany, Exapostilarion, and the usual psalms. Small Doxology (Read), Litany: Let us complete ..., On the Aposticha, these Stichera of compunction, in Tone III:`,aposticha:{rubric:`On the Aposticha, these Stichera of compunction, in Tone III:`,items:[{text:`Gather the scattered thoughts of my mind, O Lord, and purify my barren and wasted heart, granting me repentance as didst Thou to Peter, that like the Publican I may sigh in sorrow, and like the Harlot shed tears, that I may cry with a loud voice unto Thee: Save me, O God, for Thou alone art compassionate and the Lover of mankind.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, aposticha item 1`},label:`plain`},{text:`While offering a multitude of hymns, I am found to be sinning; for chanting hymns with my tongue, my soul doth dwell on wicked thoughts. * But do Thou, O Christ God set both aright through repentance, and have mercy upon me.`,tier:2,src:{file:`3-2.pdf`,locus:`Monday Matins, aposticha item 2`},label:`plain`},{text:`Come, O ye people, and let us all honor the memory of the holy passion-bearers; for, having been a spectacle for angels and men, they received crowns of victory from Christ, and pray on behalf of our souls.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, aposticha item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`}],verses:{ref:`shared.weekday_aposticha_verses.sets.standard_matins`}},aposticha_theotokion:{text:`O pure Lady of the originate holiness, who art the boast of the heavenly ranks, the subject of the apostles’ hymnody and the fulfillment of the prophets, accept our supplications.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Matins, aposticha Glory/Both-now closer`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],type:`theotokion`},closing_rubric:`Then, “It is good to give thanks ...,” Trisagion ..., Our Father ..., Troparia.`},tue:{sessionals:[{rubric:`After the 1st chanting of the Psalter, the Sessional Hymns of compunction, in Tone III:`,spec_mel:null,items:[{text:`O my soul, while sojourning on the earth, repent, for dust doth not chant in the grave, nor doth it deliver us from transgressions; but cry out to Christ God: O Thou Who knowest the heart of man, I have sinned against Thee! Before Thou condemnest me, have pity, O God, and have mercy upon me.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, sessional set 1, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:3}],label:`plain`},{text:`How long, O my soul, shalt thou remain in thine offenses? How long shalt thou put repentance aside? Be thou mindful of the coming judgment, and cry out to Christ God: O Thou Who knowest the heart of man, I have sinned! O sinless Lord, have mercy upon me!`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, sessional set 1, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:3}],label:`plain`}],verses:[{text:`O Lord, rebuke me not in Thine anger, * nor chasten me in Thy wrath.`,tier:2,src:{file:`3-3.pdf`,locus:`Tuesday Matins, sessional set 1 verse 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]}],closer:{text:`Thou art our refuge and strength O Theotokos, the mighty help of all the world: by thy supplications do thou protect thy servants from every want, O thou who alone art blessed`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, sessional set 1 closer`},type:`theotokion`}},{rubric:`After the 2nd chanting of the Psalter, the Sessional Hymns, in Tone III:`,spec_mel:null,items:[{text:`At the dread judgment I shall denounce myself, there being no need for accusers, and shall condemn myself, there being no need for witnesses; for the books of my conscience will be opened, and the things I have done in secret will be exposed. Wherefore, O God Who wilt examine my deeds at that universal trial, cleanse me and save me.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, sessional set 2, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Thou knowest the depth of mine offenses, O Lord. Grant me a helping hand, as Thou didst to Peter, and save me.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, sessional set 2, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Ye shine forth in faith, O all-radiant beacons, holy physicians of the infirm, all-famed passion-bearers; for ye were undaunted by the wounds inflicted by the torturers and cast down the ungodliness of the idols, having the Cross as a truly invincible trophy.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, sessional set 2, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`}],verses:[{text:`O Lord, rebuke me not in Thine anger, * nor chasten me in Thy wrath.`,tier:2,src:{file:`3-3.pdf`,locus:`Tuesday Matins, sessional set 2 verse 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]},{text:`Wondrous is God in His saints, * the God of Israel.`,tier:2,src:{file:`3-3.pdf`,locus:`Tuesday Matins, sessional set 2 verse 2`}}],closer:{text:`Accept me who with faith flees beneath thy protection, O Lady, and despise me not, neither disdain me who entreat thee in repentance, O good one. Receive the supplication which cometh from mine unworthy mouth, and by thy mediation deliver me from all snares, that I may cry out to thee with boldness: Rejoice, O joyous one!`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, sessional set 2 closer`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:3}],type:`theotokion`}},{rubric:`After the 3rd chanting of the Psalter, the Sessional Hymns, in Tone III:`,spec_mel:null,items:[{text:`Fleeing under thy protection, we cry out with faith from the depths of our heart: O divinely blessed prophet and Forerunner, quell the tumults of perils and misfortunes and the waves of infirmities, and foil the wily counsels of the enemy, asking great mercy for us.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, sessional set 3, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Shaking off thy despondency by repentance before thy departure, O wretched soul, turn thou with weeping, crying out to the innocent Jesus, the Lover of mankind: I have sinned against Thee, O Master, but in that Thou art full of loving-kindness, save me by the prayers of the holy Forerunner, in that Thou alone art sinless.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, sessional set 3, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`}],verses:[],closer:{text:`Beyond understanding and unapproachable is the dread mystery of God wrought in thee, O divinely joyous Lady; for having conceived the Infinite One, thou didst give birth to Him, clad in the flesh taken from thy most pure blood. Him do thou ever entreat as thy Son, O pure one, that our souls be saved.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, sessional set 3 closer`},type:`theotokion`}}],canons:[{title:`Canon of repentance, to our Lord Jesus Christ & His martyrs, the acrostic whereof is “Hearken unto my groaning, O Word of God,” the composition of Joseph, in Tone III`,heading_rubric:`Canon of repentance, to our Lord Jesus Christ & His martyrs, the acrostic whereof is “Hearken unto my groaning, O Word of God,” the composition of Joseph, in Tone III:`,odes:{1:{irmos:{text:`Wondrous art Thou, O God, * Who gloriously workest wonders, * Who didst fashion the earth from the abyss, * and didst cover the chariots and save the people who sing to Thee * as our King and God.`,tier:2,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 1 irmos`}},items:[{text:`Before the end, O ye faithful, let us weep for ourselves with all our soul. The Bridegroom approacheth; let us light our deeds as though they were radiant lamps, that together we may enter the divine bridal-chamber.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 1, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Repenting with all his soul, Manasseh of old was saved; for he cried out to the one Master from the midst of his fetters. Him do thou emulate, O my soul, and thou shalt easily find salvation.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 1, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`While the divine spiritual athletes endured the blinding of their eyes, the severing of their hands, the uprooting of their tongues, the amputation of their feet, and the breaking of their legs and arms, they gave thanks unto Jesus Christ.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 1, item 3`},label:`martyrs`},{text:`O holy martyrs, the shrine of your relics hath been revealed to be the cure of all of us, the faithful, whence we who ever honor you as is meet draw forth healing of our souls and bodies.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 1, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`O all-hymned Virgin, the noetic jar which held Christ, the Manna of immortality: Deliver me from the bitterness of the soul-corrupting passions, that with faith I may piously glorify thee.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 1, item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},3:{irmos:{text:`O barren and infertile soul, * bring forth a crop of glorious fruit and joyously cry aloud: * I have been firmly established by Thee O God; * there is none holy and none more righteous than Thee, O Lord.`,tier:2,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 3 irmos`}},items:[{text:`I have senselessly broken the law of God, and must needs be condemned. And I know not what I shall do. O most righteous Judge, have pity and save me in Thy loving-kindness.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 3, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O greatly Merciful One Who lovest mankind, Thou Dayspring of the East: Shine forth the light of righteousness upon me, I pray, rescuing me from the gloom of the passions and the darkness of torment.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 3, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O holy martyrs, ye have been revealed to be inhabitants of the noetic land, fruitful trees of paradise, wellsprings of divine water, and chalices pouring forth a holy drink.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 3, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`Bearing a single character in many bodies, O passion-bearers and martyrs, preaching the indivisible Trinity ye conquered hordes of the enemy, and the prince of this world.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 3, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`O most pure Virgin Mother, Sovereign Lady of all: Render Christ merciful unto all of us, who repent and flee unto Him, and who desire to receive release from our transgressions.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 3, item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},4:{irmos:{text:`Habakkuk foresaw the overshadowed mountain, * even thine immaculate womb, O pure one. * Wherefore he cried; God shall come forth from Thaeman, * and the Holy One from a mountain * densely overshadowed.`,tier:2,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 4 irmos`}},items:[{text:`O Christ God, Who of old poured forth water from the rock for the disobedient and gainsaying people, quenching their thirst: From my stony soul draw forth a drop of compunction that I may be washed clean.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 4, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O Physician of the sick, as a gesture of compassion cure my heart of the passions, applying repentance to it as a dressing of divine medicine, O Savior, in that Thou art good, that with faith I may glorify Thee.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 4, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`O passion-bearers, mercifully putting away all thought of friendship for the body, ye gave yourselves over to those who would torture you; wherefore, ye became close friends of the Creator.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 4, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`Ye endured the agonizing wounds of multifarious torments, O spiritual athletes of Christ, and received the grace of the gifts of the Spirit; and ye drive away the chronic pangs of our passions.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 4, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`Rejoice, O maiden of great renown, from whom God the Word was born, releasing us from irrational and unseemly deeds! Rejoice, O radiant cloud who dispellest the clouds of our despondency!`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 4, item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`theotokion`}]},5:{irmos:{text:`Rising at dawn, we hymn Thee, O Word, * Thou only-begotten Son of God. * Grant us Thy peace, and have mercy on us * who with faith hymn and worship Thee.`,tier:2,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 5 irmos`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]},items:[{text:`Sprinkling me with the hyssop of repentance, purify me of the defilements of the passions, O Jesus, that I may appear before Thee clean when Thou shalt judge all mankind in Thy righteous judgment.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 5, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`The wounds of my most wretched soul have festered, O Savior. O Healer of the sick and Bestower of good things, heal Thou and save me in Thy surpassing mercy.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 5, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`On earth, the bodies of the passion-bearers were broken like vessels of clay, but the might of their souls was wholly strengthened and illumined by the power of Christ.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 5, item 3`},label:`martyrs`},{text:`The blood which the saints shed hath sanctified the whole earth; and given drink to the souls of the faithful, clearly drying up the surging torrents of vanity.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 5, item 4`},label:`martyrs`},{text:`By thy birthgiving thou didst render barren the curse upon our forefather, O maiden, and hast poured forth rivers of blessing upon us, who bless and glorify thee with faith.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 5, item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},6:{irmos:{text:`The abyss of the passions and a storm of adverse winds * have risen up against me. * But do Thou make haste, O Savior, * to save me, and deliver me from corruption, * as Thou didst deliver the prophet from the sea-monster.`,tier:2,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 6 irmos`}},items:[{text:`I have been darkened by the gloom of sin and lie wholly dormant. O Christ God, Who wast once wounded by a spear for my sake, have pity on me in Thy tender compassion.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 6, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`I groan, yet I remain sunk in evils; I weep, yet I tremble not before the judgment; I experience pain, but remain unfeeling. O Word of God, have pity and save me by Thy good judgments!`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 6, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Wholly mute, like lambs which neither bleat nor sound, O all- glorious spiritual athletes, ye were led to wounding and slaughter, hymning Christ.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 6, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`With joyous soul ye were cast as food to the wild beasts and hurled into the depths of the sea; wherefore, O spiritual athletes, Christ hath adorned you with imperishable crowns.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 6, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`O portal of those saved by faith, gate through which He alone Who became incarnate for us hath entered: Open the doors of righteousness unto us who hymn thee with faith.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 6, item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},7:{irmos:{text:`Thou didst bedew the flame of the furnace * and save the Children from being consumed: * blessed art Thou throughout the ages, * O Lord the God of our fathers.`,tier:2,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 7 irmos`}},items:[{text:`I have stripped myself of the garments of incorruption and clothed myself in deeds of ungodliness; wherefore, I cry out to Thee: O Compassionate God, make me splendid in the raiment of the virtues.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 7, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`I have sullied myself with lustful gazes and defiled myself by unseemly touching, and am become vile in Thy sight. O Jesus, accept me as Thou didst the prodigal!`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 7, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Loving the heavenly life, ye endured many pangs, O warriors of Christ, divine luminaries; wherefore, with faith ye are called blessed.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 7, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`Having been enlightened with the splendor of martyrdom, ye shine forth more brightly than the sun, driving away all the gloom of ungodliness, O holy martyrs.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 7, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`In that thou hast given birth to the Upholder of all, O pure Ever- virgin Theotokos, deliver me from sin and the gloom of ignorance which holdeth me.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 7, item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},8:{irmos:{text:`God is unceasingly glorified on high by the angels, * O ye heaven of heavens, * ye earth and mountains, ye plains and abysses, * and all the race of mankind, * with hymns as to the Creator and Redeemer, * bless ye, and supremely exalt Him throughout all ages.`,tier:2,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 8 irmos`}},items:[{text:`I have not the fear of Thee dwelling in my heart, and, devoid of conscience, I have brought carnal pleasure to fulfillment; and trembling before Thy judgment, O King of all, I beseech Thee: Disdain me not, who now repent.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 8, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Washing earthly sin from me by repentance, grant that I may pass over to the holy land wherein the meek dwell, O greatly Merciful One Who wast born on earth from the Virgin without sin.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 8, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Your feet, dyed in your own blood, trampled the enemy underfoot, and in holiness now traverse the heavens, O all-glorious passion- bearers of Christ, the God of all.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 8, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`With care ye arrayed yourselves for struggles and great battles, and stripped the enemy bare, clothing him in shame; wherefore, ye join chorus in the heavens, O glorious crowned passion-bearers.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 8, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`Loving thee, the beauty of Jacob, the Lord, Who is beauteous in comeliness, made His abode within thy womb, O all-immaculate one, enlightening human nature with beauties and gifts transcending understanding.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 8, item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},9:{irmos:{text:`Blessed is the Lord God of Israel, * Who hath exalted the horn of our salvation * in the house of David His child, * for the sake of His loving- kindness; * the Dayspring from on high hath therein visited us, * guiding us to the path of peace.`,tier:2,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 9 irmos`}},items:[{text:`Now is the right acceptable time and the day of purification! Turn, O my soul, and make it thy will henceforth to bring forth fruits of repentance, lest the dread axe of death find thee barren and, having cut thee down like the fig-tree of old, sendeth thee into the fire.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 9, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Like the rich man of old I wallow in pleasures, lacking any great love for my neighbor; and I am not frightened by the unquenchable fire. Wherefore, soften the hardness of my soul, O Master, that in the end I who am darkened may, if but a little, be enlightened by loving-kindness.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 9, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Having been sealed by the divine blood of Christ, mightily suffering lashings with faith, O martyrs, ye have laid low the infidel foe and rescued many people from vile delusion by your divine feats, illumining them with the light of the knowledge of God`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 9, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`O godly martyrs of Christ, ye were shown to be sharp-edged swords cutting down the hordes of the enemy, vessels containing the radiance of the Holy Trinity, lamps shedding the light of piety upon the faithful, and true warriors of the noetic Sion.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 9, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`The prophet foresaw thee as the radiant cloud from which Christ God, the great Sun, appeared unto us, enlightening those who before were darkened. Beseech Him, O good one, that He dispel the clouds of my passions and illumine me with divine light.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 1, Ode 9, item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]}},acrostic:`Hearken unto my groaning, O Word of God`,composer:`Joseph`},{title:`Another canon, of the holy forerunner, in Tone III`,heading_rubric:`Another canon, of the holy forerunner, in Tone III:`,odes:{1:{irmos:{text:`He who of old gathered the waters * into one by His divine decree, * divided the sea for the people of Israel. * For He is our God and supremely glorious, * to Him alone let us sing, for He hath been glorified.`,tier:2,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 1 irmos`}},items:[{text:`O Forerunner of the Lord, godly offspring of a barren womb: Pray to God, that I may produce the fruits of the virtues, and loose the barrenness of my sin, dispelling the gloom from my mind.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 1, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`By faith thou wast revealed to be a star preceding the great Sun of glory on earth, Who hath illumined the whole world. Wherefore, entreat Him, O Forerunner, that He enlighten my soul, which hath been darkened by evil thoughts.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 1, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Prophet, who by the divine Spirit announced beforehand to those in Hades the Light Who was drawing nigh: By thy prayers give life to my deadened soul, and raise me up from my transgressions as from a grave, I pray, O glorious Forerunner.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 1, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`With the archangels and angels, and all the saints, entreat the Lord Who through thee revealed Himself to us, we pray, O Virgin, that we who confess thee to be the true Theotokos may be delivered from misfortunes.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 1, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},3:{irmos:{text:`O Most High, Ruler of all, * who out of nothing hath established all things, * fashioned by Thy Word, * perfected by the Spirit, * confirm me in Thy love.`,tier:2,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 3 irmos`}},items:[{text:`As thou art the voice of the Word, O Baptist, direct now the cries of those who honor thee unto Him, and by thy mediation grant us remission of sins.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 3, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`I have sinned against Thee and defiled my soul O Savior, having committed iniquity and transgressions. Wherefore, I pray Thee: Have pity on me for the sake of him who baptized Thee.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 3, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`I beseech thee, O Forerunner, thou child of the desert and guide of the new people of God; guide me to the paths of repentance, who through pleasures have gone astray in the wilderness.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 3, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`With the apostles, the sacred prophets, the martyrs and the heavenly hosts pray to thy Son, O most pure one, that He have pity on us who hymn thee.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 3, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},4:{irmos:{text:`Thou hast shown us steadfast love, O Lord, * for Thou gavest Thine only-begotten Son over to death for our sake. * Wherefore with thanksgiving we cry unto Thee, * ‘Glory to Thy power, O Lord!’`,tier:2,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 4 irmos`}},items:[{text:`O Forerunner of the Lord, I pray thee who art the voice of the Word Who appeared in the flesh: Deliver me from irrational actions for as is meet, I honor thee with my words and bless thee with faith.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 4, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Sigh, O my soul, and cry out to God, thy Creator: I have sinned! Cleanse me, O Christ, and at the entreaties of the divine Forerunner deliver me from dreadful torment, misfortunes and tribulations.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 4, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`Rescue me, who am drowning in the many waves of grievous passions, and am cruelly beset by storms, ever foundering therein, O Baptist, and guide me to the harbor of repentance.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 4, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O all-immaculate Mother of God, O chariot more exalted than the cherubim: With the immaterial ministers and all the saints entreat Christ to Whom thou hast given birth, that He save me, the accursed one.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 4, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`theotokion`}]},5:{irmos:{text:`The Invisible One hath appeared on earth, * and the Unapproachable One hath willingly dwelt among mankind; * and, rising early at dawn, we hymn Thee, * O Lover of mankind.`,tier:2,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 5 irmos`}},items:[{text:`On earth thou didst manifestly live like an angel in the flesh, O blessed one; wherefore, I pray to thee: Free my soul from, carnal-mindedness.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 5, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O Forerunner of the Lord, save me, who have fallen into the abyss of sin, who have defiled my soul with pleasures, and am in distress, yet flee unto thee.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 5, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Thou wast revealed to be more exalted than the prophets, O prophet, for thou thyself didst see Him Whom thou didst proclaim. Him do thou unceasingly entreat, that He enlighten our souls.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 5, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O divinely joyous one, who by the indwelling of the Word wast revealed to be more spacious than the heavens: Free me from the sins which smother me.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 5, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},6:{irmos:{text:`The uttermost depths of sin have surrounded me, * and my spirit perisheth, * but do Thou, O Master, stretch forth Thy lofty arm * and like Peter O Helmsman, * do Thou save me.`,tier:2,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 6 irmos`}},items:[{text:`In the waters thou didst baptize the Torrent of sweetness, Who bowed His head beneath thy hand. Him do thou entreat, O wise one, that He send down the water of compunction upon me who have greatly sinned.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 6, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`In the river, O Forerunner, thou didst wash Jesus, the Lover of mankind and Abyss of loving-kindness Who covereth the chambers of the heavens with waters. Him do thou entreat, that He pour forth remission upon me.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 6, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`“Repent, for the kingdom of heaven is at hand!” didst thou cry aloud, O Forerunner. Wherefore, grant that those who honor thee with love and flee beneath thine honored protection may receive it.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 6, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O most pure one, who didst lend thy flesh to the Creator: With the heavenly hosts, all the prophets, the apostles and martyrs, beseech Him to have pity and save me.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 6, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},7:{irmos:{text:`The three children in the furnace, prefiguring the Trinity: * trampled underfoot the threat of the fire * and cried aloud, chanting: * Blessed art Thou, O God of our fathers!`,tier:2,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 7 irmos`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]},items:[{text:`O Forerunner and Baptist of Christ, star of the Sun, my soul, which hath been darkened and blinded by slothfulness, do thou illumine me, guiding me to the path of repentance.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 7, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Mindful of the hour of judgment, I am wholly seized with fear; for I wallow in a multitude of unseemly deeds. But stand forth before me, O thou who didst baptize the Lord, and deliver me from the impending fire.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 7, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O intercessor for my life, O Forerunner my helper, preserve and protect me from enemies, visible and invisible, and cause me to share in the heavenly kingdom.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 7, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O Virgin Theotokos, with the prophets, apostles and martyrs beseech thy Son, that from impending need He deliver us who ever honor thee.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 7, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},8:{irmos:{text:`United together in the unbearable fire, * yet not harmed by the flame, * the children, champions of godliness, sang a divine hymn: * O all ye works of the Lord, * bless ye the Lord and supremely exalt Him throughout all ages.`,tier:2,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 8 irmos`}},items:[{text:`Thou didst preach the Lamb of God Who taketh away our sins, O godly John the Forerunner. Him do thou beseech, that He loose the burden of my sins and grant unto me the portion of the saved.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 8, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`From the furnace of burning flame and the outer darkness which is devoid of light deliver me who am wholly held fast in the darkness of evil deeds, for the sake of Thy glorious and divine Baptist, I pray Thee, O Word of God, Who art wholly without beginning.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 8, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O divine prophet of the Lord, who through repentance preached fruitfulness to empty and barren souls: Clear my thorn-choked soul of all the pleasures, that I may produce the grain of good works.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 8, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`As thou art the Mother of God, with the holy angels, the prophets, apostles and martyrs pray that those who ever confess thee to be the Theotokos may be delivered from misfortunes, tribulations, and all the torments which are to come.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 8, item 4`},label:`theotokion`},{text:`refrain: “More honorable than the cherubim ...,” and make prostrations.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 8, item 5`},label:`plain`}]},9:{irmos:{text:`In the shadow and the letter of the Law, * let us, the faithful, discern a figure: * every male child that openeth the womb * shall be sanctified to God. * Therefore we magnify the firstborn Word * and Son of the beginningless Father, * the firstborn Child of a Mother who hath not known a man.`,tier:2,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 9 irmos`}},items:[{text:`Having entered the tabernacle of the law, thou didst richly gaze upon the splendor of divine grace, O wise prophet, enlightening the ends of the earth and dispelling the darkness of ignorance; wherefore, we honor thee.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 9, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`In that thou art a martyr of Christ, the godly one who baptized Him, a beacon of repentance, the dawning of piety, the mediator between the Old and New Covenants, enlighten my humbled soul, which hath grown old through evil, renewing it with divine understanding.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 9, item 2`},label:`plain`},{text:`At the hour of horror, the hour of terror, the hour of condemnation, from the threats that await me beyond do thou deliver me who am condemned, O wise one, for thou hast the Bridegroom, the Savior of our souls, as a friend hearkening to thy supplications.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 9, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`As the Mother of God, as the Mother of the Word of God Who was born from thee in the flesh, O pure one, ever pray with the incorporeal ones, with the apostles and prophets, the holy hierarchs and martyrs, that He have pity on the world, O most pure Virgin Mother.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, canon 2, Ode 9, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`theotokion`}]}}}],magnificat_rubric:`We then chant the hymn of the Theotokos (the Magnificat), with the`,post_canon_rubric:`Then, “It is truly meet to bless thee ...,” and a prostration. Small litany, Exapostilarion, and the usual psalms. Small Doxology (Read), Litany: Let us complete ..., On the Aposticha, these Stichera of compunction, in Tone III:`,aposticha:{rubric:`On the Aposticha, these Stichera of compunction, in Tone III:`,items:[{text:`Gather the scattered thoughts of my mind, O Lord, and purify my barren and wasted heart, granting me repentance as didst Thou to Peter, that like the Publican I may sigh in sorrow, and like the Harlot shed tears, that I may cry with a loud voice unto Thee: Save me, O God, for Thou alone art compassionate and the Lover of mankind.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, aposticha item 1`},label:`plain`},{text:`While offering a multitude of hymns, I am found to be sinning; for chanting hymns with my tongue, my soul doth dwell on wicked thoughts. But do Thou, O Christ God set both aright through repentance, and have mercy upon me.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, aposticha item 2`},label:`plain`},{text:`The warriors of Christ refused to be intimidated by emperors and tyrants, and right boldly and manfully they confessed Him, the Lord God of all, our King; and they pray for our souls.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, aposticha item 3`},label:`martyrs`}],verses:{ref:`shared.weekday_aposticha_verses.sets.standard_matins`}},aposticha_theotokion:{text:`Without seed thou didst conceive by the Holy Spirit; we glorify thee and sing thy praises: Rejoice, O most holy Virgin!`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Matins, aposticha Glory/Both-now closer`},type:`theotokion`},closing_rubric:`Then, “It is good to give thanks ...,” Trisagion ..., Our Father ..., Troparia.`},wed:{sessionals:[{rubric:`st After the 1 chanting of the Psalter, the Sessional Hymns of the holy and precious Cross, in Tone III:`,spec_mel:null,items:[{text:`The Cross was planted in the earth yet touched the heavens, not because it reached the full stature of a tree, but because thereon Thou didst fulfill all things. Glory be to Thee, O Lord!`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, sessional set 1, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Thou wast uplifted upon the cypress, the pine and the cedar, O Lamb of God, that Thou mightest save those who worship Thy voluntary crucifixion with faith. Glory be to Thee, O Christ God!`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, sessional set 1, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`}],verses:[{text:`Exalt ye the Lord our God, and worship the footstool of His feet; * for He is holy.`,tier:2,src:{file:`3-4.pdf`,locus:`Wednesday Matins, sessional set 1 verse 1`}}],closer:{text:`Having obtained the Cross of thy Son as a staff of strength, O Theotokos, therewith we cast down the arrogance of the enemy, and with love unceasingly magnify thee.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, sessional set 1 closer`},type:`stavrotheotokion`,sourceLabel:`Stavrotheotokion`}},{rubric:`After the 2nd chanting of the Psalter, the Sessional Hymns, in Tone III:`,spec_mel:`Awed by the beauty of thy virginity ...`,items:[{text:`O Lord Who wast buffeted for the race of mankind, yet wast not stirred to wrath, free our life from corruption, and save us.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, sessional set 2, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Beholding Thine infinite authority and voluntary crucifixion, the angelic armies marveled: How is He who is invisible wounded in the flesh, desiring to deliver mankind from corruption? Wherefore, we cry out to Thee as the Bestower of life: Glory to Thy loving-kindness, O Christ!`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, sessional set 2, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Arraying yourselves in the full armor of Christ, and wielding the sword of faith, as martyrs ye hewed down hordes of the enemy; for, in hope of life, ye earnestly endured all the threats and wounds of the tyrants of old. Wherefore, ye have received crowns, O stouthearted martyrs of Christ.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, sessional set 2, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`}],verses:[{text:`God is our King before the ages, * He hath wrought salvation in the midst of the earth.`,tier:2,src:{file:`3-4.pdf`,locus:`Wednesday Matins, sessional set 2 verse 1`}},{text:`Wondrous is God in His saints, * the God of Israel.`,tier:2,src:{file:`3-4.pdf`,locus:`Wednesday Matins, sessional set 2 verse 2`}}],closer:{text:`Thy pure unwedded Mother, O Christ, upon seeing Thee hanging dead upon the Cross, said, weeping maternally: “How hath the iniquitous and thankless council of the Jews repaid Thy many and great wonders, O my Son, Thou Who hast filled them with Thy gifts? I hymn Thy divine condescension!”`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, sessional set 2 closer`},type:`stavrotheotokion`,sourceLabel:`Stavrotheotokion`}},{rubric:`After the 3rd chanting of the Psalter, the Sessional Hymns, in Tone III:`,spec_mel:`Awed by the beauty of thy virginity ...`,items:[{text:`Accepting crucifixion and death, O Christ our Savior, Thou didst pour forth immortal life upon us and freed the world from corruption. Wherefore, O Bestower of life Who lovest mankind, we glorify Thy salvific sufferings, whereby all of us who possess Thy Cross as peace and an invincible weapon, are saved.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, sessional set 3, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`Thou didst endure the infamy of the Cross, O Master Who dost transcend all creation, that Thou mightest honor me who before was in grievous dishonor. And Thou wast pierced in Thy side by a spear, O Long-suffering One, desiring to deliver me, Thy creature, from corruption. I hymn Thy great tender compassion and goodness, O Lover of mankind!`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, sessional set 3, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:3}],label:`plain`}],verses:[],closer:{text:`When the pure Virgin, Thine immaculate Mother, who knew not wedlock, beheld Thee uplifted upon the Tree, O Master, she cried aloud: “Woe is me, O my most sweet Son! How hath the most iniquitous council condemned Thee, the Creator and Master of all, to the Tree? I hymn Thine utter goodness!”`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, sessional set 3 closer`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],type:`stavrotheotokion`,sourceLabel:`Stavrotheotokion`}}],canons:[{title:`Canon of the precious and life-creating Cross, the acrostic whereof is “By Thy pangs Thou hast brought an end to the pangs of men,” the composition of Joseph, in Tone III`,heading_rubric:`Canon of the precious and life-creating Cross, the acrostic whereof is “By Thy pangs Thou hast brought an end to the pangs of men,” the composition of Joseph, in Tone III:`,odes:{1:{irmos:{text:`He who of old gathered the waters * into one by His divine decree, * divided the sea for the people of Israel. * For He is our God and supremely glorious, * to Him alone let us sing, for He hath been glorified.`,tier:2,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 1 irmos`}},items:[{text:`Thou didst cause the greatly painful passions to cease, O Word, and didst save mankind, whom the adversary wounded of old, yet who piously worship Thine ineffable dispensation.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 1, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`He who by deceit bound us through the violation of the commandment in paradise is bound by the unbreakable bonds wherewith Thou wast bound, having become incarnate of Thine own will, O Lord and Lover of mankind, loosing our transgressions.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 1, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Seeing creation unfortunately overwhelmed by the deceptions of the demons, the passion-bearers of great renown revealed themselves to be calm harbors for the faithful, drowning all the power of the prideful one in the streams of their blood.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 1, item 3`},label:`martyrs`},{text:`The choirs of the martyrs, having radiantly joined the ranks on high, are ever illumined by the splendors of the uncreated Godhead, enlightening those on earth who with faith glorify His wonders.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 1, item 4`},label:`martyrs`},{text:`Thou wast revealed to be more exalted than the heavenly ranks, O most pure one, who on earth hast given birth to God the Word, Who in His goodness hath led us up to the heavens by His sufferings and precious Cross.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 1, item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},3:{irmos:{text:`O Most High, Ruler of all, * who out of nothing hath established all things, * fashioned by Thy Word, * perfected by the Spirit, * confirm me in Thy love.`,tier:2,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 3 irmos`}},items:[{text:`By the Tree the assembly of the Jews slayed Thee, Who in the essence of Thy divinity art dispassionate, yet in Thy goodness became subject to suffering in the flesh, rendering us immortal.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 3, item 1`},label:`plain`},{text:`O Word Who suspended the earth upon the waters, of Thine own will Thou wast suspended upon the Tree, leading up to the heavens me who have fallen into the pit of evil.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 3, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Replete with wounds, O all-praised martyrs of Christ, ye stand before the Lord, receiving rewards from His most generous hand.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 3, item 3`},label:`martyrs`},{text:`With joyous soul the martyrs received wounds, bringing utter grief upon the serpent and filling the angelic choirs with joy.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 3, item 4`},label:`martyrs`},{text:`Beholding Christ uplifted upon the Cross, she who knew not wedlock said, weeping: “O Sun of glory, Thou hast set from before mine eyes, bringing light to those in darkness!”`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 3, item 5`},label:`theotokion`}]},4:{irmos:{text:`Thou hast shown us steadfast love, O Lord, * for Thou gavest Thine only-begotten Son over to death for our sake. * Wherefore with thanksgiving we cry unto Thee, * ‘Glory to Thy power, O Lord!’`,tier:2,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 4 irmos`}},items:[{text:`Beaten about the head with a reed, Thou didst endure mockery, O Master Who dost truly surpass all honor, that Thou mayest honor me who have been dishonored by disobedience, O Christ Who lovest mankind.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 4, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`As the King of truth Thou wast crowned with a crown of thorns as Thou didst desire, O Long-suffering One, and Thou didst uproot thorny sin. I hymn Thy sufferings, O Savior!`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 4, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`O martyrs, ye remained unbroken by the infliction of wounds, breaking the deception of the enemy and trampling underfoot him who boasted beyond measure yet wholly fadeth away in his mindlessness.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 4, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`Through your corruptible bodies ye acquired divine incorruption, by your sufferings steadfastly emulating the honored suffering of the Dispassionate One, O all-praised martyrs who have been reckoned with all the incorporeal ones.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 4, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`Once, the prophet beheld thee, O maiden, as the scroll whereon the finger of the Father inscribed the incarnate Word, Who with the spear hath rent asunder the record of our forefather’s sin, O most pure one.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 4, item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`theotokion`}]},5:{irmos:{text:`The Invisible One hath appeared on earth, * and the Unapproachable One hath willingly dwelt among mankind; * and, rising early at dawn, we hymn Thee, * O Lover of mankind.`,tier:2,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 5 irmos`}},items:[{text:`Thou wast uplifted upon the Tree like a lamb, O good One, offering Thyself to the Father as a sacrifice for us, O Almighty, and thereby abolishing idolatrous sacrifice.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 5, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`Pierced in the side with a spear, O Bestower of life, Thou pourest forth two streams of salvation upon those who declare Thee to be one of the Trinity, yet having two natures.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 5, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Through faith finding Thee to be a mighty fortress and unshakable rock, O Jesus, the mighty passion-bearers built themselves up as priceless stones.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 5, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`Strengthened by the power of God through faith, ye made war upon all the cruel power of the deceiver, O passion-bearing martyrs, and have been crowned with splendor.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 5, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`In that thou hast given birth unto Christ without corruption, thou hast refashioned our nature, which of old had become corrupt through disobedience, O most holy Lady, thou intercessor for our souls.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 5, item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},6:{irmos:{text:`The uttermost depths of sin have surrounded me, * and my spirit perisheth, * but do Thou, O Master, stretch forth Thy lofty arm * and like Peter O Helmsman, * do Thou save me.`,tier:2,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 6 irmos`}},items:[{text:`The lying serpent, who deceived me with the fruit of falsehood, caused me to be expelled from Eden; but Christ, having been willingly raised up upon the Tree hath restored mine ancient access thereto.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 6, item 1`},label:`plain`},{text:`By Thy wounded side, O Lord our Benefactor, he who wounded us was wounded and remained unhealed; but we, the faithful, have been healed by the wounds whereby Thou wast willingly wounded.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 6, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O most wise warriors of Christ, in the midst of the fire ye showed yourselves to be like roasted lambs, offered as a banquet to the God and King of all, inheriting ineffable gladness.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 6, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`Drawing healing forth from inexhaustible treasuries, ye pour it forth in rivers, O passion-bearers; and causing the harm of the passions to dry up, ye give drink to the assemblies of the faithful.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 6, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`Beholding the death of the Word Who was incarnate from thy blood, O all-immaculate one, thou didst cry out as a mother and magnify Him Who is the Cause of life, O Virgin Lady.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 6, item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`theotokion`}]},7:{irmos:{text:`Of old the three children did not worship the golden image, * of the Persian idol, * but chanted in the midst of the furnace: * O God of our fathers, blessed art Thou!`,tier:2,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 7 irmos`}},items:[{text:`By Thy pangs Thou didst cause our pangs to cease, O Lover of mankind, and thou hast now brought to the life devoid of pain those who piously worship Thine honored sufferings, O God of all.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 7, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`When creation saw Thee crucified, O Christ, it quaked and trembled: the earth shook, the rocks split asunder, and the sun in its transit hid its light.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 7, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Submitting to the laws of Christ, the martyrs rejected the enticements of the iniquitous and, suffering in the midst of the tribunal, received crowns of glory.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 7, item 3`},label:`martyrs`},{text:`Possessed of a will hotter than fire, ye were not consumed by the fire, O crowned passion-bearers of the Lord, crying aloud: Blessed art Thou, O God!`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 7, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`martyrs`},{text:`Seeing Christ, to Whom thou hast given birth, lifted up upon the Cross, O most pure one, thou didst stand, crying out: “Show me not to be childless, whom Thou didst keep pure even after birthgiving!”`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 7, item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},8:{irmos:{text:`The Babylonian furnace burnt not the children, * neither did the fire of the Godhead consume the Virgin, * wherefore with the faithful children we cry aloud: * 'Bless ye the Lord, all ye works of the Lord'.`,tier:2,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 8 irmos`}},items:[{text:`When Thou wast crucified, paradise was opened again, and the sword which was wielded against us was withdrawn, putting to shame the spear which pierced Thy holy side, O greatly merciful Christ.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 8, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`The adversary was wounded by Thy spear and fell, and fallen Adam is returned to life, crying out to Thee Who wast willingly slain, O Christ: I glorify Thee Who givest blessings, O my greatly merciful God!`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 8, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`The world is illumined by your contests, O spiritual athletes, and by your prowess and countless miracles, is delivered from the darkness of pain, crying out with faith: Bless the Lord, O ye works of the Lord!`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 8, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`martyrs`},{text:`He who of old boasted that he would destroy the earth and the sea is seen lying in humiliation beneath your feet, O saints; and with His life- bearing right hand Christ adorneth you with imperishable crowns, O ever-glorious ones.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 8, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`martyrs`},{text:`O most pure one, thou hast given birth in time unto Him Who transcendeth time, Who by His bonds freeth first-formed Adam from the bonds of time, and bindeth him to Himself with the bonds of His sweet love.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 8, item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},9:{irmos:{text:`Unto her who was prefigured on Sinai in the bush and the flame * before Moses the lawgiver, * she who conceived the fire of God within her womb without being consumed, * the most radiant and inextinguishable lamp, * the very Theotokos, thee do we honor and magnify with hymns.`,tier:2,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 9 irmos`}},items:[{text:`That Thou mightest find the coin which Thou hadst lost, O good Christ, Thou didst set Thy flesh afire on the Cross; making Thy heavenly hosts partakers of Thy joy, O Bestower of life, with them we hymn Thee as our Benefactor, magnifying Thee in song.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 9, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`As Thou didst lift up Thy hands upon the Cross, O Christ, with Thy power Thy didst strengthen my hands, which before were weakened by many passions; fortifying my truly weak knees to run the divine race: Wherefore, I glorify Thee.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 9, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Burning with flame, through countless wounds Thy steadfast and wondrous spiritual athletes found Thee to be a dew of coolness; wherefore, rejoicing, they trod the path with desire for honors, unceasingly magnifying thee with hymns.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 9, item 3`},label:`martyrs`},{text:`The multitude of spiritual athletes, the choir of the saints, entreat Thee, O Christ, on behalf of the assembly of those who have greatly offended Thee. In the multitude of Thy mercy, O Compassionate One, cleanse us of the multitude of our iniquities, in that Thou lovest mankind.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 9, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`martyrs`},{text:`O Virgin, thou hast given birth to the Effulgence of the Father, Who beareth the guise of mortals. When the sun beheld Him lifted up upon the Cross, it dimmed its rays, unable to bear the sight, but the gloom of the madness of idolatry faded. Wherefore, with it we magnify thee.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 1, Ode 9, item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]}},acrostic:`By Thy pangs Thou hast brought an end to the pangs of men`,composer:`Joseph`},{title:`Another canon, of the most holy Theotokos, the acrostic whereof is “I offer a third hymn to the Theotokos,” in Tone III`,heading_rubric:`Another canon, of the most holy Theotokos, the acrostic whereof is “I offer a third hymn to the Theotokos,” in Tone III:`,odes:{1:{irmos:{text:`He who of old gathered the waters ...,`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 2, Ode 1 irmos (incipit device, §2.7)`},incipit_ref:`tone3.matins_weekday.wed.canons[0].odes.1.irmos`},items:[{text:`Thee whom the prophet Habbakuk foresaw in the Spirit as the mountain overshadowed, do I beseech: O most pure one, overshadow me who am pierced through by passions and am in the shadow of death, that I may be freed of the passions which assail me.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 2, Ode 1, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`,repeat:2},{text:`With the sprinkling of the divine streams which flow from the divine side of thy Son, wash clean the wounds of my heart, that, as is meet, I may magnify and glorify thee, the ever-blessed and most immaculate one.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 2, Ode 1, item 2`},label:`plain`},{text:`Thou hast given birth to the Word Who is the equal of the One Who begat Him, and hath made the essence of man divine. Entreat Him, O pure one, that He grant divine consolation unto me who am confused and weakened by the wiles of the enemy.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 2, Ode 1, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`}]},3:{irmos:{text:`O Most High, Ruler of all ...,`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 2, Ode 3 irmos (incipit device, §2.7)`},incipit_ref:`tone3.matins_weekday.wed.canons[0].odes.3.irmos`},items:[{text:`O all-holy one, who art merciful, beseech Him Who is rich in ineffable mercy and compassions, that He have pity on us who are oppressed.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 2, Ode 3, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`,repeat:2},{text:`O pure Virgin, who art the dwelling-place of the Creator of all, entreat the Comforter to abide within me, for I have become a den for soul-corrupting thieves.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 2, Ode 3, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`In that thou bearest in thine arms Him Who holdeth all things in His divine hand, O Theotokos, look upon me, and deliver me from mine unseemly inclination toward the passions.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 2, Ode 3, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`}]},4:{irmos:{text:`Thou hast shown us steadfast love ...,`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 2, Ode 4 irmos (incipit device, §2.7)`},incipit_ref:`tone3.matins_weekday.wed.canons[0].odes.4.irmos`},items:[{text:`As Thou didst endure wounds and slaughter, O only greatly merciful Christ, by the supplications of her who gave birth to Thee, heal my soul, which hath been wounded by the afflictions of the ravenous demons.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 2, Ode 4, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O Creator, my body is the creation of Thy hands, yet I have been broken by the malice of the serpent and the pleasures of life. Wherefore, by the divine supplications of her who gave birth to Thee, refashion me, O Christ,`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 2, Ode 4, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`In a manner transcending description, thou hast given birth to the Word Who hath released mankind from all irrationality. Him do thou earnestly beseech, that He free me who am held captive by irrational passions, O only Ever-virgin.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 2, Ode 4, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Thou dost ever pour forth healing upon us from thy hands, O thou who art wholly the tabernacle of Holiness, who art wholly filled with Light, and dost wholly exude the Myrrh of sweet savor, O most pure Bride of God.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 2, Ode 4, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`}]},5:{irmos:{text:`In a vision Isaiah saw upon a throne, * God lifted up on high * borne aloft by angels of glory; * and he cried: ‘Woe is me! * For I have foreseen God made flesh, * the Lord of the never-setting light * and the King of peace.’`,tier:2,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 2, Ode 5 irmos`}},items:[{text:`Transform the pangs of my flesh and the sickness of my soul, O Virgin; drive away the clouds of slothfulness, O cloud of the Light; and grant deliverance from evils unto me who petition and glorify thee with love.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 2, Ode 5, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`,repeat:2},{text:`Full of every sin, O Virgin, I now present thee as my mediatress and advocate before Him Who was born from thee. Be thou the surety and correction of life for me, and guidance to the ways of divine knowledge.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 2, Ode 5, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Sanctify my mind, illumine my soul, and cause it to share in divine glory; for, lo! I have been filled with evils and enslaved by all manner of pleasures, and I bear a defiled conscience.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 2, Ode 5, item 3`},label:`plain`}]},6:{irmos:{text:`O Lover of mankind, disdain not those * who have reached the end of the ages * and are assailed with destruction by the threefold billows of perils, * yet cry aloud: O Savior, save us, * as Thou didst save the prophet from the sea monster!`,tier:2,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 2, Ode 6 irmos`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}]},items:[{text:`Ever full of pride, I have surpassed the Pharisee in arrogance of mind, plunging headlong into the defiles of countless offenses. O only pure one, have pity on me who am brought grievously low.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 2, Ode 6, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`,repeat:2},{text:`O thou whose conceiving and birthgiving were most wondrous, show now thy mercies to be wondrous in me; for I have been conceived in iniquities and born a slave to pleasures.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 2, Ode 6, item 2`},label:`plain`},{text:`I cry out, weep and lament when I contemplate the dread judgment; for my deeds are evil. O Virgin Mother of God, who knewest not a man, intercede for me at the dreadful hour!`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 2, Ode 6, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`}]},7:{irmos:{text:`The three children in the furnace, prefiguring the Trinity: * trampled underfoot the threat of the fire * and cried aloud, chanting: * Blessed art Thou, O God of our fathers!`,tier:2,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 2, Ode 7 irmos`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]},items:[{text:`My works are of no avail for salvation, O Lady, for I heap sin upon sin, and evil upon evil. Wherefore, by thy prayers, O pure one, have pity and save me.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 2, Ode 7, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`,repeat:2},{text:`The trial is at hand, the judgment-seat is set forth in readiness. Prepare thyself, O my soul, and cry aloud: When Thou shalt sit in judgment, O Word, condemn me not, for the sake of the prayers of her who gave birth to Thee.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 2, Ode 7, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Harvesting the fruits of sin and bringing forth a barren soul, I have been slain; yet I cry unto thee: Show me to be fruitful, O thou who by thy Fruit hast destroyed corruption.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 2, Ode 7, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`}]},8:{irmos:{text:`United together in the unbearable fire, * yet not harmed by the flame, * the children, champions of godliness, sang a divine hymn: * O all ye works of the Lord, * bless ye the Lord and supremely exalt Him throughout all ages.`,tier:2,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 2, Ode 8 irmos`}},items:[{text:`As thou wast wholly beautiful and didst become close to the King of all, O Theotokos, with good works fill me who have lived in wickedness and slothfulness, and have come to the end of my life, that I may glorify thee throughout all ages.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 2, Ode 8, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`,repeat:2},{text:`As of old Thou didst most gloriously deliver the prophet from the belly of the whale, O Word of God, deliver also my soul, which hath stumbled headlong into the abyss of destruction, O Savior, having the Virgin, who gave Thee birth without knowing wedlock, praying to Thee.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 2, Ode 8, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`Those who do evil, finding me clothed in the beautiful raiment of divine birth, have stripped me of it, O Theotokos; but by repentance do thou array me in divine vesture by thy supplications, O Virgin.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 2, Ode 8, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`refrain: “More honorable than the cherubim ...,” and make prostrations.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 2, Ode 8, item 4`},label:`plain`}]},9:{irmos:{text:`In the shadow and the letter of the Law, * let us, the faithful, discern a figure: * every male child that openeth the womb * shall be sanctified to God. * Therefore we magnify the firstborn Word * and Son of the beginningless Father, * the firstborn Child of a Mother who hath not known a man.`,tier:2,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 2, Ode 9 irmos`}},items:[{text:`O incorrupt and immaculate Virgin, disdain me not who am corrupt of mind and depraved of soul and conscience, who am defiled by evil and appear stripped bare of all good deeds; but do thou adorn me with works of piety.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 2, Ode 9, item 1`},label:`plain`},{text:`I have been filled with evils, filled with thoughts which alienate me from Thee the Lover of mankind; wherefore, I groan and cry aloud: Accept me, the penitent, and by the prayers of her who gave birth to Thee, reject me not, O greatly merciful Benefactor.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 2, Ode 9, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`That I may be delivered by thy prayers from all wrath, the deadly passions, cruel Gehenna and fire, from unjust men and wicked enemies, O all-immaculate maiden, I have fled to thy protection and call upon thee for help.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 2, Ode 9, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`In that thou art the Mother of God, beseech the Lord God and King, that I, thy servant, who from my mother’s womb have set my hope on thee, may be delivered from every threat and wicked habit, O Lady.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, canon 2, Ode 9, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`}]}},acrostic:`I offer a third hymn to the Theotokos`}],magnificat_rubric:`We then chant the hymn of the Theotokos (the Magnificat), with the`,post_canon_rubric:`Then, “It is truly meet to bless thee ...,” and a prostration. Small litany, Exapostilarion, and the usual psalms. Small Doxology (Read), Litany: Let us complete ..., On the Aposticha, these Stichera of the precious Cross, in Tone III:`,aposticha:{rubric:`On the Aposticha, these Stichera of the precious Cross, in Tone III:`,items:[{text:`Coveting bliss, I was banished, suffering a great fall; yet Thou didst not despise me, O Master: for, assuming what is mine for my sake, Thou wast crucified and saved me, leading me into glory. O my Redeemer, glory be to Thee!`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, aposticha item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`On the mountain, lifting up his arms in the form of the Cross, Moses vanquished Amalek; and Thou, O Savior, stretched out upon the precious Cross, embraced me, saving me from slavery to the enemy, and didst give it to me as the sign of life, enabling me to escape the arrows of mine adversaries. Wherefore, O Word, I bow down before Thy precious Cross.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, aposticha item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`Having fought the good fight, even after death ye shine in the world like beacons, O holy martyrs; wherefore, possessed of boldness, entreat Christ to have mercy on our souls.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, aposticha item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`}],verses:{ref:`shared.weekday_aposticha_verses.sets.standard_matins`}},aposticha_theotokion:{text:`Beholding Thee hanging upon the Tree, O mine supremely good Christ, the all-immaculate one cried out, lamenting maternally: “O my most beloved Son, how hath the iniquitous council condemned Thee to the Tree?”`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Matins, aposticha Glory/Both-now closer`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],type:`stavrotheotokion`,sourceLabel:`Stavrotheotokion`},closing_rubric:`Then, “It is good to give thanks ...,” Trisagion ..., Our Father ..., Troparia.`},thu:{sessionals:[{rubric:`After the 1st chanting of the Psalter, the Sessional Hymns of the holy apostles, in Tone III:`,spec_mel:null,items:[{text:`Come ye all, and let us praise the apostles as helmsmen; for they abolished the delusion of the idols, led us up to the light of life, and taught us to believe in the Trinity. Wherefore, celebrating their honored memory today, O ye faithful, we glorify Christ our God.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, sessional set 1, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`In that Thou art almighty, O Lord, Thou didst make brilliant the memorial of Thine apostles, for Thou didst strengthen them to emulate Thy sufferings, and they manfully vanquished the power of the enemy; wherefore, they have received the grace of healing. By their prayers grant peace to Thy people, O Lover of mankind.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, sessional set 1, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`}],verses:[{text:`Their sound hath gone forth into all the earth, * and their words unto the end of the world.`,tier:2,src:{file:`3-5.pdf`,locus:`Thursday Matins, sessional set 1 verse 1`}}],closer:{text:`O Theotokos, thou didst mystically contain within thy womb the Unapproachable and Uncircumscribable One, Who is of the same essence as the beginningless Father; and we who glorify thine Offspring in the world have come to understand the Godhead of the Trinity to be single and uncommingled. Wherefore, in thanksgiving we cry out to thee: Rejoice, O joyous one!`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, sessional set 1 closer`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],type:`theotokion`}},{rubric:`After the 2nd chanting of the Psalter, the Sessional Hymns, in Tone III:`,spec_mel:null,items:[{text:`Ye irrigated all the earth with streams of the divine Word, O apostles, and grew the grain of faith, and filled the ends of the whole world therewith; for ye cut down all the tares. Wherefore, ye brought all to Christ God, baptizing them for the uncreated Trinity.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, sessional set 2, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Ye irrigated all the earth with streams ...,`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, sessional set 2, item 2 (incipit repeat, §2.7)`},label:`plain`,incipit_ref:`tone3.matins_weekday.thu.sessionals[1].items[0]`},{text:`O holy passion-bearers, entreat the merciful God, that He grant our souls remission of transgressions.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, sessional set 2, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`}],verses:[{text:`The heavens * shall confess Thy wonders, O Lord.`,tier:2,src:{file:`3-5.pdf`,locus:`Thursday Matins, sessional set 2 verse 1`}},{text:`Wondrous is God in His saints, * the God of Israel.`,tier:2,src:{file:`3-5.pdf`,locus:`Thursday Matins, sessional set 2 verse 2`}}],closer:{text:`The prophets preached, the apostles taught, * the martyrs confessed, and we believe, * that thou art truly the Theotokos; ** wherefore, we glorify thine ineffable birthgiving.`,tier:2,src:{file:`3-5.pdf`,locus:`Thursday Matins, sessional set 2 closer`},type:`theotokion`}},{rubric:`After the 3rd chanting of the Psalter, the Sessional Hymns, in Tone III:`,spec_mel:null,items:[{text:`In that Thou art full of loving-kindness, O Christ, Thou didst launch Thine apostles toward the ends of the earth like arrows keenly sharpened, to slay all ungodliness and evil vanity, and to plant the doctrines of salvation. At their supplications, O Compassionate One, grant peace to our souls.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, sessional set 3, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`Praising thee, the preacher of the Truth and most radiant beacon of the world, O Nicholas, we chant and cry aloud, praying with faith: As thou didst rescue the innocent from death, O holy one, so deliver us also from misfortunes, tribulations and all grievous affliction.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, sessional set 3, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`}],verses:[],closer:{text:`As thou hast maternal boldness before thy Son, O all-immaculate Lady, enliven my soul, which hath been slain by many offenses; for thou alone hast given birth, in a manner transcending understanding and comprehension, to the Word, Who with the Father and the Spirit is without beginning, and Who ever granteth life, incorruption and great mercy to the world.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, sessional set 3 closer`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],type:`theotokion`}}],canons:[{title:`Canon of the holy, glorious and all-famed apostles, the composition of`,heading_rubric:`Canon of the holy, glorious and all-famed apostles, the composition of`,odes:{1:{irmos:{text:`He who of old gathered the waters * into one by His divine decree, * divided the sea for the people of Israel. * For He is our God and supremely glorious, * to Him alone let us sing, for He hath been glorified.`,tier:2,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 1 irmos`}},items:[{text:`Come, let us bless the sacred apostles; the pillars of the Church, the foundations of the Faith, the bulwarks of piety who make steadfast all the faithful that we may be saved by their entreaties.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 1, item 1`},label:`plain`,repeat:2},{text:`Terrified, I, the prodigal, condemn myself even before the judgment, for I have amassed” countless evil deeds; wherefore, I pray Thee, O righteous Judge: Through the divine entreaties of Thine apostles save me, who am desperate.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 1, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O steadfast pillars of piety, set me aright who am ensnared by the deception of the enemy, for I lie upon the ground in affliction, and know not what to do to find remission for those things in which I have sinned.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 1, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`With the holy prophets, the apostles and martyrs, O pure one, earnestly entreat the Lord Who became incarnate of thee, that He mortify all our carnal passions and grant us life everlasting.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 1, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},3:{irmos:{text:`O Most High, Ruler of all, * who out of nothing hath established all things, * fashioned by Thy Word, * perfected by the Spirit, * confirm me in Thy love.`,tier:2,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 3 irmos`}},items:[{text:`O eye-witnesses of Christ, ye who have filled the ends of the earth with divine doctrine, fill my soul with virtuous works and good thoughts.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 3, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`,repeat:2},{text:`Deliver me, O disciples of Christ, from the many temptations of the wicked one, from all manner of tribulation, from all oppression and every evil circumstance.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 3, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Alas, O my wretched and lowly soul! Sinning often and angering God, how canst thou ask forgiveness for thy wickedness, since thou dost not cease doing it?`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 3, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O divine ladder which Jacob beheld, whereby God descended, lifting us up: Earnestly pray with the apostles, that He have pity on us.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 3, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},4:{irmos:{text:`Thou hast shown us steadfast love, O Lord, * for Thou gavest Thine only-begotten Son over to death for our sake. * Wherefore with thanksgiving we cry unto Thee, * ‘Glory to Thy power, O Lord!’`,tier:2,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 4 irmos`}},items:[{text:`Extending the word to the ends of the world, as lightning-bolts and rays of the never-setting Sun, O apostles, ye enlightened all, dispelling the gloom of ungodliness.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 4, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`,repeat:2},{text:`The sea of grievous sin overwhelms me, and the waves of unseemly thoughts batter my lowly soul. O Lord my Helmsman, save me by the supplications of Thy disciples!`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 4, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`I am filled with horror, contemplating Thy dread coming, O Master, for I have within me my conscience condemning me even before the trial, and my lack of sense, before the tormenting tortures,`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 4, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O Word of God Who wast born from the divine Virgin maiden, by her mediations and those of Thine apostles, deliver our souls from every evil circumstances and all want, O Savior.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 4, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`theotokion`}]},5:{irmos:{text:`The Invisible One hath appeared on earth, * and the Unapproachable One hath willingly dwelt among mankind; * and, rising early at dawn, we hymn Thee, * O Lover of mankind.`,tier:2,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 5 irmos`}},items:[{text:`Incarnate on earth, Thou didst make the disciples heavens declaring Thy glory, O Christ. Wherefore, for their sake, O Lord, have mercy on our souls.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 5, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`,repeat:2},{text:`Deliver Thy servants from the passions and all need, and from grievous circumstances, O Word, through the right acceptable supplications of Thine apostles.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 5, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Woe is me, O my passion-wracked soul! How shalt thou, who art fruitless, stand before the dread tribunal? Make haste and repent, producing the fruits of the virtues!`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 5, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Ever entreat as thy Son Him Who ineffably appeared on earth in the flesh through thy pure blood, O pure one, that He grant us cleansing.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 5, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},6:{irmos:{text:`The uttermost depths of sin have surrounded me, * and my spirit perisheth, * but do Thou, O Master, stretch forth Thy lofty arm * and like Peter O Helmsman, * do Thou save me.`,tier:2,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 6 irmos`}},items:[{text:`Pouring forth an abyss of spiritual wisdom, the company of the apostles dried up the stench of worldly mindedness, giving drink to the assemblies of the pious.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 6, item 1`},label:`plain`,repeat:2},{text:`Sigh and shed tears, O my lowly soul, and cry out to the Lord, saying: I have sinned against Thee, O Master! Cleanse me, O Compassionate One, by the entreaties of Thine most wise apostles!`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 6, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:3}],label:`plain`},{text:`Torrents of the passions have gushed forth and engulfed the house of my soul. But as ye are rivers of the Spirit, O apostles, restore me to life, who have been demolished,`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 6, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`With her who gave Thee birth, O Christ, the council of the apostles entreats Thee to send down cleansing and peace upon Thy servants, in that Thou art the easily reconciled God and Lover of mankind.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 6, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},7:{irmos:{text:`Of old the three children did not worship the golden image, * of the Persian idol, * but chanted in the midst of the furnace: * O God of our fathers, blessed art Thou!`,tier:2,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 7 irmos`}},items:[{text:`Christ, the Light of the world, showed you, O light-bearing apostles, to be the light which dispelleth the darkness of delusion, enlightening the thoughts of the faithful.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 7, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`,repeat:2},{text:`O divinely eloquent apostles, break ye the snares which the enemy hath laid for us, and make smooth the paths of repentance for us who have recourse unto you.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 7, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`As divine salt cleanse my soul, which hath been made foolish by the carnal passions, O divinely eloquent disciples of the Lord, imparting to it life through faith.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 7, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Enlighten me with goodly ideas, I beseech thee, O beauty of Jacob, praying now with the apostles unto Him Who was born of thy pure blood.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 7, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},8:{irmos:{text:`United together in the unbearable fire, * yet not harmed by the flame, * the children, champions of godliness, sang a divine hymn: * O all ye works of the Lord, * bless ye the Lord and supremely exalt Him throughout all ages.`,tier:2,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 8 irmos`}},items:[{text:`I have been wounded by the sword of the passions, and have injured my heart in mindlessness, the accomplisher of evil. Heal me, who am wholly at a loss, O glorious apostles, for ye are the physicians of men’s souls and bodies.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 8, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`,repeat:2},{text:`The divine sound of the preachers went forth into all the earth, teaching all to worship throughout the ages, the single Essence, the one Being of the Holy Trinity, the one true Dominion, the one Kingship.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 8, item 2`},label:`plain`},{text:`O Master, O Word Who knowest mine infirmity, slothfulness and evil- mindedness, convert me, who have sinned greatly and have wasted Thy divine long-suffering by remaining in my transgressions.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 8, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`O most pure Theotokos, thou divine tongs which ineffably received the divine Coal: Quench the burning embers of my passions with the dew of thy prayers and those of the most glorious and divine apostles.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 8, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},9:{irmos:{text:`In the shadow and the letter of the Law, * let us, the faithful, discern a figure: * every male child that openeth the womb * shall be sanctified to God. * Therefore we magnify the firstborn Word * and Son of the beginningless Father, * the firstborn Child of a Mother who hath not known a man.`,tier:2,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 9 irmos`}},items:[{text:`O Word of the beginningless Father, Who by the words of Thy disciples didst confirm the ends of the earth: By their supplications have pity on me who have fallen headlong into irrational passions and am overwhelmed by the delusion of the demons.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 9, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`,repeat:2},{text:`O my soul who panders to the onslaughts of the passions, offer supplication unto Him Who suffered for thy sake, that He may deliver thee from grievous circumstances, for the sacred disciples plainly pray for thee, having emulated the sufferings of His flesh.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 9, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O disciples of Christ, when ye sit with Him to judge the fate of the innocent, keep my soul from condemnation, though it hath been defiled by unseemly deeds, for ye are my good intercessors and the helpers of the world.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 9, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O pure Virgin, most pure Virgin, palace of Christ, most holy Virgin, who beyond cause and all telling hast given birth to God, the Holiest of the holy: With the holy apostles pray for us all.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 1, Ode 9, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]}}},{title:`Another canon, of the holy hierarch Nicholas, the wonderworker, the`,heading_rubric:`Another canon, of the holy hierarch Nicholas, the wonderworker, the`,odes:{1:{irmos:{text:`Let us sing to the Lord, who hath wrought marvelous wonders * in the Red Sea: * for in the deep waters He hath drowned our enemies * and saved Israel. * To Him alone let us sing, for He is glorified.`,tier:2,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 1 irmos`}},items:[{text:`Let all of us, who are ever engulfed by the waves of life, honor and lovingly bless Nicholas, the most radiant and inextinguishable beacon, the tower on earth, who beckons us to the divine harbor.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 1, item 1`},label:`plain`},{text:`Strengthened by the power of God, O all-blessed one, in mind thou didst acquire zeal for piety; wherefore, thou didst deliver those who were to be unjustly put to death. We therefore beseech thee: Deliver us from all unjust affliction, O Nicholas!`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 1, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`Thou didst offer supplications to the Lord in abundance, O father, that He deliver us from sins and the flame of everlasting torment, from perils and tribulations, in that He is good.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 1, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Together let us hymn the most pure Mary, the divine ark containing the Giver of the law Who, in the in effable depths of His divine tender compassion, taketh away all our iniquities.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 1, item 4`},label:`theotokion`}]},3:{irmos:{text:`O barren and infertile soul, * bring forth a crop of glorious fruit and joyously cry aloud: * I have been firmly established by Thee O God; * there is none holy and none more righteous than Thee, O Lord.`,tier:2,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 3 irmos`}},items:[{text:`Thou wast shown to be a sharpened sword of the Spirit, O wise father Nicholas, cutting down the evil tares of the heretics, and smoothing the saving paths of the virtues for the faithful.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 3, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Unto thee do we beseech, the wellspring pouring forth torrents of healings, O holy one: By thy supplications wash us clean of the defilement of all the passions, delivering us from misfortunes and tribulations.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 3, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Laying the enemy low by thy mighty prayer, O father Nicholas, through the invocation of thy holy prayers strengthen now our thoughts therein, for they are weakened by the assaults of the passions.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 3, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`The mind cannot comprehend the birth of thy wondrous Offspring, which passeth understanding, O all-immaculate Birthgiver of God; wherefore, I pray to thee: Ever grant my mind grace, that I may glorify thee.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 3, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},4:{irmos:{text:`Habakkuk foresaw the overshadowed mountain, * even thine immaculate womb, O pure one. * Wherefore he cried; God shall come forth from Thaeman, * and the Holy One from a mountain * densely overshadowed.`,tier:2,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 4 irmos`}},items:[{text:`Every one of the faithful ever setteth thee forth as a mediator before God, O Nicholas; wherefore, we beseech thee: Deliver us from grievous perils and falls into sin, O father.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 4, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`As thou dost possess the grace of the Lord, O wise one, ever pour living water upon the hearts of those oppressed by the burning heat of tribulations and the aridity of sins, and who should perish wretchedly, O all-blessed one.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 4, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`O all-blessed one, who once delivered those led forth unjustly to execution, save us now from the oppression of corrupting men, and from all the deception of the demons.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 4, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`In an excess of compassion thou hast ineffably given birth to the incarnate Word. Him do thou beseech, O most pure one, that He deliver all from the carnal passions and defilement, and from all the needs of life.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 4, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},5:{irmos:{text:`By Thine unwaning light, O Christ, * do Thou illumine my humble soul * and guide it in Thy fear * for Thy commandments are light.`,tier:2,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 5 irmos`}},items:[{text:`Standing before the pure Light and ever illumined with the rays emitted thereby, O father, ask that we obtain cleansing and peace.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 5, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O supremely good One, by the fervent prayers of Nicholas have pity on me who have angered Thee more than all others by mine insensitive mind.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 5, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`I who have wasted my life in despondency pray to thee, O father Nicholas: Raise my defiled mind up to repentance.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 5, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`As thou alone art the joy of the angels, O divinely joyous one, fill with joy my downcast mind, which is wallowing in slothfulness.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 5, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},6:{irmos:{text:`The abyss of the passions and a storm of adverse winds * have risen up against me. * But do Thou make haste, O Savior, * to save me, and deliver me from corruption, * as Thou didst deliver the prophet from the sea-monster.`,tier:2,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 6 irmos`}},items:[{text:`Having mortified thy members by abstinence, thou didst acquire the life which waxeth not old, wherein do thou cause us to share by thy supplications, O wise one, through the avoidance of wicked sin.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 6, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`With the mast and sails of thy sacred prayers, deliver us from the deep of many and varied perils and the abyss of sin, O wise and holy hierarch, steering us to the harbor of life.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 6, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Adorning the cathedra of Myra in Lycia thou wast shown to be the beauty of high priests. O holy hierarch, by thy supplication save us unharmed by the perils of the world!`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 6, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`In the loving-kindness of His mercy, the only God, the Word Who dwelt within thy womb, O pure Mother, dispelled the corruption which from of old dwelt within us.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 6, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},7:{irmos:{text:`The three children in the furnace, prefiguring the Trinity: * trampled underfoot the threat of the fire * and cried aloud, chanting: * Blessed art Thou, O God of our fathers!`,tier:2,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 7 irmos`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]},items:[{text:`As a true chief shepherd, O father Nicholas, with the cords of thy words thou didst strangle the mindless Arius, who of old was leading the people of the Lord to destruction.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 7, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Having passed thine most holy life in holiness, O father Nicholas, thou dwellest with the saints, sending sanctification and enlightenment upon those who piously call thee blessed.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 7, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O father Nicholas, we ever invoke thee as a ready deliverer and a fervent helper: Deliver us from the passions and the unexpected perils which beset us!`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 7, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O pure one who hast given birth to the Light: Enlighten me who have darkened by soul through negligence, lighting the lamp of my heart, that I may glorify thee with goodly diligence.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 7, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},8:{irmos:{text:`God is unceasingly glorified on high by the angels, * O ye heaven of heavens, * ye earth and mountains, ye plains and abysses, * and all the race of mankind, * with hymns as to the Creator and Redeemer, * bless ye, and supremely exalt Him throughout all ages.`,tier:2,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 8 irmos`}},items:[{text:`As thou wast meek, O venerable one, thou didst inherit the land of the meek; wherefore, I pray to thee with faith: By thy supplications still thou the threefold waves of the evil one, which ever batter me.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 8, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`As thou didst deliver the military commanders who were unjustly condemned to die, so deliver us from the oppression of wicked men and from every assault of the demons, praying to the Savior, O Nicholas.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 8, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Thou didst show us the straight path of salvation, O Nicholas. Guide us thereto who in this life traverse it by thy prayers, that together we may enter the gates of life.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 8, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`He Who was born from thee is my strength and my song, O most pure Virgin. Him do thou earnestly beseech, that He strengthen me who am weakened by the passions, that I may keep His saving commandments.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 8, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`},{text:`refrain: “More honorable than the cherubim ...,” and make prostrations.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 8, item 5`},label:`plain`}]},9:{irmos:{text:`Upon Mount Sinai Moses saw thee in the bush, * as one who didst conceive the fire of the Godhead within thy womb, * and yet remained unconsumed. * Daniel saw thee as a mountain not cut by the hand of man, * and Isaiah proclaimed thee as the Rod that blossomed forth * from the root of David.`,tier:2,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 9 irmos`}},items:[{text:`The world hath acquired thee as a divine bulwark and foundation, and a goodly refuge, for by thy mediations we are ever delivered from every temptation and oppression, O father Nicholas. Wherefore, in praise we bless thee with faith.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 9, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Beset by many evil circumstances, I flee to the broad expanse of thy fervent prayers, O all-blessed one. Cause the pain of my soul to cease, I cry to thee; still thou the waves of despair, and calm the turmoil of my mind.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 9, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`The Creator cometh to judge all the earth, and as one unprepared, wretch that I am, I am utterly terrified, considering the multitude of mine evils. O long- suffering Lord, have pity and save me through the divine prayers of Thy venerable Nicholas!`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 9, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O thou who hast given birth to the Light, thou hast been revealed to be mine enlightenment, dispelling the dark and cruel clouds of my soul, that by thy prayers I may become a child of the day, doing holy deeds, that in holiness I may bless thee in hymnody.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, canon 2, Ode 9, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]}}}],magnificat_rubric:`We then chant the hymn of the Theotokos (the Magnificat), with the`,post_canon_rubric:`Then, “It is truly meet to bless thee ...,” and a prostration. Small litany, Exapostilarion, and the usual psalms. Small Doxology (Read), Litany: Let us complete ..., On the Aposticha, these Stichera of the holy apostles, in Tone III:`,aposticha:{rubric:`On the Aposticha, these Stichera of the holy apostles, in Tone III:`,items:[{text:`Your sound went forth into all the earth, O holy apostles, destroying the delusion of the idols, preaching the knowledge of God. Behold, your struggle is good, O blessed ones; wherefore, we hymn and glorify your memory.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, aposticha item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`Having blamelessly kept the commandments of Christ, O holy apostles, ye freely received and freely give, healing the sufferings of our souls and bodies; wherefore, as ye possess boldness, entreat Him, that our souls may find mercy.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, aposticha item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Having fought the good fight, even after death ye shine forth like beacons in the world, O holy martyrs. As ye have boldness, entreat Christ, that our souls may find mercy.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, aposticha item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`}],verses:[{text:`We were filled in the morning with Thy mercy, O Lord, and we rejoiced and were glad. In all our days, let us be glad for the days wherein Thou didst humble us, for the years wherein we saw evils. And look upon Thy servants, and upon Thy works, * and do Thou guide their sons.`,tier:2,src:{file:`3-5.pdf`,locus:`Thursday Matins aposticha verse 1 — the NORMAL Matins verse: the tone-2 §9.13 anomaly does NOT recur in tone 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]},{text:`And let the brightness of the Lord our God. be upon us, and the works of our hands do Thou guide aright upon us, * yea, the work of our hands do Thou guide aright.`,tier:2,src:{file:`3-5.pdf`,locus:`Thursday Matins aposticha verse 2 — "our God. be upon us" stray period (sic-registered)`}}]},aposticha_theotokion:{text:`Without seed thou didst conceive by the Holy Spirit; we glorify thee and sing thy praises: Rejoice, O most holy Virgin!`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Matins, aposticha Glory/Both-now closer`},type:`theotokion`},closing_rubric:`Then, “It is good to give thanks ...,” Trisagion ..., Our Father ..., Troparia.`},fri:{sessionals:[{rubric:`After the 1st chanting of the Psalter, the Sessional Hymns of the holy and precious Cross, in Tone III:`,spec_mel:null,items:[{text:`The Cross was planted in the earth yet touched the heavens, not because it reached the full stature of a tree, but because thereon Thou didst fulfill all things. Glory be to Thee, O Lord!`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, sessional set 1, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O Thou Who didst consent to suffer the Cross and death, Thou didst endure them between two of Thy creatures; and when Thou wast well-pleased to have Thy body pierced by nails, O Savior, the sun hid its rays. Then, beholding this, the thief reverently hymned Thee on his cross: “Remember me, O Lord!”; and believing, he received paradise.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, sessional set 1, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:3}],label:`plain`}],verses:[{text:`Exalt ye the Lord our God, and worship the footstool of His feet; * for He is holy.`,tier:2,src:{file:`3-6.pdf`,locus:`Friday Matins, sessional set 1 verse 1`}}],closer:{text:`When the unblemished Ewe-lamb of the Word, the incorrupt Virgin Mother, beheld Him Who had sprung forth from her without pain hanging upon the Cross, she cried out, lamenting as befitteth a mother: “Woe is me, O my Child! How is it that Thou sufferest of Thine own will, desiring to deliver man from the disgrace of the passions?”`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, sessional set 1 closer`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],type:`stavrotheotokion`,sourceLabel:`Stavrotheotokion`}},{rubric:`After the 2nd chanting of the Psalter, the Sessional Hymns, in Tone III:`,spec_mel:null,items:[{text:`Thou wast uplifted upon the cypress, the pine and the cedar, O Lamb of God, that Thou mightest save those who worship Thy voluntary crucifixion with faith. Glory be to Thee, O Christ God!`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, sessional set 2, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`Beholding Thine infinite authority and voluntary crucifixion, the angelic armies marveled: How is He who is invisible wounded in the flesh, desiring to deliver mankind from corruption? Wherefore, we cry out to Thee as the Bestower of life: Glory to Thy loving-kindness, O Christ!`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, sessional set 2, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`The goodly courage of your endurance vanquished the wiles of the enemy, the author of evil, O all-famed martyrs; wherefore, ye have been deemed worthy of eternal blessedness. As ye are witnesses to the Truth, pray ye to the Lord, that He save the flock of Christ-loving people.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, sessional set 2, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`}],verses:[{text:`God is our King before the ages, * He hath wrought salvation in the midst of the earth.`,tier:2,src:{file:`3-6.pdf`,locus:`Friday Matins, sessional set 2 verse 1`}},{text:`Wondrous is God in His saints, * the God of Israel.`,tier:2,src:{file:`3-6.pdf`,locus:`Friday Matins, sessional set 2 verse 2`}}],closer:{text:`Thou didst willingly endure a violent death in crucifixion, O Compassionate One. And she who gaveth birth to Thee was wounded, beholding Thee. By her supplications, take pity and save the world, O supremely good Lord and only Lover of mankind, Who takest away the sins of the world.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, sessional set 2 closer`},type:`stavrotheotokion`,sourceLabel:`Stavrotheotokion`}},{rubric:`After the 3rd chanting of the Psalter, the Sessional Hymns, in Tone III:`,spec_mel:null,items:[{text:`In Thine ineffable loving-kindness, O Sinless One, Thou didst endure the Cross, an instrument of cursing, and didst free the first-created man from the primal curse. Wherefore, we worship Thine honored sufferings, glorifying Thy holy dispensation, which Thou alone, in the tender compassion of Thy mercy, hast fulfilled, saving Thy creation.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, sessional set 3, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Smitten on the cheek for the race of mankind, Thou wast not angered. Free Thou our life from corruption, O Lord, and have mercy on us, in that Thou lovest mankind.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, sessional set 3, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`}],verses:[],closer:{text:`Having obtained the Cross of thy Son as a staff of strength, O Theotokos, therewith we cast down the arrogance of the enemy, and with love unceasingly magnify thee.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, sessional set 3 closer`},type:`stavrotheotokion`,sourceLabel:`Stavrotheotokion`}}],canons:[{title:`Canon of the precious and life-creating Cross, the acrostic whereof is “The Cross is the boast and glory of the faithful,” the composition of Joseph, in Tone III`,heading_rubric:`Canon of the precious and life-creating Cross, the acrostic whereof is “The Cross is the boast and glory of the faithful,” the composition of Joseph, in Tone III:`,odes:{1:{irmos:{text:`The Sun once passed over dry land * in the midst of the deep. * For the water on both sides became firm as a wall * while the people traversed the sea on foot, * chanting in a manner pleasing to God: * Let us sing unto the Lord; * for gloriously hath he been glorified.`,tier:2,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 1 irmos`}},items:[{text:`Making the waves of the sea solid by the staff of Moses, Thou didst lead the people across, prefiguring Thy Cross, O Compassionate One, whereby Thou hast parted the water of falsehood and led over to the land of divine knowledge all who hymn Thy power with faith.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 1, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O Thou Who created the deep by Thy command, Who with strength didst cover Thy chambers with waters and suspend the earth upon the waters: Thou didst hang suspended upon the Cross, yet didst shake all creation; and established the hearts of all in the fear of Thee.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 1, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Ye became children by fellowship, O godly martyrs of Christ, and inhabitants and inheritors of the heavenly Sion, wherein ye wear crowns, crying out with splendor: Let us sing unto the Lord, for gloriously hath He been glorified!`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 1, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`Cruelly maimed, ye endured the severing of your hands and feet; and though ye were cast into the fire, ye in nowise denied Christ, the God of all, but cried out fervently: Let us sing unto the Lord, for gloriously hath He been glorified!`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 1, item 4`},label:`martyrs`},{text:`O most beauteous Virgin Lady, beholding Him to Whom thou hast given birth willingly lifted up upon the Tree, thou didst exclaim, weeping and crying out in pain: “O compassionate God of all, as Thou art the Lord of glory, how dost Thou suffer these things, O Master?”`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 1, item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`theotokion`}]},3:{irmos:{text:`O Lord, the firm foundation of those who put their trust in Thee, * do Thou establish the Church, * which Thou hast purchased * with thy precious blood.`,tier:2,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 3 irmos`}},items:[{text:`Possessing a single compound composition, O Word, Thou didst endure a most ignominious crucifixion. Grant Thou honor to those who honor Thee.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 3, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`The curse of mortal mankind was abolished when Thou, O Master, wast accursed and poured forth blessing through the Cross.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 3, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Having been wanderers throughout the earth, ye were truly shown to be citizens of heaven and fellow-heirs with Christ, O all-praised ones.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 3, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`Having acquired the Cross as a most mighty weapon, the martyrs utterly vanquished all the power of the destructive foe.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 3, item 4`},label:`martyrs`},{text:`O pure one who hast given birth unto God incarnate, Who of His own will wast nailed to the Cross: Thou wast preserved a virgin even after giving birth.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 3, item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},4:{irmos:{text:`Thou hast shown us steadfast love, O Lord, * for Thou gavest Thine only-begotten Son over to death for our sake. * Wherefore with thanksgiving we cry unto Thee, * ‘Glory to Thy power, O Lord!’`,tier:2,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 4 irmos`}},items:[{text:`As the new Adam, Thou alone didst set aright the fall of Adam when, as Thou didst will, Thy hands were nailed to the Cross and Thou wast beaten with the reed and didst taste of vinegar and gall, as One Who transcends the heights of Thy kingdom.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 4, item 1`},label:`plain`},{text:`O Word of God, the prophet foresaw Thee as a sheep and sacrifice, as a lamb who struggled not, neither cried out; for Thou didst willingly endure crucifixion, that Thou mightest deliver and save those who have sinned of their own will, O loving Lord.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 4, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`Having tilled their souls with the plough of faith, with patience the martyrs of Christ sowed the seed of torments and reaped in abundance the grain of martyrdom which feedeth the assemblies of the faithful; wherefore, they are ever glorified.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 4, item 3`},label:`martyrs`},{text:`Hemmed in by the oppression of unbearable torments, in the expectation of beautiful things the martyrs manifestly attained unto the broad expanse of the heavenly kingdom, that they might enlarge my mouth to hymn their contests unceasingly.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 4, item 4`},label:`martyrs`},{text:`The Virgin Mother, who like tongs, received the divine Coal, Who in nowise consumed her divine and seedless womb, but instead bedewed it, beholding Him suspended in the flesh of His own will upon the Tree, she glorified Him in song.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 4, item 5`},label:`theotokion`}]},5:{irmos:{text:`In a vision Isaiah saw upon a throne, * God lifted up on high * borne aloft by angels of glory; * and he cried: ‘Woe is me! * For I have foreseen God made flesh, * the Lord of the never-setting light * and the King of peace.’`,tier:2,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 5 irmos`}},items:[{text:`Falling asleep on the Tree, O Master, Thou didst grant peace unto me who am weighed down by the burden of transgressions; and having suffered reproach, O Word, Thou didst take away my reproach. I hymn Thy might and divine sufferings, O Jesus.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 5, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:3}],label:`plain`},{text:`Thou didst light Thy flesh on the Cross as it were a torch, and didst search for the lost coin, O Lover of mankind; and called all Thy friends, all Thy hosts, upon finding it. We hymn the might of Thy kingdom, O Christ!`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 5, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`The deceiver is seen lying dead and unmoving at the feet of the steadfast passion-bearers of Christ; while they are surely numbered with the angels, full of ineffable joy.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 5, item 3`},label:`martyrs`},{text:`Frozen with cold, with grievous torments and tribulations and many wounds, the saints truly passed over to the divine warmth of the heavenly kingdom, and ever show themselves to be fervent intercessors for the faithful.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 5, item 4`},label:`martyrs`},{text:`Seeing Him crucified on the Tree Who of old fashioned Eve from the rib of Adam, His side pierced by a spear, the most pure Virgin cried out maternally: “How dost Thou die, O my Son Who art deathless Life?”`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 5, item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},6:{irmos:{text:`The Elder, having seen with his eyes the salvation * that was to come unto the peoples from God, * cried aloud unto Thee: * ‘O Christ, Thou art my God.’`,tier:2,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 6 irmos`}},items:[{text:`Like a lamb Thou wast willingly slaughtered, O Christ, leading back to life him who of his own will was slain by the fruit of the tree`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 6, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`When Thou wast lifted up upon the Cross: the deception of the demons collapsed, and the multitude of the faithful were raised on high, hymning Thee, O Bestower of life.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 6, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Arrayed in robes woven of thine own blood, the martyrs stand now before the King of all, adorned with radiant crowns.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 6, item 3`},label:`martyrs`},{text:`The relics of the holy martyrs pour forth healing upon all who approach them, drowning the multitude of the passions.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 6, item 4`},label:`martyrs`},{text:`O maiden, the human mind is unable to comprehend the mystery of thy birth giving, which transcendeth nature; for in a manner transcending understanding thou hast given birth unto God.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 6, item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},7:{irmos:{text:`O Thou who in the midst of the fire * bedewed the children as they discoursed on things divine, * and Who didst take up Thy dwelling in the pure Virgin: * O Word of God Thee do we reverently praise chanting: * “O God of our fathers, blessed art Thou.”`,tier:2,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 7 irmos`}},items:[{text:`O Master Who art One of the Trinity, Thou wast lifted up upon the cedar, the pine and the cypress, raising up those who had fallen into the depths of many pleasures. O God of our fathers, blessed art Thou.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 7, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`By Thy precious blood Thou didst cleanse creation of the blood offered to vile demons, O Lord; and when Thou wast slaughtered like an innocent lamb, O Word of God, Thou didst abolish their abominable sacrifices. Glory be to Thy dominion!`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 7, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`The spiritual athletes stood before the torturers like immovable pillars, causing deception to quake, but making steadfast the hearts of the faithful, and chanting: O Lord God of our fathers, blessed art Thou!`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 7, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`Having acquired a will hotter than fire, O crowned passion- bearers of Christ, ye were not consumed by the fire, but cried aloud: O Lord God of our fathers, blessed art Thou!`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 7, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`martyrs`},{text:`O only pure one who gavest flesh to the Master Who was crucified, thy conceiving was incomparable and thy birthgiving ineffable; chanting to Him, we cry out: O Lord God of our fathers, blessed art Thou!`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 7, item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`theotokion`}]},8:{irmos:{text:`United together in the unbearable fire, * yet not harmed by the flame, * the children, champions of godliness, sang a divine hymn: * O all ye works of the Lord, * bless ye the Lord and supremely exalt Him throughout all ages.`,tier:2,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 8 irmos`}},items:[{text:`The disobedient and foolish people condemned Thee to death, Who in Thy proper and obedient character desired to be crucified, O Word, that Thou mightest give life to those deadened in spirit, and who hymn and supremely exalt Thee throughout the ages.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 8, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Stretching out Thy hands upon the Cross, O Master, Thou didst heal the hands of the first-created man, which stretched out unrestrainedly to pluck the fruit of the tree; and seeing Thee, the sun hid its rays in fear and all creation trembled.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 8, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`With the rays of their sacred struggles the passion-bearers dried up the streams of impiety and the outpourings of ungodliness, and poured forth springs of healings, which wash away the defilement of the passions and give drink in abundance to the hearts of the faithful.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 8, item 3`},label:`martyrs`},{text:`United in your honored sufferings and fulfilling the divine commandments, O passion-bearers, ye have become fellow citizens with the incorporeal ones, and have now been enrolled in the city on high. Beseech God on behalf of those who honor you throughout all ages.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 8, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`All of us, the faithful, call thee the golden jar and lampstand, the table and staff, the divine mountain and cloud, the palace of the King and fiery throne, the Theotokos who was kept a virgin even after giving birth.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 8, item 5`},label:`theotokion`}]},9:{irmos:{text:`In the shadow and the letter of the Law, * let us, the faithful, discern a figure: * every male child that openeth the womb * shall be sanctified to God. * Therefore we magnify the firstborn Word * and Son of the beginningless Father, * the firstborn Child of a Mother who hath not known a man.`,tier:2,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 9 irmos`}},items:[{text:`Nailed to the Cross, O Jesus Christ Who founded the whole earth upon nothing, in that Thou art good have pity and draw me forth, who by my wicked character have become stuck in the mire of sin, for by Thy shameful death Thou hast brought honor to me, O greatly Merciful One.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 9, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`God Who is invisible by nature, became visible and exalted in the flesh, that He might deliver the visible world from the invisible foe, wherefore O Christ, render those here below heavenly, who glorify the dominion of Thy great authority.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 9, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O all-glorious passion-bearers of the Savior, ye have been revealed to be a sacred army, chosen like the holy angels; a garden of paradise having Christ, the Tree of Life, in your midst; an honored regiment of the divinely adorned Church.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 9, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`Standing joyfully before the throne of the Master, O saints, be ye mindful of us who commemorate you on earth; and richly illumine us with His rays, that we may receive release from our debts.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 9, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`“Beholding Thy crucifixion, O my Son, the sun and the moon withdrew their light. How then hath the unbelieving assembly of the Jews not faded away, having given Thee, the Author of life, over to death?” the Theotokos cried out, whom we unceasingly magnify.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 1, Ode 9, item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]}},acrostic:`The Cross is the boast and glory of the faithful`,composer:`Joseph`},{title:`Another canon, of the most holy Theotokos, in Tone III`,heading_rubric:`Another canon, of the most holy Theotokos, in Tone III:`,odes:{1:{irmos:{text:`He who of old gathered the waters * into one by His divine decree, * divided the sea for the people of Israel. * For He is our God and supremely glorious, * to Him alone let us sing, for He hath been glorified.`,tier:2,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 1 irmos`}},items:[{text:`By thy divine supplications, O Virgin, grant me cleansing of transgressions; for thy supplication is powerful, O most pure one, and thou dost deliver those who honor thee from offenses, the passions, tribulations and evil circumstances.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 1, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`With the waters of thy prayers, O Virgin, bedew my lowly soul, which hath withered under the burning heat of my countless offenses and passions, that, having received divine coolness, I may in hymns magnify thee as my fervent intercessor.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 1, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Stretching forth the hand of thy loving-kindness, O pure Lady, draw up to the heights of repentance me who am wholly drowning in sins and am full of despair, and grant me a fountain of tears.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 1, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`As thou hast the boldness before thy Son to pray earnestly for us, O most pure one, by thy supplications tear apart the record of my sins and transgressions, for thee do we Christians have as a helper.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 1, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`}]},3:{irmos:{text:`O Most High, Ruler of all, * who out of nothing hath established all things, * fashioned by Thy Word, * perfected by the Spirit, * confirm me in Thy love.`,tier:2,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 3 irmos`}},items:[{text:`Quickly open unto me the compassion of thy loving kindness, I pray, O most pure Theotokos, and reveal thyself to me to be a fervent helper and salvation amid temptations.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 3, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Deliver me from every cruel tempest of sin which assails me, thy servant, O most pure one, and by thy supplications guide me to the harbor of salvation.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 3, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O pure Virgin Mother, save me from the filthy stench of my passions, which now surround my lowly soul and oppress it.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 3, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Grant me a torrent of tears, O good one, and therewith quench the furnace of my passions, and wash a way all the defilements of my soul, O Theotokos.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 3, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`}]},4:{irmos:{text:`Thou hast shown us steadfast love ...,`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 4 irmos (incipit device, §2.7)`},incipit_ref:`tone3.matins_weekday.fri.canons[0].odes.4.irmos`},items:[{text:`All my hope have I set on thee, O Lady, and falling down, I pray from the depths of my soul: Deliver me from deadly pain, and lead me up to the life of salvation, O thou who hast given birth unto Life.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 4, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`O pure Lady, mighty helper of the world: Cast me not away from thee, neither banish me in disgrace from thy presence, nor show me to be the object of the demons’ jubilation.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 4, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Wretch that I am, I am wholly stripped bare of godly works and am riddled with the sharp arrows of pleasures and wounded; wherefore, I cry to thee, O Lady: Save me, O most pure one!`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 4, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`The waters of unseemly deeds have flooded my wretched soul, O pure one, and, stuck fast in thoughts of clay, I cry unto thee in pain: O Lady, disdain not me, thy servant!`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 4, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`}]},5:{irmos:{text:`In a vision Isaiah saw upon a throne ...,`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 5 irmos (incipit device, §2.7)`},incipit_ref:`tone3.matins_weekday.fri.canons[0].odes.5.irmos`},items:[{text:`O Virgin, thou art the divine vine, which produced the beauteous cluster of grapes Who giveth divine drink unto men’s souls: Deliver my soul from the draught of bitterness, the drunkenness of passions and pleasures, and everlasting fire.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 5, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O most pure Bride of God, out of the mire of sins pull me who have fallen into the mud of the passions; and having cleansed me of the defilements of the passions with the streams of thy prayers, clothe me in the splendid robe of salvation.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 5, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O pure Virgin, who hast given peace to the world and salvation to all, in that with fear and love, thou hast given birth to divine Peace; Christ the Savior, bring an end to the present aggression of the passions of my soul and body.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 5, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`In thy tender compassion heal my soul, which is sick from sin, O most pure one, and, guiding me grant that in humility I may ever do the commandments of thy Son, that I may receive His goodness.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 5, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`}]},6:{irmos:{text:`The uttermost depths of sin have surrounded me, * and my spirit perisheth, * but do Thou, O Master, stretch forth Thy lofty arm * and like Peter O Helmsman, * do Thou save me.`,tier:2,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 6 irmos`}},items:[{text:`In that thou art good, O most pure one, grant deliverance from transgressions unto me, thy servant, who with faith asks for thine aid; and rescue me from the coming judgment.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 6, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O Lady, Mother of the Redeemer, stand before me at the hour of my departure, when l am tested by the spirits of the air concerning those things I committed with an irrational mind.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 6, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Wholly wretched have I been revealed to be, ever beset by impurities; and seeing death now speedily overtaking me, I cry out to thee: O Theotokos, help me!`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 6, item 3`},label:`plain`},{text:`Waves of passionate thoughts ever batter me, O most pure one, and the tempest of evil spirits cause me to flounder; but moor me firmly to the rock of dispassion.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 6, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`}]},7:{irmos:{text:`As of old Thou didst bedew * the three pious children in the Chaldean flames, * so also with the radiant fire of Thy divinity * illumine us who cry to Thee, * ‘Blessed art Thou, O God of our fathers!’`,tier:2,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 7 irmos`}},items:[{text:`Unto thee, the pure and immaculate Mother of God do I pray, for I am defiled in body and soul and sullied by unclean acts; and I have placed my hope in thy mercy. O most pure Lady, have pity on me!`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 7, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`The multitude of my transgressions and the experience of evils sorely afflict and perplex me, and drag me into the depths of despair. O most pure Lady, save me who am perishing and cruelly drowning!`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 7, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O good one, have mercy on my soul, which hath been brought low by wicked acts; guide me to the path of repentance, direct me in doing the will of thy Son, and deliver me from torments.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 7, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`In the multitude of the goodness of thy compassions, O good one, overlook the multitude of our sins, and be thou speedily reconciled with those who cry out unceasingly: Blessed is the Fruit of thy womb, O most pure one!`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 7, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`}]},8:{irmos:{text:`In His divine power the Lord descended into the flames * and was seen walking with the Children of the Hebrews: * O ye priests, bless and supremely exalt Him throughout all ages.`,tier:2,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 8 irmos`}},items:[{text:`Having passed through the bitterness of pleasures and all the bodily senses, I have sullied my soul in an unseemly manner and dragged it toward death. O Sovereign Lady of the world, be thou my salvation!`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 8, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Unto thee have I committed my heart, soul and body, O Lady, for I have no other hope than thee, through whom I receive mercy; wherefore, grant me thy rich goodness.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 8, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`The serpent hath filled me with his venom and hath cruelly slain my wretched soul with carnal pleasure; but restore it to life with the salve of thy prayers, O pure one.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 8, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`The cruel night of transgressions lay heavily upon me, O holy Lady, for I have no lamp to shed light upon my soul with the oil of good works; wherefore, I shall find myself turned away from the bridal-chamber of the Most High.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 8, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`refrain: “More honorable than the cherubim ...,” and make prostrations.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 8, item 5`},label:`plain`}]},9:{irmos:{text:`We magnify thee, the unburnt bush, * the holy Virgin, * and the Mother of the Light, * the Theotokos, the hope of us all.`,tier:2,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 9 irmos`}},items:[{text:`Having cleansed my mind of the defilement of passionate thoughts, O pure one, clothe me in the splendid robe of dispassion.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 9, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Open unto me the divine gates of repentance, O Virgin, shutting the gates of my passions and pleasures, closing them by thy power.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 9, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Hearken unto the sound of my groaning and the voice of my weeping, O all- immaculate Virgin, and grant cleansing and salvation to my wretched soul.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 9, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`I am wholly in despair, wretch that I am, and am filled with consternation as I ponder my wicked deeds. Freely have pity on me, O Lady, and save me!`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, canon 2, Ode 9, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`}]}}}],magnificat_rubric:`We then chant the hymn of the Theotokos (the Magnificat), with the`,post_canon_rubric:`Then, “It is truly meet to bless thee ...,” and a prostration. Small litany, Exapostilarion, and the usual psalms. Small Doxology (Read), Litany: Let us complete ..., On the Aposticha, these Stichera of the precious Cross, in Tone III:`,aposticha:{rubric:`On the Aposticha, these Stichera of the precious Cross, in Tone III:`,items:[{text:`The tree of disobedience brought forth death upon the world; but the Tree of the Cross brought forth life and incorruption. Wherefore, we worship the crucified Lord, crying: Let the light of Thy countenance be signed upon us!`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, aposticha item 1`},label:`plain`},{text:`Coveting bliss, I was banished, undergoing a great fall; yet Thou didst not despise me, O Master: for, assuming what is mine for my sake, Thou wast crucified and saved me, leading me into glory. O my Redeemer, glory be to Thee!`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, aposticha item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2},{from:`U+041C М (Cyrillic)`,to:`M`,count:1}],label:`plain`},{text:`Come, all ye people, let us honor the memory of the holy passion-bearers, for, having become a spectacle for angels and men, they received crowns of victory from Christ, and they pray on behalf of our souls.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, aposticha item 3`},label:`martyrs`}],verses:[{text:`We were filled in the morning with Thy mercy, O Lord, and we rejoiced and were glad. In all our days, let us be glad for the days wherein Thou didst humble us, for the years wherein we saw evils. And look upon Thy servants, and upon Thy works, * and do Thou guide their sons.`,tier:2,src:{file:`3-6.pdf`,locus:`Friday Matins aposticha verse 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]},{text:`And let the brightness of the Lord our God be upon us, and the works of our hand do Thou guide aright upon us, * yea, the work of our hands do Thou guide aright.`,tier:2,src:{file:`3-6.pdf`,locus:`Friday Matins aposticha verse 2 — "works of our hand" (singular; §5 divergence; sic-registered)`}}]},aposticha_theotokion:{text:`The all-immaculate one, beholding Him Who was born from her hanging upon the Tree, exclaimed, crying aloud: “O my sweet Child, whither hath gone the luminous beauty of Thee Who didst create the race of mankind?”`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Matins, aposticha Glory/Both-now closer`},type:`stavrotheotokion`,sourceLabel:`Stavrotheotokion`},closing_rubric:`Then, “It is good to give thanks ...,” Trisagion ..., Our Father ..., Troparia.`},sat:{sessionals:[{rubric:`After the 1st chanting of the Psalter, the Sessional Hymns of the holy martyrs, in Tone III:`,spec_mel:null,items:[{text:`Your goodly endurance, O all-praised passion-bearers, vanquished the wiles of the enemy, the author of all evil; wherefore ye were deemed worthy of eternal blessedness. Intercede, then with the Lord, that He save the flock of Christ-loving people, in that ye are witnesses to the Truth.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, sessional set 1, item 1`},label:`plain`},{text:`Through your faith ye shine like most radiant beacons, O physicians of the infirm, and all-famed passion-bearers. Ye were undaunted by the torments of the torturers, and cast down the ungodliness of idolatry, having the true Cross as an invincible trophy.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, sessional set 1, item 2`},label:`plain`}],verses:[{text:`Wondrous is God in His saints, * the God of Israel.`,tier:2,src:{file:`3-7.pdf`,locus:`Saturday Matins, sessional set 1 verse 1`}}],closer:{text:`We hymn thee who hast mediated the salvation of our race, * O Virgin Theotokos; * for thy Son and our God, * accepting suffering on the Cross in the flesh * He had received of thee, * hath delivered us from corruption, ** in that He is the Lover of mankind.`,tier:2,src:{file:`3-7.pdf`,locus:`Saturday Matins, sessional set 1 closer`},type:`theotokion`,sourceLabel:`Theotokion`}},{rubric:`After the 2nd chanting of the Psalter, the Sessional Hymns, in Tone III:`,spec_mel:null,items:[{text:`Arraying yourselves in the full armor of Christ, and wielding the sword of faith, as martyrs ye hewed down hordes of the enemy; for, in hope of life, ye earnestly endured all the threats and wounds of the tyrants of old. Wherefore, ye have received crowns, O stouthearted martyrs of Christ.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, sessional set 2, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O holy passion-bearers, entreat the merciful God, that He grant unto our souls, the remission of sins.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, sessional set 2, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`When at Thy word we stand before Thine impartial tribunal, O Lord our Savior, put not to shame those who believe on Thee; for we have all sinned and fallen away from Thee. Wherefore, we beseech Thee: In the mansions of Thy righteous, grant rest to those whom Thou hast taken from among us, for Thou alone art sinless, O Christ.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, sessional set 2, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`for_the_reposed`}],verses:[{text:`Wondrous is God in His saints, * the God of Israel.`,tier:2,src:{file:`3-7.pdf`,locus:`Saturday Matins, sessional set 2 verse 1`}},{text:`Blessed are they whom Thou hast chosen and taken to Thyself, O Lord. * Their memorial is unto generation and generation.`,tier:2,src:{file:`3-7.pdf`,locus:`Saturday Matins, sessional set 2 verse 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]}],closer:{text:`The prophets preached, the apostles taught, the martyrs confessed, and we believe, that thou art truly the Theotokos; wherefore, we magnify thine ineffable birthgiving.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, sessional set 2 closer`},type:`theotokion`}}],canons:[{title:`Canon of the holy martyrs, hierarchs, the venerable and the departed, the`,heading_rubric:`Canon of the holy martyrs, hierarchs, the venerable and the departed, the`,odes:{1:{irmos:{text:`Wondrous art Thou, O God, * Who gloriously workest wonders, * Who didst fashion the earth from the abyss, * and didst cover the chariots and saved the people who sang to Thee * as our King and God.`,tier:2,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 1 irmos`}},items:[{text:`Ye found the glory of martyrdom, O most wise spiritual athletes and passion- bearers, and bravely endured many and varied tortures; wherefore, ye are ever glorified.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 1, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Tending the flock of the Lord well with divine power, ye were revealed to possess a most exalted manner of life, O divine ministers, most wise initiates of the mysteries of the incarnate Word.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 1, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Having crucified yourselves to the world, ye rejected all carnal passions, O venerable ones, and, revealed to be vessels of the Spirit, by divine power ye destroyed the spirits of delusion.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 1, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Granting endless life and never-waning light unto those who with pious faith have passed from the earth at Thy command, O Compassionate One, grant rest unto them, in that Thou art good.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 1, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`for_the_reposed`},{text:`With the honored women who shone forth in fasting and cast down the enemy by their sufferings, do we with pious demeanor honor thee, O most pure one, as her who gave birth unto God in the flesh.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 1, item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},3:{irmos:{text:`O barren and infertile soul, * bring forth a crop of glorious fruit and joyously cry aloud: * I have been firmly established by Thee O God; * there is none holy and none more righteous than Thee, O Lord.`,tier:2,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 3 irmos`}},items:[{text:`Strengthened by the power of God, O glorious martyrs, ye utterly destroyed the pernicious power of the enemy who is mighty in evil, and ye have received divine crowns of victory.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 3, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O Christ our Master, Who revealed the venerable as victors over the enemy, and didst consecrate the holy hierarchs with Thy most holy anointing: By their supplications sanctify and enlighten those who hymn Thee.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 3, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`With all the prophets we praise the choir of the godly women who shone forth in fasting and suffered with faith, trampling down the greatly crafty enemy.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 3, item 3`},label:`plain`},{text:`Those whom Thou hast taken from among us by Thy divine will, O compassionate Christ, do Thou number with the saints through the prayers of Thy holy ones, overlooking the transgressions they committed in this life.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 3, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`for_the_reposed`},{text:`We who have been saved by thy holy birthgiving cry out to thee with faith the salutation of Gabriel, “Rejoice!”; and we pray: In thy prayers ask forgiveness for us all.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 3, item 5`},label:`theotokion`}]},4:{irmos:{text:`Habakkuk foresaw the overshadowed mountain, * even thine immaculate womb, O pure one. * Wherefore he cried; God shall come forth from Thaeman, * and the Holy One from a mountain * densely overshadowed.`,tier:2,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 4 irmos`}},items:[{text:`Slaughtered willingly like lambs, O wise spiritual athletes, ye brought yourselves like sheep to the Lamb, the Word of God, Who on the tree of the Cross was well-pleased to be slain for the race of mankind.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 4, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`With the venerable let us honor the right glorious chief hierarchs, who were lamps unto the faithful; for they dispelled the profound darkness of heresy and the passions, and with faith have passed over to the never-waning Light.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 4, item 2`},label:`plain`},{text:`With the beauty of their words the divinely eloquent prophets enlighten the souls of the faithful; and with the splendors of their struggles and the dawning of their miracles the God-bearing women illumine their hearts.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 4, item 3`},label:`plain`},{text:`Those who have departed this life do Thou reveal to be sharers in heavenly glory, O good Word of God, granting them deliverance from the transgressions they committed on earth in knowledge and in ignorance.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 4, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`for_the_reposed`},{text:`Let us hymn the all-hymned Mother of the Lord, the glory of the martyrs, the divine adornment of holy hierarchs and the venerable, the confirmation of the faithful, and the proclamation of the prophets.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 4, item 5`},label:`theotokion`}]},5:{irmos:{text:`By Thine unwaning light, O Christ, * do Thou illumine my humble soul * and guide it in Thy fear * for Thy commandments are light.`,tier:2,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 5 irmos`}},items:[{text:`Your stripes and wounds inflicted incurable wounds upon the enemy, but they now heal the wounds of all the faithful, O spiritual athletes of the Lord.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 5, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Let us hymn the multitude of the venerable, let us bless the holy hierarchs of Christ, and let us honor His prophets, who ever pray now on our behalf.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 5, item 2`},label:`plain`},{text:`Loving God Who became incarnate for our sake, the most glorious women, who with upright character suffered and fasted, abide now in the heavens.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 5, item 3`},label:`plain`},{text:`Amid the sustenance of paradise, in the land of the living, where Thy light shineth, O Christ, settle Thy faithful servants, whom Thou hast taken from the earth.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 5, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`for_the_reposed`},{text:`God became incarnate from thee, O most pure one, and hath now shown thee to be more exalted than the angels and higher than all creation; wherefore, we hymn thee, O Lady.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 5, item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`theotokion`}]},6:{irmos:{text:`O Lover of mankind, disdain not those * who have reached the end of the ages * and are assailed with destruction by the threefold billows of perils, * yet cry aloud: O Savior, save us, * as Thou didst save the prophet from the sea monster!`,tier:2,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 6 irmos`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}]},items:[{text:`Let the luminaries of the honored Church, the most sacred and all-glorious spiritual athletes of Christ, the Lamb and Shepherd, be honored with sacred hymns.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 6, item 1`},label:`plain`},{text:`The assembly of the venerable, who exalted God in humility, hath been exalted, and the multitude of the holy hierarchs hath been glorified in good works, glorifying the Holy Trinity.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 6, item 2`},label:`plain`},{text:`Full of courageous valor, the choir of sacred women hath wounded the iniquitous foe by showing forth divine miracles and by their perfect endurance of pangs.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 6, item 3`},label:`plain`},{text:`Those whom Thou hast taken from the earth in the faith, do Thou enroll in the councils of the saints and number in the bosom of the faithful Abraham, O Christ, that they may ever glorify Thy great loving-kindness.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 6, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`for_the_reposed`},{text:`O most pure one, thou art the boast of the martyrs, the prophets and the venerable, and the righteous of ages past; wherefore, with them we honor thee with joyful voices, O Theotokos.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 6, item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`theotokion`}]},7:{irmos:{text:`The three children in the furnace, prefiguring the Trinity: * trampled underfoot the threat of the fire * and cried aloud, chanting: * Blessed art Thou, O God of our fathers!`,tier:2,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 7 irmos`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]},items:[{text:`Standing in the midst of the fire, O most glorious passion-bearers of the Lord, ye received divine dew from heaven; and slain by tortures, ye rendered the greatly crafty foe dead.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 7, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O divine and holy hierarchs, as helmsmen of the ship of the Church of Christ ye kept it from foundering, truly escaping the evil waves of deception.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 7, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1},{from:`U+043E о (Cyrillic)`,to:`o`,count:1}],label:`plain`},{text:`O true ascetics who mortified the flesh with sacred struggles, ye have inherited the life of dispassion, which waxeth not old, chanting; Blessed art Thou, O Lord God of our fathers.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 7, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`Show not Thy faithful servants, whom Thou hast taken to Thyself, to be deserving of condemnation, O Word, but grant them rest in the radiance of Thy saints, that they may hymn Thy loving-kindness.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 7, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`for_the_reposed`},{text:`O all-immaculate one, thou art truly the glory of the martyrs and the venerable, the prophets and the holy women, and all the hierarchs who received sacred ordination; and with them we honor thee.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 7, item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},8:{irmos:{text:`God is unceasingly glorified on high by the angels, * O ye heaven of heavens, * ye earth and mountains, ye plains and abysses, * and all the race of mankind, * with hymns as to the Creator and Redeemer, * bless ye, and supremely exalt Him throughout all ages.`,tier:2,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 8 irmos`}},items:[{text:`Sorely beset by the endurance of wounds and the infliction of pangs, ye did not deny the true Life, O passion-bearers of the Lord, nor did ye offer worship to graven images, a wicked delusion.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 8, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O lamps of the honored virtues, set upon lamp-stands, ye illumine the souls of all, dispelling all darkness, O passion-bearers who work sacred deeds, who dwell with the celestial intelligences.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 8, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`Let the right laudable prophets, the company of the righteous and the right glorious multitude of all the reverent women, who pray to God the Savior on our behalf, be hymned as is meet`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 8, item 3`},label:`plain`},{text:`O Thou Who hast dominion over the living, the faithful whom Thou hast taken from the earth do Thou settle with the saints in the light of Thy countenance, O Savior, granting them forgiveness of transgressions in Thy great loving-kindness.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 8, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`for_the_reposed`},{text:`As is meet, let the greatly hymned Virgin, the proclamation of the prophets, the adornment of holy hierarchs, passion-bearers and the venerable, and the joy of holy women, be hymned throughout the ages.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 8, item 5`},label:`theotokion`}]},9:{irmos:{text:`Upon Mount Sinai Moses saw thee in the bush, * as one who didst conceive the fire of the Godhead within thy womb, * and yet remained unconsumed. * Daniel saw thee as a mountain not cut by the hand of man, * and Isaiah proclaimed thee as the Rod that blossomed forth * from the root of David.`,tier:2,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 9 irmos`}},items:[{text:`Ye brought yourselves like lambs to Him Who was slain for our sake, and filled the divine choirs of the angels with joy, O passion-bearers of Christ; wherefore, by your prayers make all steadfast and deliver them from the harmful delusion of the enemy.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 9, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Possessed of the Word of life, like lamps ye enlightened men’s souls, O most sacred hierarchs of Christ who share in divine glory; for, having received the fire of the Spirit, O venerable ones, ye utterly consumed the passions and abolished the immolation of idolatrous sacrifices.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 9, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`Let us honor the holy prophets and the multitude of the venerable, who in their pure life shone forth before the law and under the law; and let us praise the choirs of holy women, and cry aloud: By their prayers, O Lord, save us all!`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 9, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Thy burial and resurrection became life for all; wherefore, with boldness we cry out to Thee: Grant rest with all the elect unto the faithful whom Thou hast taken to Thyself, forgiving them all their offenses, in that Thou art the supremely good God.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 9, item 4`},label:`for_the_reposed`},{text:`“Awesome is this place!” Jacob cried aloud when he beheld thee depicted in the true ladder, O Theotokos, thou glory of the martyrs, boast of the venerable, adornment of the angels and all the prophets, and salvation of the faithful.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 1, Ode 9, item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]}}},{title:`Another canon, of the departed, which we chant when there is no Menaion, the`,heading_rubric:`Another canon, of the departed, which we chant when there is no Menaion, the`,odes:{1:{irmos:{text:`Having clearly made the form of a Cross with the staff, * and thereby prepared a path, * Israel of old crossed the turbulent sea as though on dry land, * Wherefore, let us chant in praise to our wondrous God, * for He hath been glorified.`,tier:2,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 1 irmos`}},items:[{text:`O Christ Who by Thy burial didst slay death and cast down the tyranny of Hades, ascending into the heavens as our forerunner, with Thyself Thou didst raise up the choir of the passion-bearers. Grant rest now unto the souls of those who have passed over to Thee.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 1, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`,refrain:`Wondrous is God in His saints, the God of Israel.`},{text:`O Savior, Who hast strengthened the divine martyrs and by them annulled the power of delusion: By their supplications be Thou well-pleased to grant those who have reposed in Thee, immortality and a goodly inheritance.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 1, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1},{from:`U+041E О (Cyrillic), in refrain`,to:`O`,count:1}],label:`plain`,refrain:`Grant rest, O Lord, to the souls of Thy departed servants.`},{text:`When Thou wast slain, Thou didst pour forth Thy blood for Thy servants, in that Thou art compassionate, O Master, paying their ransom; wherefore, we beseech Thee, O Thou Who art full of loving-kindness, grant rest unto Thy servants who have passed over to Thee.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 1, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`glory`},{text:`Let us hymn the pure Theotokos, who gave birth unto God Who by His own death hath overthrown our death, and poured forth life which waxeth not old, and abiding blessedness.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 1, item 4`},label:`theotokion`}]},3:{irmos:{text:`O Most High, Ruler of all, * who out of nothing hath established all things, * fashioned by Thy Word, * perfected by the Spirit, * confirm me in Thy love.`,tier:2,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 3 irmos`}},items:[{text:`O Thou Who didst fashion me from earth and hast most splendidly restored me, a wretch returning to the earth, grant rest to the souls of the departed through the prayers of the martyrs.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 3, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1},{from:`U+043E о (Cyrillic)`,to:`o`,count:1}],label:`plain`,refrain:`Wondrous is God in His saints, the God of Israel.`},{text:`Entreated by the beatings and bonds, and stripes and wounds of the passion- bearing martyrs, O Compassionate One, number the souls of Thy servants in the habitations of the saints`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 3, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1},{from:`U+041E О (Cyrillic), in refrain`,to:`O`,count:1}],label:`plain`,refrain:`Grant rest, O Lord, to the souls of Thy departed servants.`},{text:`From Gehenna, fire and the abodes of gloom do Thou deliver Thy servants who have reposed in faith and hope, O Master and Lover of mankind.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 3, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`O most sacred and most pure Theotokos, thou art the Mother of the Creator Who destroyed the power of death and hath given us incorruption.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 3, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},4:{irmos:{text:`Thou hast shown us steadfast love, O Lord, * for Thou gavest Thine only-begotten Son over to death for our sake. * Wherefore with thanksgiving we cry unto Thee, * ‘Glory to Thy power, O Lord!’`,tier:2,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 4 irmos`}},items:[{text:`Mercifully making Thine abode in the tomb for our sake, O Master, as God Thou didst empty the graves; and having revealed the martyrs to be triumphant, grant that Thy departed servants may dwell in a place of ease.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 4, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`,refrain:`Wondrous is God in His saints, the God of Israel.`},{text:`O Master Who rejoicing, accepted the mighty feats of the spiritual athletes, the wounds and dismemberments they endured for Thee: Deliver from torment those whom Thou hast taken to Thyself.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 4, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1},{from:`U+041E О (Cyrillic), in refrain`,to:`O`,count:1}],label:`plain`,refrain:`Grant rest, O Lord, to the souls of Thy departed servants.`},{text:`O Thou Who holdest the balance of life in Thy hand, grant Thine endless life and incorrupt glory unto those who have passed on to Thee, breaking down the middle wall of partition.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 4, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`Thou wast truly shown to be true Mother and Virgin, O all- immaculate one, uniting a true conception and birthgiving to virginity; for thou hast given birth unto God Who hath broken the power of death.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 4, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},5:{irmos:{text:`I rise at dawn unto Thee, * the Creator of all, * surpassing all worldly understanding; * for Thy commandments are light, * wherein do Thou guide me.`,tier:2,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 5 irmos`}},items:[{text:`For the sake of the martyrs and by the supplications of the honorable spiritual athletes, O good One, Who art the Firstborn of the Church, number those who have departed from us with the righteous.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 5, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`,refrain:`Wondrous is God in His saints, the God of Israel.`},{text:`As deliverance from many transgressions Thou didst shed Thy most holy blood, O Christ; and now, by the supplications of Thy martyrs, O Savior, grant rest to those who have reposed in piety.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 5, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2},{from:`U+041E О (Cyrillic), in refrain`,to:`O`,count:1}],label:`plain`,refrain:`Grant rest, O Lord, to the souls of Thy departed servants.`},{text:`Unto the eternal place of Thy delights which pass understanding, O Word, guide the souls of the departed, and deem them worthy of the divine splendors of the saints.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 5, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`As is meet, we bless thee, the Virgin who in a manner past all telling conceived in her womb the infinite Word Who giveth life unto the dead.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 5, item 4`},label:`theotokion`}]},6:{irmos:{text:`Lead me up from corruption, O Lord my God! * cried Jonah unto Thee; * and I also cry aloud to Thee: * Deliver me from the abyss of my many evils, O Savior, * and guide me I pray, to Thy light!`,tier:2,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 6 irmos`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}]},items:[{text:`Through the supplications of the passion-bearers, O Christ, transform into joy the lamentation of those who have reposed in the Faith, magnificently girding them about with gladness, and guiding and directing them to Thy light.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 6, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`,refrain:`Wondrous is God in His saints, the God of Israel.`},{text:`In the multitude of Thy compassions, O Christ God, grant rest to the departed in the bosom of the patriarchs, where the radiant light of Thy countenance shines; and overlook all their transgressions.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 6, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1},{from:`U+041E О (Cyrillic), in refrain`,to:`O`,count:1}],label:`plain`,refrain:`Grant rest, O Lord, to the souls of Thy departed servants.`},{text:`O Christ, show forth as wondrous, the marvelous mercy of Thy love for mankind, upon those who have departed from here and are delivered from the cruelties of life; and fill them, with joy and meekness.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 6, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`We have been delivered from mortality, corruption and death by thy most glorious birthgiving, O Mother of God; for unto us thou didst give birth to the Source of incorruption, illumining the whole world with thy light.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 6, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},7:{irmos:{text:`As of old Thou didst bedew * the three pious children in the Chaldean flames, * so also with the radiant fire of Thy divinity * illumine us who cry to Thee, * ‘Blessed art Thou, O God of our fathers!’`,tier:2,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 7 irmos`}},items:[{text:`O Word of God, Who for all art the life-creating Cause and creative Power: Grant unto the souls of Thy departed servants the sustenance promised to the martyrs. Blessed art Thou, O God of our fathers!`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 7, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`,refrain:`Wondrous is God in His saints, the God of Israel.`},{text:`The glorious martyrs valiantly ignored their bodies as things corruptible, O Christ; and they now pray to Thee with boldness: Grant rest to the souls of Thy departed servants. O God of our fathers, blessed art Thou!`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 7, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2},{from:`U+041E О (Cyrillic), in refrain`,to:`O`,count:1}],label:`plain`,refrain:`Grant rest, O Lord, to the souls of Thy departed servants.`},{text:`With the Cross as a pen, for all the faithful Thou didst sign a writ of emancipation from sins. Grant now that the souls thou hast taken to Thyself may also share therein, and in gladness sing to Thee: O God of our fathers, blessed art Thou!`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 7, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`The Word of the Father, Who hath wrought all things by His will, as God hath restored human nature, which was buried by the passions. Blessed is the Fruit of thy womb, O most pure one!`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 7, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]},8:{irmos:{text:`Serving the living God in Babylon, * the children who took no pleasure in the sounding of the musical instruments, * patiently stood within the flames, * and sang a divine hymn saying: * 'Bless ye the Lord, all ye works of the Lord'.`,tier:2,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 8 irmos`}},items:[{text:`As the treasury of immortality, O Bestower of life, to the dead Thou didst proclaim incorruption, which Thou didst give to Thy martyrs, who with piety and faith chant unto Thee: Bless the Lord, all ye works of the Lord!`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 8, item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`,refrain:`Wondrous is God in His saints, the God of Israel.`},{text:`With spiritual wisdom and the endurance of tortures the mighty spiritual athletes paid no heed to their torments, and they entreat Christ to grant remission unto departed souls, crying: Bless the Lord, all ye works of the Lord!`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 8, item 2`},label:`plain`,homoglyph_log:[{from:`U+041E О (Cyrillic), in refrain`,to:`O`,count:1}],refrain:`Grant rest, O Lord, to the souls of Thy departed servants.`},{text:`Cleanse those who have departed unto Thee, O Good Savior, Who by the spear which pierced Thy side hast torn apart the record of sins and removed the middle wall of their transgressions; and be Thou well-pleased that, receiving it, they may chant unto Thee: Bless the Lord, all ye works of the Lord!`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 8, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`O pure Virgin, we know thee to be a noetic cloud for those burdened by the thirst of mortality, pouring forth the water of remission, imparting immortality unto all the dead, who ever cry out with faith: Bless the Lord, all ye works of the Lord!`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 8, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`},{text:`refrain: “More honorable than the cherubim ...,” and make prostrations.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 8, item 5`},label:`plain`}]},9:{irmos:{text:`Unto her who was prefigured on Sinai in the bush and the flame * before Moses the lawgiver, * she who conceived the fire of God within her womb without being consumed, * the most radiant and inextinguishable lamp, * the very Theotokos, thee do we honor and magnify with hymns.`,tier:2,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 9 irmos`}},items:[{text:`As the only good God and Lover of mankind, by the supplications of the martyrs grant that those who have passed over to Thee may dwell now in the land of the meek, granting them remission of sins, that we may unceasingly magnify Thee with hymns.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 9, item 1`},label:`plain`,refrain:`Wondrous is God in His saints, the God of Israel.`},{text:`O Christ, among Thy holy ones number those whom Thou hast taken to Thyself in the dwellings of the saints, in the bosom of Abraham, where the ineffable and divine light of Thy countenance shines, and everlasting joy truly abides forever.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 9, item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1},{from:`U+041E О (Cyrillic), in refrain`,to:`O`,count:1}],label:`plain`,refrain:`Grant rest, O Lord, to the souls of Thy departed servants.`},{text:`In a place of verdure, by restful waters, grant Thy blessed life, the unceasing sustenance of eternal good things, and true gladness, unto Thy servants, whom of Thy will Thou hast taken to Thy self, O Bestower of life.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 9, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`Like the holy ark and the tabernacle of witness didst thou, O all- immaculate one, receive within thy womb God thy Creator, the Giver of the law, Who by His death hath annulled the law of death.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, canon 2, Ode 9, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`theotokion`}]}},condition:`which we chant when there is no Menaion`}],magnificat_rubric:`We then chant the hymn of the Theotokos (the Magnificat), with the`,post_canon_rubric:`Then, “It is truly meet to bless thee ...,” and a prostration. Small litany, Exapostilarion, and the usual psalms. On the Praises, these Stichera of the holy martyrs, in Tone III:`,praises:{rubric:`On the Praises, these Stichera of the holy martyrs, in Tone III:`,items:[{text:`Come, all ye peoples, let us honor the memory of the holy passion-bearers. For, having become a spectacle to angels and to men, they have received crowns of victory from Christ God, and they ever intercede on behalf of our souls.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, Praises item 1`},label:`martyrs`},{text:`The warriors of Christ cast aside the fear of kings and tyrants; and with courage boldly confessed Him as the Lord and God of all, our God; and now they intercede on behalf of our souls.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, Praises item 2`},label:`plain`},{text:`The hosts of the bodiless angels marveled at the sufferings of the martyrs; For though clad in mortal flesh, they paid no heed to their tortures, following the example of Christ the Savior's Passion; and they ever interceding on behalf of our souls.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, Praises item 3`},label:`plain`},{text:`O race of mankind, why are ye rebellious in vain? Short is the course on which we run. Life is but smoke, vapor, ashes and dust; No sooner doth it appear, than it quickly vanisheth. Wherefore let us cry unto Christ the immortal King: Grant rest to our departed brethren, where all who rejoice have their abode with Thee.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, Praises item 4`},label:`for_the_reposed`}],verses:[{text:`Praise Him for His mighty acts, * praise Him according to the multitude of His greatness.`,tier:2,src:{file:`3-7.pdf`,locus:`Saturday Matins, Praises verse 1`}},{text:`Praise Him with the sound of trumpet, * praise Him with the psaltery and harp.`,tier:2,src:{file:`3-7.pdf`,locus:`Saturday Matins, Praises verse 2`}},{text:`Praise Him with timbrel and dance, * praise Him with strings and flute.`,tier:2,src:{file:`3-7.pdf`,locus:`Saturday Matins, Praises verse 3`}},{text:`Praise Him with tuneful cymbals, praise Him with cymbals of jubilation. * Let every breath praise the Lord.`,tier:2,src:{file:`3-7.pdf`,locus:`Saturday Matins, Praises verse 4`}}],theotokion:{text:`Without seed thou didst conceive by the Holy Spirit; we glorify thee and hymn thy praises: Rejoice, O most holy Virgin!`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, Praises Glory/Both-now Theotokion (§9.12 sic "Even who gave birth" kept verbatim)`},type:`theotokion`,sourceLabel:`Glory ..., Both now ..., Theotokion:`},doxology_rubric:`Small Doxology (Read), Litany: Let us complete ...,`},aposticha:{rubric:`On the Aposticha, these Stichera of the departed, in Tone III:`,items:[{text:`I glorify Thy precious Cross O Lord, whereby life and blessedness have been granted to those who with faith and love hymn Thy praises, O greatly merciful One. Wherefore we cry aloud unto Thee, O Christ God: Grant rest to our departed brethren, where all who rejoice have their abode with Thee.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, aposticha of the departed, item 1`},label:`plain`,homoglyph_log:[{from:`U+041E О (Cyrillic), in spec_mel`,to:`O`,count:1}],spec_mel:`Great is the power of Thy Cross, O Christ`},{text:`Repeat: I glorify Thy precious Cross O Lord ..,`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, aposticha of the departed, item 2`},label:`plain`},{text:`O Christ God Who alone art merciful and compassionate, Who hast an unapproachable abyss of goodness, Who knowest human nature, which Thou didst create, we beseech Thee: Unto those who have been taken from us grant rest where all who rejoice have their abode with Thee.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, aposticha of the departed, item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`When Thou didst rest in the tomb as a man, as God Thou didst raise up with invincible power, those who were sleeping in the graves, and who offer Thee unceasing hymnody. Wherefore, we beseech Thee, O Christ God: Unto those who have been taken from among us grant rest where all who rejoice have their abode with Thee.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, aposticha of the departed, item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`}],verses:[{text:`Blessed are they whom Thou hast chosen * and taken to Thyself, O Lord.`,tier:2,src:{file:`3-7.pdf`,locus:`Saturday Matins aposticha of the departed, verse 1 ("they" — the 2-7 print has "those"; §5 per-tone)`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}]},{text:`Their souls * shall dwell among good things.`,tier:2,src:{file:`3-7.pdf`,locus:`Saturday Matins aposticha of the departed, verse 2`}},{text:`Their memorial * is from generation to generation.`,tier:2,src:{file:`3-7.pdf`,locus:`Saturday Matins aposticha of the departed, verse 3 — "from generation to generation" (2-7: "unto generation and generation"; §5 divergence)`}}]},aposticha_theotokion:{text:`O Theotokos, all of us know thee to be the noetic lamp bearing the Light of the Godhead, Who had united Himself to the coarseness of human nature. Entreat thy Son and God, that unto those who have been taken from among us He grant rest where all who rejoice have jubilation.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Matins, aposticha Glory/Both-now closer`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],type:`theotokion`},closing_rubric:`Then, “It is good to give thanks ...,” Trisagion ..., Our Father ..., Troparia.`}},liturgy_weekday:{mon:{beatitudes:{rubric:`On the Beatitudes, these Troparia, in Tone III:`,items:[{text:`Thou didst banish from paradise our forefather Adam, who had broken Thy commandment, O Christ; but Thou didst cause to dwell therein the thief who confessed Thee on the cross, crying: Remember me, O Savior, in Thy kingdom!`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Liturgy, Beatitudes item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`Overlooking the multitude of mine evils in the multitude of Thy mercy, O Christ, save me, and on the dread day of condemnation deliver me from everlasting torment, O Savior, that I may hymn Thy goodness.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Liturgy, Beatitudes item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`O ye cherubim and seraphim, ye thrones, archangels, powers, principalities, dominions, angels and all authorities, entreat the Creator, that, in that He is the Lover of mankind, He overlook mine offenses when He shall come to judge the earth.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Liturgy, Beatitudes item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Having dyed vesture for themselves in their sacred blood, in a godly manner the spiritual athletes of Christ were truly deemed worthy to reign with the King of the heavenly hosts; and they ask remission of transgressions for us who ever honor them as is meet.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Liturgy, Beatitudes item 4`},label:`martyrs`},{text:`O ye faithful, piously hymning the one Godhead in three Hypostases: the Father, the Son and the Holy Spirit, the Comforter: with the angels let us cry out unceasingly with our voices: Holy, holy, holy art Thou, O God Who savest our souls!`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Liturgy, Beatitudes item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`glory`},{text:`O pure one, thou radiant cloud, who hast given birth to the Light from Light: Guiding to the Light me who have been darkened by the passions and pleasures of life, set me aright, and pray that I may receive the glory which those who lived righteously have now received.`,tier:1,src:{file:`3-2.pdf`,locus:`Monday Liturgy, Beatitudes item 6`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]},prokeimenon:{ref:`shared.daily_liturgy_propers.mon.prokeimenon`},alleluia:{ref:`shared.daily_liturgy_propers.mon.alleluia`},communion:{ref:`shared.daily_liturgy_propers.mon.communion`}},tue:{beatitudes:{rubric:`On the Beatitudes, these Troparia, in Tone III:`,items:[{text:`Thou didst banish from paradise our forefather Adam, who had broken Thy commandment, O Christ; but Thou didst cause to dwell therein the thief who confessed Thee on the cross, crying: Remember me, O Savior, in Thy kingdom!`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Liturgy, Beatitudes item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`I have acquired a soul defiled by the pleasures of life, and, wholly desperate, I approach Thy compassions and earnestly cry out to Thee, O Christ, Who alone knowest the secret things: Cleanse me in Thy loving-kindness, O Lord!`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Liturgy, Beatitudes item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`As the mediator between the Old and the New Covenants, O divine Baptist, having renewed me who have grown old through transgressions, by thy supplications grant that I may walk the paths of repentance without stumbling, for they lead straight to the kingdom of Christ, O all-praised one.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Liturgy, Beatitudes item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`Fighting the good tight, O valiant spiritual athletes, ye endured countless myriads of pangs; and thus ye ever ease the pain of all and dispel the harm wrought by the evil spirits. Wherefore, we glorify you with faith, O holy ones.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Liturgy, Beatitudes item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`martyrs`},{text:`The Unity in three Hypostases is truly light and life, the Creator of all, Whom we glorify; for the Master and Lord is known to be the one God in three Hypostases - the Father, the Son and the Spirit - the Unity which sustain- eth all things.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Liturgy, Beatitudes item 5`},label:`glory`},{text:`O Virgin Mother, have pity on me who ever sin and anger the good God, and by examples of repentance make me steadfast now, in that thou art good, that, having escaped the torments which are to come, I may earnestly hymn thy supplication, O maiden.`,tier:1,src:{file:`3-3.pdf`,locus:`Tuesday Liturgy, Beatitudes item 6`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`both_now`}]},prokeimenon:{ref:`shared.daily_liturgy_propers.tue.prokeimenon`},alleluia:{ref:`shared.daily_liturgy_propers.tue.alleluia`},communion:{ref:`shared.daily_liturgy_propers.tue.communion`}},wed:{beatitudes:{rubric:`On the Beatitudes, these Troparia, in Tone III:`,items:[{text:`Thou didst banish from paradise our forefather Adam, who had broken Thy commandment, O Christ; but Thou didst cause to dwell therein the thief who confessed Thee on the cross, crying: Remember me, O Savior, in Thy kingdom!`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Liturgy, Beatitudes item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`Thou wast crucified and pierced in the side for my sake, O my Jesus, Who pourest forth upon me a twofold stream of salvation; wherefore, saved by Thy suffering, O Christ, I hymn and glorify Thy loving-kindness. In Thy kingdom, remember me who cry out aloud.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Liturgy, Beatitudes item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`Reckoned among the iniquitous, O Jesus, Thou didst take away the iniquities of us all; and crowned with thorns as the King of all, Thou dost cut off the thorns of the sin of our forefather at the root; wherefore, we now glorify Thy suffering with faith.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Liturgy, Beatitudes item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O valiant spiritual athletes, all-glorious martyrs, who emulated the sufferings of Christ and with divine power cast down the deception of the enemy: Ye have received heavenly glory, O saints, praying for us all.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Liturgy, Beatitudes item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`martyrs`},{text:`O Unity of three Hypostases, indivisible and all-accomplishing Trinity, single Essence and Power: From all the harm wrought by the enemy protect those who hymn Thee, and grant us Thy kingdom, which those who live virtuously receive.`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Liturgy, Beatitudes item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`Beholding on the Cross Him Who took flesh of thy pure blood, O maiden Birthgiver of God, thou didst cry out, weeping: “How hath the wicked assembly rewarded Thee, slaying Thee, the life and resurrection of all the faithful?”`,tier:1,src:{file:`3-4.pdf`,locus:`Wednesday Liturgy, Beatitudes item 6`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]},prokeimenon:{ref:`shared.daily_liturgy_propers.wed.prokeimenon`},alleluia:{ref:`shared.daily_liturgy_propers.wed.alleluia`},communion:{ref:`shared.daily_liturgy_propers.wed.communion`}},thu:{beatitudes:{rubric:`On the Beatitudes, these Troparia, in Tone III:`,items:[{text:`Thou didst banish from paradise our forefather Adam, who had broken Thy commandment, O Christ; but Thou didst cause to dwell therein the thief who confessed Thee on the cross, crying: Remember me, O Savior, in Thy kingdom!`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Liturgy, Beatitudes item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`O apostles, who with the Cross as a fishing-pole didst drag men forth from the depths of ignorance, ye drove heathen deception from the earth and were verily true saviors of the faithful; wherefore, ye are blessed.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Liturgy, Beatitudes item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`As mystic rays and lights of the Sun of righteousness, O glorious apostles, ye dispelled the darkness of ungodliness and guided all to the light of the knowledge of God; wherefore, we honor you.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Liturgy, Beatitudes item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Ye endured torture by burning, O spiritual athletes, and received from on high the dew of grace; and as favorites of Christ, O wise ones, ye ever piously heal the sufferings of all; wherefore, we honor you with faith, O saints.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Liturgy, Beatitudes item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:3}],label:`martyrs`},{text:`O sacred preachers of the Trinity: Peter and Paul, Mark and Luke, Matthew, Simon, James, Andrew and John, Thomas, Bartholomew and the wise Philip: entreat God, that we may be delivered from every evil circumstance.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Liturgy, Beatitudes item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`O Lady, full of the grace of God, beauty of the apostles and joy of the holy passion-bearers: Entreat God the Savior on behalf of us all, that we may find remission of transgressions, and may all come to share in life divine.`,tier:1,src:{file:`3-5.pdf`,locus:`Thursday Liturgy, Beatitudes item 6`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]},prokeimenon:{ref:`shared.daily_liturgy_propers.thu.prokeimenon`},alleluia:{ref:`shared.daily_liturgy_propers.thu.alleluia`},communion:{ref:`shared.daily_liturgy_propers.thu.communion`},alleluia_note:`3-5 prints the same digit-zero artifact ("0 Lord") at the same verse as 2-5 — normalized per §9.10 (scan review delivered); post-normalization the print byte-matches shared, so the ref stands.`},fri:{beatitudes:{rubric:`On the Beatitudes, these Troparia, in Tone III:`,items:[{text:`Thou didst banish from paradise our forefather Adam, who had broken Thy commandment, O Christ; but Thou didst cause to dwell therein the thief who confessed Thee on the cross, crying: Remember me, O Savior, in Thy kingdom!`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Liturgy, Beatitudes item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`Beholding Thee, the never-setting Sun, upon the Cross, the sun dimmed its light, the stones split asunder and the earth quaked, O Master and Savior; and the veil of the temple was rent in twain, seeing Thee suffering unjustly, which none can comprehend.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Liturgy, Beatitudes item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Thou wast led forth to die for all, O Jesus, Life of the living, that by Thy divine sufferings Thou mightest as God save those slain by the fruit of old, and mightest show them to be dwellers in paradise; wherefore, we now glorify Thy sufferings with faith.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Liturgy, Beatitudes item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`Emulating the sufferings of Him Who of His own will suffered for our sake and took away the reproaches of men, O martyrs, by your many tortures ye cast down the enemy and received glory on high. Wherefore, ye are glorified in a godly manner.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Liturgy, Beatitudes item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`martyrs`},{text:`O all ye faithful, let us worship the Father, the Son and the upright Spirit, the Comforter: the one Godhead. And let us chant in godly manner and cry out piously with an Orthodox understanding: Remember us in Thy kingdom!`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Liturgy, Beatitudes item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`Beholding her Son on the Cross, enduring suffering in the flesh of His own will, the most immaculate and pure one was wholly troubled and cried out, weeping: “Woe is me, O my Child! How art Thou done to death, Who desirest to bring life to those who have grievously died?”`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Liturgy, Beatitudes item 6`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]},prokeimenon:{ref:`shared.daily_liturgy_propers.fri.prokeimenon`},alleluia:{tone:4,text:{text:`Remember Thy congregation which Thou hast purchased from the beginning.`,tier:1,src:{file:`3-6.pdf`,locus:`Friday Liturgy Alleluia`}},verses:[{text:`God is our King before the ages, * He hath wrought salvation in the midst of the earth.`,tier:2,src:{file:`3-6.pdf`,locus:`Friday Liturgy Alleluia verse — "ages," (the tone-2 print: "ages;"; §5 divergence)`}}]},communion:{ref:`shared.daily_liturgy_propers.fri.communion`}},sat:{beatitudes:{rubric:`On the Beatitudes, these Troparia, in Tone III:`,items:[{text:`Thou didst banish from paradise our forefather Adam, who had broken Thy commandment, O Christ; but Thou didst cause to dwell therein the thief who confessed Thee on the cross, crying: Remember me, O Savior, in Thy kingdom!`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Liturgy, Beatitudes item 1`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`plain`},{text:`Subjected to wounding by fire, O passion-bearers of Christ, ye found the dew of heaven which cooled and strengthened you to endure the bitter pangs in your flesh; wherefore, ye ever ease all the pain of our souls.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Liturgy, Beatitudes item 2`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`The holy and sacred hierarchs, the glorious apostles, the multitude of the venerable, the council of godly women who faithfully suffered, and set at naught the deception of the enemy, have received heavenly glory. By their supplications, O Savior, have pity on Thy servants.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Liturgy, Beatitudes item 3`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`plain`},{text:`O Jesus our God and Savior, in the abodes of Thine elect number those who have departed from us in faith where Thy light shineth, and the sustenance is everlasting, and overlook their offenses, that we may fervently glorify Thee, O Master.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Liturgy, Beatitudes item 4`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:2}],label:`for_the_reposed`},{text:`O ye faithful, let us worship the uncreated Trinity in three Hypostases but a single Godhead: the Father, the Son and the divine Spirit: Who is ever glorified with faith by the incorporeal hosts in three sacred ranks.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Liturgy, Beatitudes item 5`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`glory`},{text:`The Redeemer, enlightenment and cleansing of all revealed Himself through thee, O divinely joyous and most pure Lady. Him do thou earnestly entreat, that at the dread judgment He deliver from all condemnation us who ever hymn Him with faith.`,tier:1,src:{file:`3-7.pdf`,locus:`Saturday Liturgy, Beatitudes item 6`},homoglyph_log:[{from:`U+041E О (Cyrillic)`,to:`O`,count:1}],label:`both_now`}]},prokeimenon:{ref:`shared.daily_liturgy_propers.sat.prokeimenon`},alleluia:{ref:`shared.daily_liturgy_propers.sat.alleluia`},communion:{ref:`shared.daily_liturgy_propers.sat.communion`}}}};export{e as default};